import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святителю Арсенію, єпископу Тверському","e":"Akathist to St Arsenius, Bishop of Tver","secs":[{"h":"Кондак 1","ps":["Ізбра́нний святи́телю Христо́в і преди́вний чудотво́рче, о́тче наш Арсе́ніє! Похва́льноє пі́ніє воспису́єм ті с ві́рою і любо́вію, я́ко те́плому моли́твеннику і предста́телю на́шему: ти же, свя́тче Бо́жий, я́ко імі́яй дерзнове́ніє к Пресвяті́й Тро́йце, от вся́ких бід і скорбе́й моли́твами твої́ми свободи́ ни, тебе́ зову́щия:","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний бил єси́, святи́телю Арсе́ніє, житія́ твоєго́ чистото́ю і пра́ведностію; сего́ ра́ди а́нгелов Творе́ць во вре́менній жи́зні поста́ви тя во архієре́я Тверськи́я па́стви, по блаже́нній же кончи́ні сопричте тя со́нму святи́х небожи́телей, с ни́миже сві́тло водворя́яся ни́ні во оби́теліх ра́йських, сли́шиши от нас сія́ хвале́бния глаго́ли:","Ра́дуйся, Пресвяти́я Тро́йці ві́рний служи́телю;","Ра́дуйся, а́нгельськия чистоти́ ревни́телю.","Ра́дуйся, от пеле́н ма́терніх ізбра́нний сосу́де Бо́жия благода́ті;","Ра́дуйся, от ю́ности твоєя́ всім се́рдцем і душе́ю возлюби́вий Го́спода.","Ра́дуйся, рачи́телю доброді́телей, пожи́вий в ми́рі а́ки безпло́тний;","Ра́дуйся, всего́ себе́ принеси́й в же́ртву живу́, свя́ту і благоуго́дну Бо́гові.","Ра́дуйся, я́ко світи́ло світоза́рноє осія́вий па́ству Тверськую сія́нієм до́брих діл твої́х;","Ра́дуйся, просвіти́вий лю́ди сло́вом і приме́ром равноа́нгельнаго житія́ твоєго́.","Ра́дуйся, правосла́вія тве́рдий храни́телю;","Ра́дуйся, благоче́стія сто́лпе непоколеби́мий.","Ра́дуйся, благи́й ра́бе і ві́рний, вше́дий в ра́дость Го́спода твоєго́;","Ра́дуйся, со а́нгели і всі́ми святи́ми предстоя́й Престо́лу Христо́ву.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дя суєту́ ми́ра сего́ вре́меннаго, от ю́ности восхоті́л єси́ служи́ти Го́сподеві в ді́встві і чистоті́; ті́мже роди́телей твої́х погребе́нію до́брі послужи́в, а́біє все імі́ніє твоє́ ни́щим расточи́л єси́, і дом і град твой оста́вив, ви́шняго гра́да взиска́л єси́ Ієрусали́ма небе́снаго, іді́же от лико́в а́нгельських і всіх святи́х поє́ться немо́лчная піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́нний стяжа́л єси́, свя́тче Бо́жий, чте́нієм писа́ній Боже́ственних, от ю́ности бо напита́л єси́ ду́шу твою́ сла́дкою пи́щею слове́с Бо́жиїх і соді́лался єси́ ві́рним ісполнителем за́повідей Христо́вих. Ті́мже ублажа́єм тя і глаго́лем:","Ра́дуйся, до́брий учениче́ небе́снаго учи́теля Христа́;","Ра́дуйся, богому́дрий ізследователю та́їнств, в зако́ні Бо́жиєм сокрове́нних.","Ра́дуйся, вся кра́сная ми́ра сего́ возненави́дівий;","Ра́дуйся, го́ре устремивий вся по́мисли душі́ твоєя́.","Ра́дуйся, нищія і стра́нния удовли́вий от імі́ній твої́х;","Ра́дуйся, утверди́вий се́рдце твоє́ в любо́в Бо́жию.","Ра́дуйся, самоотверже́нія і преданности Бо́гу о́бразе соверше́нний;","Ра́дуйся, самоосужденія і покаянних слез люби́телю.","Ра́дуйся, я́ко насади́л єси́ в душі́ твоє́й страх Госпо́день;","Ра́дуйся, я́ко приліжа́л єси́ моли́твам усе́рдним і коленопреклоненним.","Ра́дуйся, умиле́нія істо́чниче; Ра́дуйся, кро́тости пра́вило.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́ла Христо́ва осіни́ тя, святи́телю, і дарова́ тебі́ крі́пость му́жественно претерпі́ти іскуше́нія неви́димаго врага́, єго́же стрі́ли разжже́нния угаси́л єси́ сле́зними твої́ми к Бо́гу моли́твами; сего́ ра́ди я́ко побіди́тель воспіва́єши ни́ні со безпло́тними си́лами піснь побі́дную Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Усли́шав глас небе́сний, повелевающ тебі́, да і́деши в дом Пречи́стия Богоро́диці нариця́ємия Пече́рськия, я́ко єле́нь на істо́чники водни́я, устреми́лся єси́ во оби́тель Пече́рськую, я́же в Ки́єві, іді́же преподо́бнії і богоно́снії отці́ Анто́ній і Феодо́сій со ученики́ свої́ми Христу́ благоугоди́ша, і бил єси́ о́ния оби́телі святи́я постриженник і подви́жник до́брий. Ті́мже ни́ні в го́рніх оби́теліх пребива́я со всі́ми преподо́бними Печерськими, сли́шиши от нас такова́я:","Ра́дуйся, ма́слино благопло́дная, на па́жити гор Ки́євських насажде́нная;","Ра́дуйся, ла́ври Пече́рськия сві́тлая похвало́.","Ра́дуйся, вели́ких уго́дников Бо́жиїх Анто́нія і Феодо́сія подража́телю;","Ра́дуйся, всіх преподо́бних пече́рських соревнова́телю.","Ра́дуйся, вся послуша́нія і́ночеськая нелі́ностно проше́дий;","Ра́дуйся, для бра́тії оби́телі потруди́вийся, день і нощ рабо́тая свої́ма рука́ма.","Ра́дуйся, ропта́ніє і праздносло́віє возненави́дівий;","Ра́дуйся, терпі́ніє крі́пкоє і молчаливая уста́ стяжа́вий.","Ра́дуйся, по́мисли го́рдості і превозноше́нія попра́вий;","Ра́дуйся, свято́є смире́ніє Христо́во себі́ усво́ївий.","Ра́дуйся, по́стниче неізнемогающий;","Ра́дуйся, подви́жниче непоколеби́мий.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́рею уни́нія непоколеби́м преби́л єси́, о́тче: впери́в бо ум твой в Боже́ственная, вся по́мисли до́лу влеку́щия низложи́л єси́, і нелі́ностно приліжа́л єси́ трезве́нію і моли́твам непреста́нним, восходя́ от си́ли в си́лу к соверше́нству духо́вному. Ті́мже досто́йно воспіва́л єси́ єще́ на землі́ небе́сную піснь Трийпоста́сному Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дів благопло́дную добро́ту душі́ твоєя́ первосвяти́тель Киприя́н, возлюби́ тя зіло́, Арсе́ніє смиренному́дре, і поста́ви тя во архидия́кона себе́ і сові́тника при́снаго, я́ко да послу́жиши ку́пно с ним Престо́лу Госпо́дню і бу́деши єму́ помо́щник ві́рен в управле́нії па́стви всероссі́йськия. Ті́мже я́ко ізбра́нника Бо́жия честву́єм тя похвала́ми си́ми:","Ра́дуйся, олтаря́ Госпо́дня благогові́йний предстоя́телю;","Ра́дуйся, та́їн Христо́вих досто́йний служи́телю.","Ра́дуйся, первосвяти́теля Киприя́на собесі́дниче і сослужи́телю;","Ра́дуйся, того́ по́двигов і доброді́телей послі́дователю.","Ра́дуйся, в управле́нії, тебі́ ввереннем, пра́вду і ми́лость возлюби́вий;","Ра́дуйся, суди́ пра́ведни і нелицеприятни творивий.","Ра́дуйся, ти́хостію нра́ва украси́вийся;","Ра́дуйся, безкори́стіє і нищету́ духо́вную стяжа́вий.","Ра́дуйся, помо́щниче беспомощним;","Ра́дуйся, засту́пниче си́рим.","Ра́дуйся, хода́таю оби́димим;","Ра́дуйся, защи́тниче напа́ствуємим.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 5","ps":["Во град Твер прибил єси́ ку́пно с первосвятителем Киприя́ном, богому́дре Арсе́ніє, і зді, во оте́чествії твоє́м, яви́лся єси́ я́ко звізда́ многосві́тлая, сія́ющая сві́том богоразу́мія і луча́ми доброді́телей, я́ко диви́тися всім согра́жданом твої́м і воспіва́ти за тя хвале́бную піснь Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя князь і лю́діє Тверстії богоно́сна і всі́ми доброді́тельми укра́шена, проси́ша первосвяти́теля Киприя́на, да поста́вить тя во архієре́я гра́ду Тве́рі, да іді́же рожде́н бил єси́ пло́тію, та́мо і духо́вную па́ству обря́щеши от пастиренача́льника Христа́. Прийми́ у́бо, ієра́рше Христо́в, і от нас, чад і сограждан твої́х, сія́ хвале́бния пі́сні:","Ра́дуйся, гра́да Тве́рі благопло́дная о́трасле і украше́ніє;","Ра́дуйся, па́стви Тверськи́я світи́ло і удобре́ніє.","Ра́дуйся, Єва́нгелія Христо́ва усе́рдний благові́стниче;","Ра́дуйся, апо́стольських преда́ній тве́рдий храни́телю.","Ра́дуйся, сло́ва Бо́жия сладковіща́нний учи́телю;","Ра́дуйся, зако́на Госпо́дня одушевле́нния скрижа́ли.","Ра́дуйся, нището́ю вре́менною бога́тство ві́чноє стяжа́вий;","Ра́дуйся, моли́твами і поще́ньми блаже́нство го́рнєє улучи́вий.","Ра́дуйся, приникший во глубину́ смире́нія;","Ра́дуйся, возше́дий на висоту́ безстра́стія.","Ра́дуйся, вдов і сиро́т благосе́рдий пита́телю;","Ра́дуйся, оби́димих і гони́мих многомо́щний засту́пниче.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 6","ps":["Боготе́чній звізді́, дре́вле путеводи́вшей волхво́в к возсія́вшему Со́лнцю пра́вди Христу́, уподо́бити тя дерза́єм, святи́телю Бо́жий Арсе́ніє. Сло́вом бо твої́м і доброді́тельним житіє́м путь пра́вий ко Христу́ слове́сній па́стві твоє́й указа́л єси́, і бил єси́ путеводи́тель ко спасе́нію мно́гих, і́же наставля́ємі тобо́ю, научи́шася богоприя́тно пі́ти всіх Творцю́ а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ я́ко богосві́тлоє світи́ло на святи́тельстім престо́ле па́стви Тверськи́я, просвіща́я душі́ всіх прибіга́ющих к тебі́, я́ко архієре́ю богоприя́тному, єго́же моли́тва мно́го мо́жеть пред лице́м Вседержи́теля Бо́га. Ті́мже і ми, охраня́ємі твої́ми святи́ми моли́твами, благода́рно тебі́ зове́м:","Ра́дуйся, па́стирю наш і учи́телю;","Ра́дуйся, те́плий о нас грі́шних пред Бо́гом предста́телю.","Ра́дуйся, умиротвори́вий в па́стві твоє́й раздо́ри і нестроє́нія;","Ра́дуйся, бо́дренними твої́ми моли́твами посрами́вий врага́ спасе́нія челові́чеськаго.","Ра́дуйся, правосла́вія і благоче́стія насади́телю;","Ра́дуйся, лжі і вся́каго нече́стія істребителю.","Ра́дуйся, Христу́ уневі́стивий мно́гія душі́ челові́чеськія;","Ра́дуйся, руководи́вий в Ца́рствіє Небе́сноє твоя́ ученики́.","Ра́дуйся, до́брий і неуси́пний ді́лателю виногра́да Христо́ва;","Ра́дуйся, му́дрий і богоприя́тний строї́телю та́їн Бо́жиїх.","Ра́дуйся, ієра́рше всеблаги́й;","Ра́дуйся, архієре́ю пречу́дний.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хоті́нієм возжелі́л єси́, святи́телю о́тче Арсе́ніє, імі́ти в па́стві твоє́й подо́біє святи́я ла́ври Кі́єво-Пече́рськия; ті́мже устро́їл єси́ близ гра́да Тве́рі оби́тель во і́м'я Честна́го Успе́нія Пресвяти́я Богоро́диці і Преподо́бних оте́ць Анто́нія і Феодо́сія Пече́рських, іді́же сонм і́ноков благогові́йних собра́л єси́ му́дре і научи́л єси́ їх сло́вом і благи́м приме́ром твої́м в преподо́бії і святи́ні пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Новосозданная тобо́ю оби́тель, я́ко вертогра́д духо́вний яви́ся, святи́телю богому́дре, єго́же возді́лал єси́ трудолю́бно, бра́тію твою́ назида́я к по́двигом по́стничеським і ко вся́кому доброді́ланію, да бу́дуть соверше́ни і непоро́чни, і да возно́сять немо́лчния хвали́ Христу́ Бо́гу. О сем по до́лгу тя велича́єм і зове́м:","Ра́дуйся, і́ноков люби́телю;","Ра́дуйся, до́брий наста́вниче подвизающимся во бра́ні духо́вній.","Ра́дуйся, ві́рний руководи́телю ше́ствующих ко Го́споду путе́м ті́сним і́ночеськаго житія́;","Ра́дуйся, му́дрий учи́телю христия́нськаго соверше́нства.","Ра́дуйся, лі́ствице, возводя́щая богому́дрих і́ноков на висоту́ соверше́нства духо́внаго;","Ра́дуйся, в по́двизіх неутоми́мий.","Ра́дуйся, на престо́лі святи́тельстім житіє́ і́ночеськоє проводивий;","Ра́дуйся, храм Бо́жий чу́дний во і́м'я Пресвяти́я Богома́тере во оби́телі твоє́й созда́вий.","Ра́дуйся, і себі́ самаго́ храм одушевле́нний сотвори́вий Трийпоста́сному Бо́гу;","Ра́дуйся, всено́щния моли́тви і бді́нія всеусе́рдно соверша́вий.","Ра́дуйся, преподо́бнії ру́ці твої́ со мно́гим дерзнове́нієм к Бо́гу воздвизавий;","Ра́дуйся, єще́ при жи́зні твоє́й да́ром чуде́с обогащенний.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 8","ps":["Странника і прише́льця в жи́зні сей скоротечней помишля́я себі́ би́ти, о́тче наш Арсе́ніє, гроб рука́ма свої́ма із ка́мене устро́їл єси́ і над ним го́рці пла́кал єси́, помишля́я смерть і суд Бо́жий нелицеприя́тний і гро́зний вся́кому земнородному. Ті́мже і нас воздви́гни от сна гріхо́внаго, да подража́єм пла́чу твоєму́ умиленному, і покая́нієм очи́стившеся от вся́кия зло́би, сподо́бимся ку́пно с тобо́ю на небесі́ взива́ти Созда́телю на́шему: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь жела́нієм боже́ственним об'ят бил єси́, святи́телю богоблаже́нне, го́рняя му́дрствуя, а не земна́я, і богомисленним умо́м твої́м ви́ну предстоя́ Бо́гу в моли́твах непреста́нних, яви́лся єси́ вели́кий уго́дник Бо́жий і чудотво́рець, і при́сно предстательствующий о па́стві твоє́й, тебі́ приносящей сія́ похвали́:","Ра́дуйся, свяще́нная главо́, ви́ну го́рняя мудрствующая;","Ра́дуйся, досто́йний носи́телю Бо́жия благода́ті.","Ра́дуйся, врачу́ безме́здний, ту́не врачева́нія расточаяй;","Ра́дуйся, сосу́де драгоці́нний, целебноє ми́ро всім ві́рним бога́тно ізлива́яй.","Ра́дуйся, многотеку́щая ріко́, напоі́вшая се́рдця люде́й твої́х уче́ньми спаси́тельними;","Ра́дуйся, ча́ше всезлата́я, че́рплющая оби́ліє дарова́ній от даропода́теля Христа́ і ороша́ющая душі́ к плодоношенію духо́вному.","Ра́дуйся, о́тче благосе́рдий, подража́яй бла́гости Отця́ Небе́снаго;","Ра́дуйся, ми́лости струє́ неізсяка́ємая.","Ра́дуйся, ра́дости мно́гим хода́таю;","Ра́дуйся, печа́лей і скорбе́й утоли́телю.","Ра́дуйся, многообра́зні украше́нний доброді́тельми;","Ра́дуйся, сві́тло блиста́ющий луча́ми пресла́вних чуде́с.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 9","ps":["А́нгели небе́снії і со́нми святи́х ра́достно восприя́ша тя, єгда́ свята́я душа́ твоя́, ми́рно разріши́вшися от уз пло́ті, восхожда́ше в го́рняя, іді́же сподо́бился єси́ ві́чния сла́ви в невече́рнім дні Ца́рствія Христо́ва, ю́же і нам улучи́ти умоли́ Христа́ Бо́га, да с тобо́ю на землі́ живи́х воспоє́м Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий язи́к челові́чеський не мо́жеть ізрещи́ оби́ліє чуде́с твої́х, святи́телю Бо́жий, я́же при жи́зні і по сме́рті твоє́й істочи́л єси́ і до ни́ні істоча́єши стра́ждущим і неду́жним, враче́бниця бо воі́стину неоску́дная яви́ся свяще́нная твоя́ ра́ка, к не́йже притека́я, нікто́же тощ і неуті́шен от тебе́ ісхо́дить, ю́же благогові́йні обстоя́ще, і ми с любо́вію к тебі́ вопіє́м:","Ра́дуйся, беснуємих от томле́нія дия́вольськаго свободи́вий;","Ра́дуйся, неісці́льно боля́щих уврачева́вий.","Ра́дуйся, сліпи́м зрі́ніє дарова́вий;","Ра́дуйся, німи́м дар сло́ва возврати́вий.","Ра́дуйся, разсла́бленних укріпи́вий;","Ра́дуйся, і мертвеця́ пресла́вно воскреси́вий.","Ра́дуйся, святотатця гро́зно наказавий;","Ра́дуйся, покая́ніє того́ ми́лостиво приє́мий.","Ра́дуйся, без стра́ха Бо́жия жи́вших вразуми́вий;","Ра́дуйся, лише́нним сми́сла ум здра́вий ниспославий.","Ра́дуйся, от страхова́ній вра́жиїх мно́гія ізба́вивий;","Ра́дуйся, і і́на мно́га чудеса́ сотвори́вий.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 10","ps":["Подо́бно вели́кому святи́телю і чудотво́рцю Никола́ю явля́єшися во сні і я́ві, по своє́м преставле́нії, святи́телю о́тче наш Арсе́ніє, ізвіству́я ве́лію благода́ть, да́нную тебі́ от Христа́ Бо́га, і неуси́пноє промишле́ніє твоє́ о спасе́нії жи́тельствующих во святі́й оби́телі твоє́й і всіх с ві́рою притека́ющих к твоєму́ оте́чеському покро́ву. Яви́лся бо єси́ во сні ні́коєму клирику і увіщава́л єго́ не удаля́тися із твоєя́ оби́телі, і я́ві предста́л єси́ благогові́йному єпи́скопу Алексі́ю, я́ко а́нгел Бо́жий, две́рем затворе́нним, вшед в єго́ ке́ллію і помоли́вся іко́ні Спа́совой, кро́тко вопроси́л єго́ о мі́сті пребива́нія архімандрі́та твоєя́ оби́телі. О сем прославля́єм ди́внаго во святи́х Свої́х Бо́га на́шего і вопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і тве́рдоє огражде́ніє гра́да Тве́рі і оби́телі твоєя́ яви́лся єси́, святи́телю о́тче Арсе́ніє. Єгда́ бо лю́тії і злонравнії литвини, разоря́юще гра́ди і ве́сі украї́нськия, доідо́ша до оби́телі твоєя́, і восхоті́вше о́ную расхи́тити, взя́ша покро́в со святи́х і многоціле́бних моще́й твої́х, зла́том і сребро́м украше́нний, і́мже єди́н от них дерзну́ покри́ти коня́ своєго́, но а́біє на висоту́ взе́мшеся, о́ба падо́ша ме́ртви, покро́в же си́лою Бо́жиєю обрі́теся на кресті́ верху́ хра́ма твоєго́, про́чий же, ве́ліїм об'яти стра́хом, біжа́ша, оста́вльше оби́тель твою́ і град Твер невреди́ми. Помина́юще у́бо сіє́ чу́дноє твоє́ заступле́ніє, ра́достно взива́єм к тебі́:","Ра́дуйся, ізбра́нний воєво́до, при́сно гото́вий отража́ти враги́ ви́димия і неви́димия от па́стви твоєя́ земни́я;","Ра́дуйся, гра́да Тве́рі і оби́телі твоєя́ забра́ло несокрушимоє.","Ра́дуйся, щиті́ защища́яй ві́рния;","Ра́дуйся, стіно́ огражда́ющая благочести́вия.","Ра́дуйся, я́ко не попусти́л єси́ бисеру святи́ні попрану би́ти;","Ра́дуйся, я́ко прогна́л єси́ ди́ких вепрей от виногра́да Христо́ва.","Ра́дуйся, я́ко святу́ю оби́тель твою́ нерасхищену от враго́в сохрани́л єси́;","Ра́дуйся, я́ко правосла́вний град оте́чествія твоєго́ невреди́мим соблю́л єси́.","Ра́дуйся, во бра́ніх христолюби́вому во́їнству вели́кий пособниче;","Ра́дуйся, подвизающимся в пості́ і безмо́лвії до́брий споспі́шниче.","Ра́дуйся, неду́жних благода́тний ціле́бниче;","Ра́дуйся, преди́вний чудотво́рче.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє со а́нгельськими чи́ни і всі́ми святи́ми возно́сиши го́ре у Престо́ла Бо́жия, святи́телю о́тче наш Арсе́ніє, і та́мо наслажда́яся блаже́нства неізрече́ннаго, не престає́ши ми́лостивно призира́ти на па́ству твою́ земну́ю, на град Твер і на оби́тель твою́; зри́ши бо на́ші ско́рби і ну́жди, болі́знуєши о на́ших не́мощіх і грісі́х, і те́плі мо́лишися о всіх нас ко Го́споду, подвиза́я і нас недосто́йних во умиле́нії глубо́цім пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник світоза́рний бил єси́, святи́телю Христо́в Арсе́ніє, в жи́зні земні́й, світи́вий па́стві твоє́й сло́вом уче́нія і приме́ром свята́го житія́ твоєго́; но і ни́ні, по сме́рті твоє́й, не престає́ши просвіща́ти нас чудеси́ твої́ми і нетлі́нієм честни́х моще́й твої́х, найпа́че же святи́ми і богоприя́тними моли́твами твої́ми, і́миже огражда́єми, невреди́ми от вся́каго зла пребива́єм і глаго́лем:","Ра́дуйся, ізбра́нниче Бо́жий, єго́же моли́тва мно́го мо́жеть пред благосе́рдієм Влади́ки;","Ра́дуйся, архієре́ю Госпо́день, чу́дне подража́вий в житії́ вели́кому архієре́ю Ісу́су Христу́.","Ра́дуйся, слуго́ Всеви́шняго равноа́нгельний;","Ра́дуйся, я́ко кончи́на твоя́ сла́вна і успе́ніє во святи́х.","Ра́дуйся, осія́нний в го́рніх оби́теліх сла́вою сві́та невече́рняго;","Ра́дуйся, просла́вленний ди́вним нетлі́нієм святи́х моще́й твої́х і мно́гими чудеси́.","Ра́дуйся, благоуха́нієм святи́ні твоєя́ удобри́вий святу́ю Христо́ву Це́рков;","Ра́дуйся, всея́ Украї́нськия страни́ ра́дованіє і утіше́ніє.","Ра́дуйся, покро́ве Бо́гом да́нний, і́мже покрива́ються ві́рнії;","Ра́дуйся, сві́тлий о́блаче, зной страсте́й на́ших утоля́ющий.","Ра́дуйся, роса́ благода́тная, ороша́ющая і веселя́щая на́ша се́рдця;","Ра́дуйся, гра́де прибі́жища, не кри́ющийся от на́шего притека́нія.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 12","ps":["Богоблагода́тния струї́ ісціле́ній істоча́єть свяще́нная ра́ка моще́й твої́х, святи́телю Христо́в Арсе́ніє: сію́ бо дарова́ нам всеблаги́й Бог, я́ко но́вую купі́ль Силоамськую, к не́йже не єди́ножди в лі́то, но во вся́коє вре́м'я притека́юще, неду́гующії духо́вні і тіле́сні оби́льния почерпа́ють ісціле́нія. Ті́мже с любо́вію припа́даєм к ней, і прославля́юще ве́лію ми́лость і неізрече́нноє человіколю́біє Бо́га на́шего, зове́м Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ богоуго́дноє житіє́, вели́кий уго́дниче Бо́жий, о́тче наш Арсе́ніє, сла́вим святу́ю кончи́ну твою́, іспові́дуєм мно́гая чудеса́ твоя́ і вели́коє милосе́рдіє твоє́ к лю́дем, благогові́йно лобиза́єм нетлі́нния і цільбоно́сния мо́щі твоя́, і мо́лим ті ся прилі́жно: не пре́зри, па́стирю наш до́брий і о́тче милосе́рдий, ма́лаго усе́рдія на́шего і любве́, і́миже подвиза́ємі, вопіє́м ті си́це:","Ра́дуйся, арха́нгелов і а́нгелов сослужи́телю;","Ра́дуйся, всіх небе́сних сил сожи́телю.","Ра́дуйся, проро́ком равноче́стне;","Ра́дуйся, апо́столом єдинонра́вне.","Ра́дуйся, му́чеников сонаслі́дниче;","Ра́дуйся, святи́телей красото́.","Ра́дуйся, преподо́бних удобре́ніє;","Ра́дуйся, пра́ведних похвало́.","Ра́дуйся, ко Пресвяті́й Богоро́дице бли́жній предста́телю;","Ра́дуйся, всіх святи́х дру́же.","Ра́дуйся, душ і тіле́с на́ших благода́тноє врачева́ніє;","Ра́дуйся, по Бо́зі і Богоро́дице крі́пкоє на́ше упова́ніє.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 13","ps":["О вели́кий святи́телю і пресла́вний чудотво́рче, о́тче наш Арсе́ніє! Прийми́ ма́лоє сіє́ моле́ніє на́ше, от любве́ те́плия на́ми тебі́ приноси́моє, і умоли́ Вседержи́теля Го́спода ізба́витися нам от вся́кия ско́рби і болі́зні во вре́менній жи́зні сей, і от ві́чних муче́ній по сконча́нії на́шем, да унаслі́дуєм Ца́рство Небе́сноє, і сподо́бимся вку́пі с тобо́ю пі́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний бил єси́, святи́телю Арсе́ніє, житія́ твоєго́ чистото́ю і пра́ведностію; сего́ ра́ди а́нгелов Творе́ць во вре́менній жи́зні поста́ви тя во архієре́я Тверськи́я па́стви, по блаже́нній же кончи́ні сопричте тя со́нму святи́х небожи́телей, с ни́миже сві́тло водворя́яся ни́ні во оби́теліх ра́йських, сли́шиши от нас сія́ хвале́бния глаго́ли:","Ра́дуйся, Пресвяти́я Тро́йці ві́рний служи́телю;","Ра́дуйся, а́нгельськия чистоти́ ревни́телю.","Ра́дуйся, от пеле́н ма́терніх ізбра́нний сосу́де Бо́жия благода́ті;","Ра́дуйся, от ю́ности твоєя́ всім се́рдцем і душе́ю возлюби́вий Го́спода.","Ра́дуйся, рачи́телю доброді́телей, пожи́вий в ми́рі а́ки безпло́тний;","Ра́дуйся, всего́ себе́ принеси́й в же́ртву живу́, свя́ту і благоуго́дну Бо́гові.","Ра́дуйся, я́ко світи́ло світоза́рноє осія́вий па́ству Тверськую сія́нієм до́брих діл твої́х;","Ра́дуйся, просвіти́вий лю́ди сло́вом і приме́ром равноа́нгельнаго житія́ твоєго́.","Ра́дуйся, правосла́вія тве́рдий храни́телю;","Ра́дуйся, благоче́стія сто́лпе непоколеби́мий.","Ра́дуйся, благи́й ра́бе і ві́рний, вше́дий в ра́дость Го́спода твоєго́;","Ра́дуйся, со а́нгели і всі́ми святи́ми предстоя́й Престо́лу Христо́ву.","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нний святи́телю Христо́в і преди́вний чудотво́рче, о́тче наш Арсе́ніє! Похва́льноє пі́ніє воспису́єм ті с ві́рою і любо́вію, я́ко те́плому моли́твеннику і предста́телю на́шему: ти же, свя́тче Бо́жий, я́ко імі́яй дерзнове́ніє к Пресвяті́й Тро́йце, от вся́ких бід і скорбе́й моли́твами твої́ми свободи́ ни, тебе́ зову́щия:","Ра́дуйся, святи́телю Арсе́ніє, усе́рдний моли́твенниче о душа́х на́ших."]},{"h":"Молитва","ps":["При́зри от Го́рних висо́т, святи́телю о́тче Арсе́ніє, на нас смире́нних і грі́шних, во умиле́нії душ і серде́ць к тебі́ прибіга́ющих, ві́рою крі́пкою на тя упова́ющих, любо́вію нелицемі́рною прося́щих у тебе́ заступле́нія. Тебі́ бо моли́твенника благоприя́тнаго ві́ми ко Всеми́лостивому Бо́гу. Проле́й о нас твоя́ святи́я моли́тви і умоли́ Человіколю́бця Го́спода не погуби́ти нас со беззако́нії на́шими, но обрати́ти нас к покая́нію і ісправле́нію, да про́чеє вре́м'я житія́ на́шего земна́го, не в рабо́ті гріху́ і страсте́м, но в ді́ланії за́повідей Єго́ святи́х і в благоче́стії провожда́єм і со благо́ю наде́ждою дости́гнем кончи́ни на́шея. В час же сме́ртний найпа́че яви́ся нам, о́тче, засту́пник благи́й, ускори́ тогда́ на моли́тву о нас безпо́мощних і помози́ нам со прича́стієм Та́їнств Боже́ственних ми́рную і благу́ю кончи́ну улучи́ти, гро́зния мита́рства возду́шния безбі́дно прейти́ і унаслі́довати Го́рнєє Ца́рство. Єй, святи́телю Бо́жий, не пре́зри нас і не посрами́ упова́нія на́шего, но бу́ди о нас предста́тель немо́лчний к Бо́гу. Па́стирю наш до́брий, упаси́ нас бо́дренними твої́ми моли́твами і сохрани́ ненаві́тни от вся́каго зла, да сла́вим неізрече́нноє человіколю́біє Бо́га на́шего, Отця́ і Си́на і Свята́го Ду́ха, і твоє́ оте́чеськоє заступле́ніє, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, вели́кий уго́дниче Бо́жий, святи́телю о́тче Арсе́ніє! Се прино́сим тебі́ хвале́бноє пі́ніє ми, грі́шнії і недосто́йнії ча́да твоя́, і велича́єм по́двиги і доброді́телі твоя́, і мно́гую ми́лость твою́ ко всім с ві́рою притека́ющим к оте́чеському твоєму́ покро́ву. Прийми́ с любо́вію приноше́ніє ві́ри і любве́ на́шея, і принеси́ є Вседержи́телю Бо́гу, от Него́же нисхо́дить вся́коє дая́ніє бла́го і вся́кий дар соверше́нний, і я́коже благоді́тельствовал єси́ в земні́м житії́ твоє́м всім іска́вшим твоєя́ по́мощі, та́ко і ни́ні не лиши́ нас, о́тче благосе́рдий, твоєго́ пред Бо́гом многомо́щнаго заступле́нія. Се бо нетлі́нния і многоціле́бния мо́щі твоя́ дарова́ нам Госпо́дь во увіре́ніє, я́ко ве́ліє дерзнове́ніє і́маши к Нему́ і я́ко мно́го мо́жеть предста́тельство твоє́ пред Престо́лом бла́гости Єго́. Ті́мже не оста́ви нас си́рих і безпо́мощних, но при́сно помина́й нас во святи́х небе́сних твої́х моли́твах. Укріпи́ на́ша стопи́ тве́рдо і непоколеби́мо ходи́ти путе́м за́повідей Госпо́дніх, утверди́ ру́ці на́ша к воздія́нію моли́твенному і к соверше́нію до́брих діл, согрі́й сердця́ на́ша любо́вію ко Го́споду і к жи́зні ві́чній. Іспроси́ у Царя́ Небе́снаго гра́ду Тве́рі і святі́й оби́телі твоє́й благостоя́ніє і всей страні́ Украї́нській ми́лость Бо́жию і сохране́ніє от вся́каго зла. Іспроси́, святи́телю Бо́жий, і всім, с ві́рою прибега́ющим к ра́ці святи́х моще́й твої́х і і́м'я твоє́ благогові́йно призива́ющим, коєму́ждо дар благопотре́бен: неду́гующим ісціле́ніє, бе́дствующим ізбавле́ніє, печа́льним утіше́ніє, заблу́ждшим і́стини позна́ніє, грі́шним ісправле́ніє, подвиза́ющимся преспі́яніє, і всім вся к жи́зні вре́менній і ві́чній потре́бная, во сла́ву ди́внаго во святи́х Свої́х Бо́га, в Тро́йці сла́вимаго і покланя́ємаго, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва третя","ps":["О всехва́льний святи́телю Христо́в і чудотво́рче, о́тче Арсе́ніє! Не забу́ди нас, чад святи́я оби́телі твоєя́ і всіх с ві́рою і любо́вію прибіга́ющих к ра́ці честни́х і многоціле́бних моще́й твої́х, но помина́й нас во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. Моли́ за вся христия́ни, о́тче святи́телю Арсе́ніє, і за святу́ю сію́ оби́тель, ю́же вручи́ тебі́ Пречи́стая Влади́чиця Богоро́диця, мним бо тя ви́ну предстоя́ща Христу́ Бо́гу на́шему і Пречи́стій Єго́ Ма́тері і іму́ща ве́ліє к Ним дерзнове́ніє. А́ще бо ті́лом і преста́вился єси́ от нас, но душе́ю жив сий, неотсту́пен пребива́єши с на́ми ду́хом. Сохраня́й нас твої́м предста́тельством пред Престо́лом Небе́снаго Царя́ от ко́зней вра́жиїх, от собла́знов ми́ра, во злі лежа́щаго, і от вся́кия ско́рби і ну́жди. О преблаги́й па́стирю і учи́телю наш, о́тче Арсе́ніє! К тебі́ припа́даєм і тебі́ мо́лимся, моли́ся всеси́льному Бо́гу о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да очи́стившеся от вся́кия скве́рни гріхо́вния, Небе́сному Ца́рствію наслі́дники сподо́бимся би́ти со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Безнача́льним Єго́ Отце́м і с Пресвяти́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Благоче́стно пожи́во во святи́тельстві, / лю́ди просвіти́л єси́ уче́нієм твої́м, / і о хра́мі Пречи́стия вельми́ подвиза́вся, / і люби́тель мона́хов бив, / сего́ ра́ди от Христа́ па́стви твоєя́ віне́ць прия́л єси́. / Ті́мже, я́ко апо́стольськаго престо́ла намі́стника, / і святи́теля вели́каго чту́ще тя, мо́лим ча́да твоя́, блаже́нне: / от всіх бід ізба́ви нас я́же ко Христу́ моли́твами твої́ми, // святи́телю Христо́в Арсе́ніє, о́тче наш."]},{"h":"Кондак, глас 8","ps":["Восприє́мши ра́достно честни́я твоя́ мо́щі, пречи́стая це́рков, / в ню́же че́стно вноси́ми мно́жеством священномона́хов, і кня́зі благові́рними, / і я́же приє́мши я́ко сокро́вище многоці́нноє. / Ті́мже і ми ни́ні твоєя́ огра́ди слове́сния о́вці, / о́крест ра́ки твоєя́ предстоя́ще, / любе́зно вопіє́м ті: / не забу́ди чад твої́х, о́тче, / ї́хже му́дре собра́л і возлюби́л єси́, / я́ко да зове́м ті: // ра́дуйся, святи́телю Арсе́ніє, па́стирю і учи́телю наш."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Арсе́ніє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст апостолу і євангелісту Марку","e":"Akathist to the Apostle and Evangelist Mark","secs":[{"h":"Кондак 1","ps":["Пресла́вніх апо́стол Петра́ і Па́вла сора́тниче, струя́ми бла́года́ті Госпо́дней напоі́вши оби́льні конці́ ми́ра, святи́й апо́столе Ма́рко, при́зри ни́ні на ни, чту́щия усе́рдно па́м'ять твою́! Укріпи́ сердця́ на́ша Тро́йчеською ві́рою, іспо́лни нас ду́ха прему́дрости, научи́ ра́зуму, обрати́ во ученико́в свої́х, да непреста́нно поє́м бла́года́рственная тебі́, во умиле́нії зову́ще:","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Ікос 1","ps":["Ми́ра созда́телю, Христо́с Бог, па́дшеє во тьму челові́чество, сві́том нетлі́нним просвіща́ти жела́я, тя, блаже́нне апо́столе Ма́рко, із до́ма ма́тері твоєя́ Марі́ї во гра́ді Ієрусали́ме на служе́ніє Себі́ призва́, на ді́ланіє спасе́нія на́шего во мно́гі зе́млі іуде́ом і е́ллином Христа́ расп'я́таго, Бо́жию си́лу і Бо́жию прему́дрость пропові́дати посла́в. Ті́мже і ми, сві́том уче́нія твоєго́ озаря́ємі, се́рдцем і усти́ к тебі́ си́це вопіє́м:","Ра́дуйся, із євре́йська колі́на Леві́їна роди́вийся:","ра́дуйся, от пле́мені свя́ще́нничеськаго Бо́гом ізбра́нний.","Ра́дуйся, в до́мі ма́тері своєя́ Марі́ї, апо́стольськом прибі́жище, Світ узрі́вий:","ра́дуйся, євре́йськи Іоа́нном нарече́нний, лати́нськоє і́м'я Марк во сла́ву Бо́га просвіти́вий.","Ра́дуйся, оби́чаї роди́тельськия почита́вий:","ра́дуйся, ізмла́да і́стинную простоту́ возлюби́вий.","Ра́дуйся, от ю́ности украше́нний доброді́тельми:","ра́дуйся, к ві́рі і упова́нію на Бо́га нас призва́вий.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 2","ps":["В собо́рния труди́ созива́юще ієрусали́млян ві́рующих і апо́стол Бо́жиїх, дом ма́тері твоєя́, святи́й апо́столе, тебі́ ковче́гом духоно́сним і назида́тельним стал, оба́че і ми собо́рность Це́ркві Госпо́дней почита́єм, усе́рдно поя́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум боже́ственний і́мам, при жи́зні земно́й в це́ркві гра́да Госпо́дня сугу́бо чти́мий, твой дя́дя Варна́ва, апо́столе Ма́рко, муж до́брий і іспо́лненний Ду́ха Свята́го і ві́ри, Тро́їчеським про́мислом к апо́столу Па́влу в до́мі ма́тернем теб'я́ прибли́зивий, за таково́є і ми с благогові́нієм умиле́нно вопіє́м сицева́я:","Ра́дуйся, апо́столу Варна́ві по пло́ті і о Бо́зі сро́дниче:","ра́дуйся, в до́мі ма́тернем первоверхо́вних апо́стол Петра́ і Па́вла срі́тивий.","Ра́дуйся, первоверхо́вних апо́стол Петра́ і Па́вла учениче́ став усе́рдний:","ра́дуйся, Ду́ха Свята́го обогати́вийся от апо́стол первоверхо́вних.","Ра́дуйся, я́ко сам стал єси́ обита́лищем Пресвята́го Ду́ха:","ра́дуйся, украше́ніє цілому́дрія.","Ра́дуйся, от Го́спода жре́бій апо́стольства улучи́вий:","ра́дуйся, благові́стія трубо́, основа́нія ве́тхаго ми́ра сокруши́вий.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 3","ps":["Си́лою сви́ше укрепле́ннії, в пе́рвий путь із Антіохі́ї к іуде́ом і волхво́м с апо́столи Па́влом і Варна́вою по́слани Го́сподем би́сте, тебі́, святи́й апо́столе і євангели́сте, с собо́ю взя́вше, нам же укажи́ стезю́ ко Го́споду, вопію́щих: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще прему́дрость ше́ствовати за ста́ршими апо́столи, ти святи́телю Ма́рко, о́стров Кипр с восто́ка на за́пад проше́д пропові́да, тім у́бо і на́ша ду́ші, омраче́нния мра́ком страсте́й ко сві́ту Госпо́дню просвіти́, да восхва́лим ті та́ко:","Ра́дуйся, свиді́телем став пораже́нія сліпото́ю волхва́ Варіїсу́са по сло́ву апо́стола Па́вла:","ра́дуйся, в ма́лую А́зію із Кі́пра со апо́столи Па́влом і Варна́вою проше́ствовавий.","Ра́дуйся, дерза́ющий Про́мисл Бо́жий ісполня́ти, із Пергі́ї во Ієрусали́м возврати́вийся:","ра́дуйся, во свято́м гра́де ко апо́столу Петру́ присоєдини́вийся.","Ра́дуйся, со апо́столом Петро́м в Рим от до́ма ма́терняго ше́ствовати вознаме́ривийся:","ра́дуйся, Це́рков Правосла́вную во гра́ді Ри́мі апо́столу Петру́ соді́йствующе, утверди́вий.","Ра́дуйся, напоі́вий зе́млю ри́мськую струя́ми боже́ственних віща́ній:","ра́дуйся, мно́жество язи́чников ри́мських во́їнами христо́вими утверди́вий.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 4","ps":["Сладча́йшаго Учи́теля ти па́че всіх благ земни́х возлю́бил єси́, что устреми́лся возвісти́ти єго́ о ше́ствії Іу́ди со стра́жники, наготу́ пло́ті своєя́ успе́в покри́ти то́лько покрива́лом, научи́ і нас чрез все житіє́ ко Спаси́телю свої́ стопи́ устремля́ти, вопія́ше Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша, богому́дре Ма́рко, бли́жнії і да́льнії ри́мляне із уст твої́х о Го́споді, ре́вностно возжела́ли в письмена́х обрісти́ сло́во Бо́жиє, ми же к їх мольба́м благода́рственно вопіє́м ті:","Ра́дуйся, в дні разли́чни от апо́стола Петра́ сли́шанноє во Єва́нгеліє ізложи́вий:","ра́дуйся, Єва́нгеліє тобо́ю пи́санноє, второ́й кни́гой Заві́та Госпо́днего яви́ся.","Ра́дуйся, чудеса́ми Боже́ственними во Єва́нгеліє си́лу Тро́йці Свято́й показа́вий:","ра́дуйся, явле́нієм Іоа́нна Крести́теля благовіствова́ніє о Го́споді нача́вий.","Ра́дуйся, про́повідь із пусти́ні іуде́йськой в пусти́ню всей землі́ принеси́й:","ра́дуйся, я́ко рика́ющему льву глас вопію́щаго в пусти́ні уподо́бивий.","Ра́дуйся, сам со львом в Це́ркві Христо́вой показу́ємий:","ра́дуйся, непоколеби́мий сто́лпе, тве́рдо содержа́вий су́щих во ві́рі.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 5","ps":["Сверши́вше труди́ апо́стольскиє в Ри́мі, ісполня́я смире́нно чрез апо́стола Петра́ во́лю Госпо́дню дарова́ти іни́м зе́млем сло́во Бо́жиє, апо́столе Христо́в Ма́рко, научи́ смире́нію і послуша́нію нас грі́шних, пою́щих: Аллилу́я."]},{"h":"Ікос 5","ps":["Не і́щуще сла́ви себі́, но ре́вностно благовіству́яй во сла́ву Христо́ву, святи́й апо́столе Ма́рко, дерзну́вий во град імпера́торов войти́. Тебі́ ми, многогрі́шнії, хвалу́ воспіва́єм:","Ра́дуйся, із Ри́ма в Аквиле́ю для про́повіді сло́ва Бо́жия прише́дий:","ра́дуйся, во гра́ді, возлю́бленнім імпера́торами, о Христі́ расп'я́том бла́говествова́вий.","Ра́дуйся, Аквиле́ю, зла́том с Ри́мом ра́вной, нетлі́нним зла́том сло́ва Бо́жия озари́вий:","ра́дуйся, во́ди мо́ря Адріяти́чеськаго вода́ми Іорда́нськими утверди́вий.","Ра́дуйся, сокро́вищами духо́вними бога́тства Аквиле́ї посрами́вий:","ра́дуйся, в гра́ді сем Це́рков Христо́ву основа́вий.","Ра́дуйся, всім се́рдцем Ісу́са, Си́на Бо́жия возлюби́вий:","ра́дуйся, с усе́рдієм Свято́й Тро́йце зе́мно послужи́вий.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 6","ps":["Боготе́чной звізді́ подо́бен бил єси́, апо́столе Ма́рко, с ра́достію во іуде́йський і язи́чеський Єги́пет Єва́нгеліє Христо́во поне́сший, научи́л єси́ неві́рних ві́ровати в Тро́йцю Єдиносу́щную і ку́пно с тобо́ю воспіва́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Подо́бно Моїсе́ю, ні́когда возвісти́вшему сино́м Ізра́їлевим ізбавле́ніє от і́га Фарао́нова, ти із апо́стол пе́рвим, євангели́сте Ма́рко, во Єги́пті возвісти́л свобо́ду от ра́бства дия́вола, ми же, чту́щи па́м'ять твою́, умиле́нно поє́м:","Ра́дуйся, вели́коє мно́жество жен і муже́й іуде́йських во Єги́пті ко Христу́ приведи́й:","ра́дуйся, зе́рна Єва́нгелія в угото́ванную зако́ном Мойсе́овим зе́млю всади́вий.","Ра́дуйся, утвержде́ніє ві́ри Христо́вой:","ра́дуйся, сто́лпе Це́ркві Бо́жия.","Ра́дуйся, в Александрі́ї єги́петськой Це́рков Христо́ву возведи́й:","ра́дуйся, насади́телю і́стиннаго богопочита́нія.","Ра́дуйся, світи́ло ві́ри Правосла́вния:","ра́дуйся, всего́ ро́да Христия́нськаго украше́ніє.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 7","ps":["Узрі́л єси́, апо́столе Ма́рко, во о́бразі Челові́честім Влади́ку ми́ра і Си́на Бо́жия, от первоверхо́вних апо́стол открове́ніє о Го́споді возлюби́в. Сего́ ра́ди і ми, іспові́данію твоєму́ вня́вше, поє́м та́ко: Аллилу́я."]},{"h":"Ікос 7","ps":["Ра́зум неуразумі́нний вразумля́я о Святі́й Тро́йці, побо́рниче іспові́данія Правосла́вния ві́ри, святи́й апо́столе Ма́рко, із Антіохі́ї со святи́ми Па́влом і Варна́вою ше́ствовати во втори́й путь с про́повідію Христо́вой вознаме́ривийся. Сего́ ра́ди ві́рнії научи́шася воспіва́ти тебі́:","Ра́дуйся, про́мислу Бо́жию на тебі́ по ісхо́ді із Антіохі́ї сверши́вшемуся:","ра́дуйся, ше́ствовати да́ліє ку́пно, отка́з апо́стола Па́вла получи́вий.","Ра́дуйся, с дя́дею свої́м апо́столом Варна́вою в Кипр возврати́вийся:","ра́дуйся, в сі́ні до́ма роди́тельськаго от стра́нствій до вре́мені почива́вий.","Ра́дуйся, богоозаре́нний іспові́дниче неізрече́нния Боже́ственния сла́ви:","ра́дуйся, мир віща́нієм воплоти́вшагося Бо́жия сло́ва озари́вий.","Ра́дуйся, мре́жею бла́года́ті нас із сує́ть ми́ра любо́вію возводя́щий:","ра́дуйся, уче́ній небе́сних бла́говеща́нний сказа́телю.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 8","ps":["Та́йнам Ца́рствія Бо́жия науче́нний, па́ки во Єги́пті благовіству́я, апо́столе Ма́рко, апо́стола Петра́ срі́тивий, омраче́нния гріхми́ ду́ші на́ша просвіти́, да воспря́нем є́же пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь огне́м Боже́ственния любве́ іспо́лненний, в терпі́нії стяжа́в Дух Святи́й, Бо́гом води́мий десни́цею своє́ю Єва́нгеліє Госпо́днє напису́я, апо́столе Ма́рко, апо́стола Петра́ во Вавило́ні для трудо́в но́вих срі́тивий, ми же, любо́вію твоє́ю побіжда́ємі, дерза́єм зва́ти тебі́ такова́я:","Ра́дуйся, апо́столу Петру́ усе́рдно подража́вий:","ра́дуйся, со апо́столом Петро́м Це́рков Христо́ву во Вавило́ні єги́петстім созда́вий.","Ра́дуйся, апо́столе Пе́тре, в хра́мі том пе́рвоє посла́ніє к малази́йцем сотвори́вий:","ра́дуйся, апо́столе Ма́рко, дру́же врата́ря ра́йськаго, отве́тшаго Спа́су, ти єси́ Христо́с, Син Бо́га Жива́го.","Ра́дуйся, собра́том став апо́столу, ключи́ Ца́рствія Небе́снаго стяжа́вшаго:","ра́дуйся, Христо́во Єва́нгеліє в себі́ воплоти́вий.","Ра́дуйся, ко сві́ту тайн Бо́жиїх приниця́ющий:","ра́дуйся, сло́ва Бо́жия усе́рдний із'ясни́телю.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 9","ps":["Си́лою сви́ше осіне́нний, апо́столе Ма́рко, гони́телей свято́й ві́ри не устраши́вийся, благове́стничеськия труди́ заточе́ннаго во у́зи в Ри́мі апо́стола Па́вла разділи́вий, ві́ру Христо́ву велегла́сно прославля́я, ті́мже поя́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния не довлі́ють ізглаго́лати чистоту́ духо́вную, ю́же імі́л ти, апо́столе Ма́рко, і нас научи́ ві́рі крі́пцій, с любо́вію зову́щих ті:","Ра́дуйся, Па́влом, во дні заточе́нія, колосса́єм о тебі́ писа́вшим, я́ко о своє́м уте́шителе:","ра́дуйся, і́мже сотру́дником свої́м для Ца́рствія Бо́жия нарече́нний.","Ра́дуйся, указа́ніє ше́ствовати із Ри́ма в Ма́лую А́зію іспо́лнивий:","ра́дуйся, во фригі́йський град Коло́сси прише́дий.","Ра́дуйся, лжеучи́телем, прельща́вшим колоссі́йських христия́н, противоде́йственниче:","ра́дуйся, іуде́єв і е́ллинов просвіти́телю.","Ра́дуйся, тридне́внаго сме́рти і воскре́снія Божества́ бла́говести́телю:","ра́дуйся, кро́тости і воздержа́нія учите́лю.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ род челові́чеський, сам благові́стником на стезя́х Бо́жиїх ста́вий, в прилі́жнім послуша́нії апо́столу Па́влу ві́рен до конця́ би́вий, поя́ Тро́йце Пресвяті́й: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго, Єго́же славосло́в'ять херуви́ми і серафи́ми, житіє́м, ві́рою і любо́вію всеусе́рднійший служи́тель бил єси́, апо́столе Ма́рко, первоверхо́вним апо́столом Па́влом пред кончи́ною єго́ во у́зах бил призва́нний, Того́ ра́ди ра́достно зове́м ті:","Ра́дуйся, посла́ніє апо́стола Па́вла к Тимофе́ю іспо́лнивий:","ра́дуйся, со апо́столом Тимофе́єм із Ма́лой А́зії в Рим на по́мощ Па́влу поспіши́вий.","Ра́дуйся, свиді́телем му́ченичеськой кончи́ни обої́х учи́телей свої́х яви́вийся:","ра́дуйся, вели́каго апо́стола Па́вла, ри́мськаго граждани́на, усекнове́нним узрі́вий.","Ра́дуйся, первоверхо́внаго апо́стола Петра́, ра́сп'ята на кресті́ созерца́вий:","ра́дуйся, плоть свою́ ко страда́нієм за Христа́ угото́вавий.","Ра́дуйся, сле́зи за гріхи́ на́ша пред Го́сподем пролія́вий:","ра́дуйся, учи́телей свої́х в Ца́рствії Бо́жиєм срі́тивий.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце с первоверхо́вними апо́столи возда́л єси́, апо́столе Ма́рко, сло́вом, умо́м і живи́м всего́ себе́ в же́ртву принесе́нієм: подража́я бо расп'я́тому за ни непоро́чному А́гнцю Христу́, положи́л єси́ ду́шу свою́ за дру́ги своя́ во́лею. Ті́мже благода́рні су́ще, поє́м ди́вному во святи́х: Аллилу́я."]},{"h":"Ікос 11","ps":["До послі́дняго часа́ своєго́ науча́ти любві́ Госпо́дней і сло́ва Бо́жия устремле́нний, апо́столе Ма́рко, па́ки во Єги́пет после убіє́нія учи́телей свої́х стопи́ напра́вивий, просвіща́єши бо сердца́ ві́рних і к ра́зуму Боже́ственному вся наставля́єши, поуча́я і нас ве́село взива́ти:","Ра́дуйся, во Єги́пет воздви́гнутий тобо́ю храм благоустра́ївать напра́вивийся:","ра́дуйся, в Александрі́ї средото́чіє гре́чеськаго уче́нія в зна́тнем книгохрани́лище во сла́ву Христо́ву употреби́вий.","Ра́дуйся, іуде́єв, увле́кшихся гре́честей уче́ностію, к зна́нієм христия́нським приведи́й:","ра́дуйся, христия́нськоє учи́лище в Александрі́ї основа́вий.","Ра́дуйся, учи́лище сіє́, знамени́тими учи́тельми і отця́ми Це́ркві просла́вивший:","ра́дуйся, в забо́ті о слу́жбі церко́вній чин Боже́ственния Литургі́ї соста́вивий.","Ра́дуйся, із Александрі́ї пропове́дать Христа́ в А́фрику, Ли́вию і іни́м язи́ком путь предприя́вий:","ра́дуйся, во Єги́пті про́повіді твої́ вро́вень с мле́ком ма́тері христия́не употреби́ша.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия соблюда́ше тя, апо́столе Ма́рко, а́ки Петр і Па́вел Єва́нгеліє возвіща́л єси́, сло́вом Христо́вим ві́рния утіша́я. І та́ко упа́сл єси́ Це́рков да́же до дне, єгда́ язи́чники зли́я в храм ворва́вшеся с намі́ренієм погуби́ти тя, неуста́нно взива́л ко Го́споду: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще многотру́дния по́двиги за Христа́, всехва́льний апо́столе Ма́рко, хва́лим єва́нгельськия труди́ твоя́, ублажа́єм му́ченичеськую кончи́ну, почита́єм свяще́нную па́м'ять твою́ і в похвалу́ сицева́я тебі́ зове́м:","Ра́дуйся, пе́рвий єпи́скопе це́ркві Александри́йстій:","ра́дуйся, Александрі́ї первому́чеником явле́нний.","Ра́дуйся, е́ллинськоє божество́ се́раписа Свято́ю Па́схою разруши́вий:","ра́дуйся, в Пра́здник Христо́вой Па́схи е́ллинами уму́ченний.","Ра́дуйся, а́нгелом Госпо́днім в темни́ці на по́двиг укрепле́нний:","ра́дуйся, істе́рзанний, вслід за а́нгелом от Самого́ Го́спода утіше́ніє прия́вий.","Ра́дуйся, во втори́й день лю́тою толпо́ю доро́гами гра́да влаче́нний, дух от мук іспусти́вий:","ра́дуйся, я́ко ті́ло твоє́ не дал єси́ Госпо́дь огне́м сожещи́, громо́м с мо́лнієй злора́дних е́ллинов вразумля́я, і христия́ном пречи́стую плоть погреба́ти благослови́вий.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 13","ps":["О всехва́льний благові́стниче апо́столе і євангели́сте Ма́рко! Внемли́ у́бо воздиха́нію серде́ць на́ших, моля́щихся тебі́, учите́лю і архіпа́стирю, мно́го бо мо́жеть моли́тва святи́х апо́стол пред Бо́гом: научи́ нас потщі́теся і па́м'ятовати о небе́снім зва́нії і христия́нстій кончи́ні жи́зні на́шея, привлеци́ ни ко сла́дости єва́нгельськия і́стини, свяжи́ у́зами любве́ Христо́ви, да ми всі, отве́ргшеся нече́стія і мирськи́х по́хотей, вни́дем в ра́дость Го́спода на́шего, пою́ще Єму́ с тобо́ю і со всі́ми апо́столи: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Ми́ра созда́телю, Христо́с Бог, па́дшеє во тьму челові́чество, сві́том нетлі́нним просвіща́ти жела́я, тя, блаже́нне апо́столе Ма́рко, із до́ма ма́тері твоєя́ Марі́ї во гра́ді Ієрусали́ме на служе́ніє Себі́ призва́, на ді́ланіє спасе́нія на́шего во мно́гі зе́млі іуде́ом і е́ллином Христа́ расп'я́таго, Бо́жию си́лу і Бо́жию прему́дрость пропові́дати посла́в. Ті́мже і ми, сві́том уче́нія твоєго́ озаря́ємі, се́рдцем і усти́ к тебі́ си́це вопіє́м:","Ра́дуйся, із євре́йська колі́на Леві́їна роди́вийся:","ра́дуйся, от пле́мені свя́ще́нничеськаго Бо́гом ізбра́нний.","Ра́дуйся, в до́мі ма́тері своєя́ Марі́ї, апо́стольськом прибі́жище, Світ узрі́вий:","ра́дуйся, євре́йськи Іоа́нном нарече́нний, лати́нськоє і́м'я Марк во сла́ву Бо́га просвіти́вий.","Ра́дуйся, оби́чаї роди́тельськия почита́вий:","ра́дуйся, ізмла́да і́стинную простоту́ возлюби́вий.","Ра́дуйся, от ю́ности украше́нний доброді́тельми:","ра́дуйся, к ві́рі і упова́нію на Бо́га нас призва́вий.","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Кондак 1","ps":["Пресла́вніх апо́стол Петра́ і Па́вла сора́тниче, струя́ми бла́года́ті Госпо́дней напоі́вши оби́льні конці́ ми́ра, святи́й апо́столе Ма́рко, при́зри ни́ні на ни, чту́щия усе́рдно па́м'ять твою́! Укріпи́ сердця́ на́ша Тро́йчеською ві́рою, іспо́лни нас ду́ха прему́дрости, научи́ ра́зуму, обрати́ во ученико́в свої́х, да непреста́нно поє́м бла́года́рственная тебі́, во умиле́нії зову́ще:","Ра́дуйся, святи́й апо́столе Ма́рко, во Єва́нгелії Христа́ пропові́дниче."]},{"h":"Молитва","ps":["О пресла́вний апо́столе і єва́нгели́сте Ма́рко, ду́шу за Христа́ преда́вий і кро́вію твоє́ю па́жить Єго́ удобри́вий! При́зри на нас, чад Госпо́дніх многогрі́шних, всіх зді ни́ні предстоя́щих і моля́щихся (імена́), моли́тви і воздиха́нія сердця́ми сокруше́нними ни́ні принося́щих.","Се бо беззако́ньми омрачи́хомся, і того́ ра́ди біда́ми, я́коже ту́чами, обложи́хомся, єле́я же до́браго житія́ обнища́хом зіло́, і не возмо́жем проти́витися во́лком хи́щним, і́же расхища́ти наслі́діє Бо́жиє де́рзостно тща́ться.","О, всехва́льний апо́столе і єва́нгели́сте Ма́рко! Просвіти́ нас сві́том Свята́го Єва́нгелія Госпо́дня, вразуми́ істреби́ти не́мощі на́ша, помоги́ не отлуча́тися от Го́спода Спа́са на́шего, да не разлучи́мся в коне́ць от любве́ Бо́жия, но крі́пким заступле́нієм твої́м нас защити́, да поми́луєть Госпо́дь всіх нас моли́тв твої́х ра́ди, да вразуми́ть сло́вом Свої́м і рукописа́ніє безмі́рних гріхо́в на́ших істреби́ть, і да сподо́бит со всі́ми святи́ми апо́столи во блаже́нном Ца́рствії воспіва́ти Пресвяту́ю і Неразді́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, і ни́ні і при́сно і во ві́ки віко́в! Амі́нь."]},{"h":"Тропар, глас 3","ps":["У верхо́внаго Петра́ научи́вся, / апо́стол Христо́в бил єси́ / і, я́ко со́лнце страна́м возсія́л єси́, / Александрі́ом удобре́ніє бив, блаже́нне: / тобо́ю Єги́пет от пре́лести свободи́ся, / єва́нгельським твої́м уче́нієм просві́щ вся, / я́ко світ, столп церко́вний. / Сего́ ра́ди твою́ па́м'ять чту́ще, сві́тло пра́зднуєм, / Ма́рко, Богогла́се, / моли́ тобо́ю благовісти́маго Бо́га, // да согріше́ній оставле́ніє пода́сть душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["С висоти́ приї́м благода́ть Ду́ха, / ри́торськая плете́нія разруши́л єси́, апо́столе, / і, язи́ки вся улови́в, Ма́рко всесла́вне, / твоєму́ Влади́ці приве́л єси́, // Боже́ственноє пропові́дав Єва́нгеліє."]},{"h":"Величання","ps":["Велича́єм тя, / апо́столе Христо́в Ма́рко, / і чтим болі́зні і труди́ твоя́, ї́миже труди́лся єси́ // во благові́сти Христо́ві."]}],"notes":[]},{"u":"Акафіст святителю Ігнатію (Брянчанінову), єпископу Кавказькому","e":"Akathist to St Ignatius (Brianchaninov), Bishop of the Caucasus","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Небе́сним Царе́м і от Него́ просла́вленний, святи́телю о́тче Ігна́тіє, ни́ні всечестну́ю твою́ па́м'ять пра́зднующе, мо́лим тя усе́рдно: путево́дствуй нас на путі́ спасе́нія, ізба́ви от враг ви́димих і неви́димих, от скорбе́й і болі́зней, да с любо́вію зове́м ті:","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели удивля́хуся житію́ твоєму́, святи́телю о́тче Ігна́тіє, ка́ко ти от літ ма́лих к Бо́гу ве́ліє раче́ніє імі́л єси́ і по за́повідем Єго́ житіє́ твоє́ неукло́нно проводи́л єси́. Див'я́щеся таково́му благоразу́мію твоєму́, со умиле́нієм взива́єм ті:","Ра́дуйся, скорб'я́щих безча́дних роди́телей твої́х рожде́нієм свої́м уті́шивий;","ра́дуйся, ро́да честна́го о́трасль прекра́сная.","Ра́дуйся, А́нгела-храни́теля твоєго́ непреста́нноє весе́ліє;","ра́дуйся, роди́телей і наста́вников твої́х своє́ю кро́тостію і поко́рностію удиви́вий.","Ра́дуйся, от літ младе́нчеських ко і́ночеському послуша́нію себі́ приугото́вивий;","ра́дуйся, ду́шу свою́ младе́нчеськую к Бо́гу устреми́вий.","Ра́дуйся, в моли́тві і богоми́слії о́трочеськия своя́ досу́ги проводи́вий;","ра́дуйся, для ме́ньших бра́тій і се́стер твої́х примі́р моли́тви і послуша́нія би́вий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 2","ps":["Ви́дяще роди́телі твої́ вели́кая твоя́ дарова́нія, посла́ша тя в ца́рствующий град, да обу́чен бу́деши к восприя́тію во́їнськаго зва́нія. Ти же, ізбра́нниче Бо́жий, юн сий лі́ти, ста́рець же му́дрий ра́зумом, вся сія́ я́ко тлі́нна і скоропреходя́ща почита́ше, к єди́ній же Красоті́ і Сла́дости неізрече́нній — Го́споду Ісу́су Христу́ умо́м і се́рдцем устремля́лся єси́, поя́ Єму́: Аллилу́я!"]},{"h":"Ікос 2","ps":["Ра́зум боже́ственний от возлю́бленнаго тобо́ю Спа́са Христа́ прия́л єси́, Ігна́тіє досточу́дне, єгда́ єще́ о́трок сий, во всіх ви́димих о́бразіх ми́ра сего́ ру́ку Небе́снаго Творця́ і Промисли́теля проразумева́л єси́. Ті́мже прославля́юще тя, вопіє́м ті си́це:","Ра́дуйся, во ви́димих явле́ніїх приро́ди Неви́димаго Бо́га созерца́вий;","ра́дуйся, тишину́ і уєдине́ніє пусти́нноє возлюби́вий.","Ра́дуйся, от літ о́трочеських к Бо́гу ве́ліє раче́ніє імі́вий;","ра́дуйся, вся кра́сная і сла́дкая ми́ра сего́ презрі́вий.","Ра́дуйся, мзду небе́сную от Го́спода восприє́мий;","ра́дуйся, моли́тву Ісу́сову непреста́нно твори́вий.","Ра́дуйся, соверше́нную любо́в ко Го́споду показа́вий;","ра́дуйся, возлю́бленнаго тобо́ю Ісу́са ви́ну в се́рдці твоє́м носи́вий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго осене́н бил єси́, о́тче преблаже́нне, єгда́ вся, я́же в ми́рі сем за бла́га почита́ються, отве́ргл єси́ і, по за́повіді Христа́ Спаси́теля, взем крест, невозвра́тно Єму́ послі́довал єси́, непреста́нно поя́ в се́рдці твоє́м: Аллилу́я!"]},{"h":"Ікос 3","ps":["Імі́я в душі́ своє́й пла́менноє жела́ніє мир оста́вити і Христу́ послі́довати, не убоя́лся єси́ ні гні́ва царе́ва, ні преще́ній оте́чеських і, єще́ в ми́рі живи́й, і́ночеським житіє́м себі́ украси́л єси́. Ті́мже, почита́я му́жество твоє́ і любо́в к Сладча́йшему Го́споду Ісу́су, ублажа́єм тя си́це:","Ра́дуйся, во мла́дости твоє́й адама́нтову тве́рдость ду́ха прояви́вий;","ра́дуйся, єженеде́льнаго приобще́нія Святи́х Христо́вих Та́їн, я́ко велича́йшаго сокро́вища, жела́вий.","Ра́дуйся, на небесі́х ни́ні Христа́ приобща́яйся, я́коже вожделі́л єси́, єще́ сий на землі́;","ра́дуйся, я́ко сі́м'я Бо́жиє, всі́янноє в до́брую зе́млю се́рдця твоєго́, оби́льними слеза́ми ороша́л єси́.","Ра́дуйся, я́ко посреді́ мирськи́х пле́вел, стори́чний плод доброді́телей Го́споду прине́сл єси́;","ра́дуйся, чистоти́ душе́вния і тіле́сния усе́рдний храни́телю.","Ра́дуйся, цілому́дрія ди́вноє украше́ніє;","ра́дуйся, я́ко благолі́піє ли́ка твоєго́ о душе́вній красоті́ твоє́й свиді́тельствоваше.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 4","ps":["Бу́ря помишле́ній сумни́тельних не поколеба́ тя, Ігна́тіє блаже́нне, єгда́ гні́ва царе́ва не убоя́вся, чин во́їнський оста́вил єси́ і, под'є́м на ся і́го Христо́во і мир с собла́знами єго́ презрі́в, в пусти́ню всели́лся єси́ і та́мо жела́нний поко́й душі́ своє́й стяжа́в, немо́лчно піл єси́ Бо́гу: Аллилу́я!"]},{"h":"Ікос 4","ps":["Єгда́ сли́шано бисть во оте́честві твоє́м, я́ко ти, юн сий лі́ти, лі́потою і дарова́ньми украше́н, сла́ву ми́ра сего́ і сла́дости єго́ возненави́дів, в пусти́ню удали́лся єси́, всі сро́дниці твої́ вельми́ удивля́хуся, А́нгели же на небесі́ возра́довашася зіло́ і просла́виша Бо́га, восхи́тившаго тя от су́єтнаго путі́ мирська́го і поста́вившаго на ті́сний путь і́ночеський, веду́щий в Ца́рство Небе́сноє. Ми же, похваля́юще святу́ю ре́вность твою́ о Го́споді, зове́м ті:","Ра́дуйся, зва́нію во́їна царя́ земна́го зва́ніє во́їна Царя́ Небе́снаго предпочти́й;","ра́дуйся, на іскуше́нія от ми́ра, пло́ті і дия́вола находя́щая, крі́пко ополчи́вийся.","Ра́дуйся, ору́жієм Бо́жиїм, Кресто́м Христо́вим, вся ко́зні вра́жия побіди́вий;","ра́дуйся, броне́ю пра́ведности облече́нний.","Ра́дуйся, шлем спасе́нія восприє́мий;","ра́дуйся, меч духо́вний, є́же єсть глаго́л Бо́жий, па́че вся́каго челові́чеськаго ору́жія возлюби́вий.","Ра́дуйся, щито́м ві́ри от стріл лука́ваго себі́ огради́вий;","ра́дуйся, чи́на а́нгельськаго блаже́нство неізрече́нноє в Черто́зі Небе́снім получи́вий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́бен бил єси́, Ігна́тіє преподо́бне, єгда́ предста́л єси́ пред ігу́меном оби́телі да́льнія і ску́дния, прося́ прия́ти тя в число́ бра́тії. Ігу́мен же, іспита́в тя, нічто́же вопреки́ глаго́лаше, благослови́ тя на нача́ло і́ночеськаго путі́ твоєго́. Ти же, улучи́в ча́яній твої́х заве́тних сбитіє́, благода́рні воспіва́л єси́ во умиле́нії благоді́ющему тебі́ Бо́гу: Аллилу́я!"]},{"h":"Ікос 5","ps":["Вся бра́тія оби́телі удивля́шеся, зря́ще вели́коє тща́ніє твоє́ во ісполне́нії послуша́ній, і́миже іспи́товаше твоє́ смире́ніє духо́вний оте́ць твой. Ми же, почита́юще по́двиги і труди́ твоя́, во млади́х лі́тіх во́лею Христа́ ра́ди под'я́тия, умиле́нно вопіє́м ті:","Ра́дуйся, крест свой на ра́мена под'є́мий і Христу́ послі́довавий;","ра́дуйся, у́зький і приско́рбний путь житія́ мона́шеськаго во́лею ізбра́вий.","Ра́дуйся, всп'ять ніколи́же обрати́вийся;","ра́дуйся, смире́нієм свої́м дух горди́ні низложи́вий.","Ра́дуйся, тала́нт свой в землі́ не сокри́вий;","ра́дуйся, во сла́ву Бо́жию і на спасе́ніє душ челові́чеських єго́ употреби́вий.","Ра́дуйся, богому́дрими писа́ньми твої́ми мно́гия ду́ші, во грісі́х погря́зшия, оживи́вий;","ра́дуйся, сла́дкий глас Небе́снаго Домовлади́ки: «Ра́бе благи́й і ві́рний, вни́ди в ра́дость Господи́на твоєго́» усли́шавий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 6","ps":["Смире́нієм, посто́м, найпа́че же непреста́нною моли́твою на стра́сті плотські́я крі́пко воєва́л єси́, святи́телю, до́ндеже плоть твою́ ду́хові порабо́тил єси́, і сего́ ра́ди ни́ні предстої́ши с ли́ки А́нгел престо́лу Пресвяти́я Тро́йці, ви́ну воспіва́я: Аллилу́я!"]},{"h":"Ікос 6","ps":["Возсія́ в тебі́ оби́льно благода́ть Бо́жия, єгда́ ти, чин а́нгельський восприї́м, вско́рі са́ном свяще́нства почте́н бил єси́. Дух же твой, прия́тий во об'я́тія О́тча, тебі́ отве́рстая, блаже́нство неізрече́нноє вкуси́. Єгда́ же ізбра́ тя Госпо́дь во ігу́мена оби́телі Пе́льшемськия, ти о слове́сних овця́х твої́х, тебі́ Бо́гом вруче́нних, де́нно і но́щно пе́клся єси́, да ні єди́на от них поги́бнеть нераде́нія ра́ди твоєго́. Таково́му Бо́жию о тебі́ промишле́нію ра́дующеся, зове́м ті:","Ра́дуйся, в прия́тії а́нгельського чи́на заверше́ніє ча́яній твої́х узрі́вий;","ра́дуйся, небе́сному покрови́телю твоєму́, священному́ченику Ігна́тію Богоно́сцю, подража́вий.","Ра́дуйся, я́коже і он, Го́спода Ісу́са Христа́ в се́рдці твоє́м ви́ну носи́вий;","ра́дуйся, сан свяще́нства, я́ко вели́кий дар Бо́жий, приє́мий.","Ра́дуйся, огню́ тезоимени́тий, огне́м ві́ри і любве́ к Бо́гу і бли́жнім пламене́вий;","ра́дуйся, с благогові́нієм вели́ким і стра́хом Безкро́вную Же́ртву приноси́вий.","Ра́дуйся, Пренепоро́чную Ма́тер Христа́ Бо́га на́шего я́ко Чисті́йшую Святи́ню і Сокро́вище Сла́ви Бо́жия благогові́йно почита́вий;","ра́дуйся, храм благоукраше́нний во і́м'я Ми́лостивия Врата́рници во оби́телі воздви́гнувий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь, да не сокри́т бу́деть світи́льник доброді́телей твої́х, но да сві́тить всім, да просла́в'ять Отця́ Небе́снаго всі челові́ци, ви́дящії тя, ізведе́ тя із оби́телі пусти́нния на многотру́дная послуша́нія. Сему́ Бо́жию промишле́нію див'я́щеся, со умиле́нієм зове́м: Аллилу́я!"]},{"h":"Ікос 7","ps":["Но́вій оби́телі преподо́бнаго Се́ргия близ ца́рствующаго гра́да дарова́ тя Госпо́дь, я́ко предстоя́теля і до́браго па́стиря, неуси́пно о слове́снім ста́ді своє́м пеку́щагося і о благолі́пії оби́телі ревну́ющаго. Сего́ ра́ди і сла́в'яше тя бра́тія твоя́, взива́юще си́це:","Ра́дуйся, небе́сному покрови́телю оби́телі твоєя́ подража́вий;","ра́дуйся, ди́вними хра́ми і строє́ньми сію́ украси́вий.","Ра́дуйся, я́ко оте́ць чадолюби́вий ча́да твоя́ по путі́ спасе́нія в Ца́рствіє Небе́сноє веди́й;","ра́дуйся, жа́ждавшия вступи́ти на путь і́ночеський с любо́вію во оби́тель прийма́вий.","Ра́дуйся, провини́вшіяся і́ноки увещева́ньми свої́ми к сле́зному раска́янію приводи́вий;","ра́дуйся, я́ко па́стир до́брий житіє́м і нра́вом всей бра́тії примі́р по́двига і́ночеськаго подава́вий.","Ра́дуйся, за спасе́ніє їх ду́шу свою́ положи́ти гото́вий;","ра́дуйся, мона́шествующих сла́во і похвало́.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 8","ps":["Стра́нник і пришле́ць на землі́ бил єси́, святи́телю, я́коже про́чії челові́ци. Оба́че Госпо́дь от літ младе́нчеських ізбра́ тя, я́ко уго́дника Своєго́, житіє́м бо і богодухнове́нними писа́ньми твої́ми Го́споду усе́рдно послужи́л єси́. Ми же хвалу́ возсила́юще ко Благоді́ющему тебі́ Бо́гу, вопіє́м Єму́: Аллилу́я!"]},{"h":"Ікос 8","ps":["Весь доброді́телі іспо́лненний, воі́стину бил єси́ во пло́ті А́нгел, святи́телю Ігна́тіє, всіх притека́вших к тебі́ с любо́вію прийма́я, в ско́рбі їх утіша́я, на путь покая́нія наставля́я, непреста́нній моли́тві і пла́чу серде́чному науча́я. Сего́ ра́ди бога́тії і бі́днії, зна́тнії і убо́зії лю́діє, духо́вная ча́да твоя́, взива́ху ті:","Ра́дуйся, но́вий Златоу́сте, о́гненними словеси́ твої́ми мно́гия заблу́ждшия к Бо́гу приведи́й;","ра́дуйся, богому́дрими писа́ньми твої́ми вся і́щущия спасе́нія просвіти́вий.","Ра́дуйся, за враги́ своя́ моли́тися наставля́вий;","ра́дуйся, і сам за враги́ твоя́ с те́плою любо́вію моли́вийся.","Ра́дуйся, во вражду́ющих на нас ору́жіє Бо́жиє ко ісправле́нію на́шему разумі́ти учи́вий;","ра́дуйся, Єзекі́їни сле́зи і Манассі́їни воздиха́нія духо́вним очесе́м ка́ющихся представля́вий.","Ра́дуйся, по́двиги і труди́ подви́жников дре́вніх в богому́дрих творе́ніїх твої́х ізобрази́вий;","ра́дуйся, в житії́ твоє́м всеці́ло їм подража́вий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 9","ps":["Все во́їнство а́нгельськоє і святи́телей лик удиви́шася, зря́ще тя, но́ваго уго́дника Бо́жия, вели́кими труди́ і по́двиги просія́вшаго. Ми же, ублажа́юще тя, просла́вльшему тя Бо́гу вопіє́м: Аллилу́я!"]},{"h":"Ікос 9","ps":["На но́воє многотру́дноє послуша́ніє в да́льній край Оте́чества на́шего отше́л єси́, святи́телю Ігна́тіє, єгда́ жезл архієре́йський от Предві́чнаго Архієре́я, Го́спода на́шего Ісу́са Христа́, вручи́ тебі́ архипа́стир ца́рствующаго гра́да в собо́рі во і́м'я Цари́ці Небе́сния. Разумі́юще в сем во́лю Бо́жию, да і в чужде́й страні́ пропові́стся тобо́ю Єва́нгеліє Ца́рствія Бо́жия, смире́нно зове́м ті:","Ра́дуйся, в хиротоні́ї оби́льно благода́ть Боже́ственную восприє́мий;","ра́дуйся, апо́стольськаго уче́нія іспо́лненний і вся ві́рния спаси́тельними струя́ми єго́ напая́яй.","Ра́дуйся, ві́рний ді́лателю виногра́да Христо́ва;","ра́дуйся, цівни́це златостру́нная Ду́ха Свята́го.","Ра́дуйся, архієре́єв богодухнове́нноє украше́ніє;","ра́дуйся, я́ко уста́ми твої́ми провіщава́ше возлю́бленний тобо́ю Госпо́дь.","Ра́дуйся, духо́вних бра́тій і чад твої́х во оби́телі преподо́бнаго Се́ргия, а́ще і ті́лом оста́вивий, оба́че в моли́твах твої́х їх ніколи́же заби́вий;","ра́дуйся, всім ві́рним і неві́рним, призива́ющим тя на по́мощ, ми́лостивий засту́пниче.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 10","ps":["Не́мощію тіле́сною і по́двигами житія́ утружде́нний, во оби́тель свята́го Никола́я удали́лся єси́, святи́телю Ігна́тіє, хотя́ ду́шу твою́ ко отше́ствію от ми́ра сего́ угото́вати, іді́же в богоми́слії і моли́тві уєдине́нній дні твоя́ скончава́я, піл єси́ немо́лчно Бо́гові: Аллилу́я!"]},{"h":"Ікос 10","ps":["Ско́рий помо́щник і уті́шитель бил єси́, святи́телю Ігна́тіє, не то́кмо к тебі́ приходя́щим, но і дале́че су́щим, писа́ньми твої́ми їх утіша́я, дух їх ободря́я і вразумля́я. Сего́ ра́ди і возглаша́ють ті всі чту́щії богому́драя творе́нія твоя́:","Ра́дуйся, па́стирю наш до́брий;","ра́дуйся, приходя́щих к тебі́ ніколи́же отвраща́яйся.","Ра́дуйся, прося́щия твоєя́ по́мощі бли́жнія і да́льнія любо́вію своє́ю об'є́мляй;","ра́дуйся, чту́щия со тща́нієм писа́нія твоя́ в тісні́йшеє єдине́ніє с душе́ю твоє́ю приє́мляй.","Ра́дуйся, ча́да своя́ духо́вная христия́нському терпі́нію учи́вий;","ра́дуйся, в страда́ніїх на́ших промишле́ніє Бо́жиє о спасе́нії на́шем ви́діти наставля́яй.","Ра́дуйся, всеці́ло преда́тися Про́мислу Бо́жию ча́да своя́ научи́вий;","ра́дуйся, соверше́нія над на́ми во́лі Єго́, я́ко ми́лости вели́кия, проси́ти у Го́спода запові́давий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє приноси́л єси́ Пресвяті́й Тро́йце во вся дні земна́го житія́ твоєго́, Ігна́тіє всехва́льне. Ни́ні же предстоя́ престо́лу Царя́ Сла́ви, моли́ся о нас, чту́щих святу́ю па́м'ять твою́, да моли́твою і покая́нієм очи́стившеся, с тобо́ю ку́пно во ві́ки віко́во воспоє́м Бо́гу: Аллилу́я!"]},{"h":"Ікос 11","ps":["Світи́льник вели́кий Святи́я Правосла́вния Це́ркве в житії́ твоє́м бил єси́, святи́телю Ігна́тіє, і сего́ ра́ди дарова́ тебі́ Вседержи́тель Госпо́дь кончи́ну чу́дну і просла́ви тя на небесі́х. Про́сим тя, святи́телю ми́лостивий, іспроси́ і нам грі́шним, твоєя́ по́мощі і предста́тельства взиску́ющим, кончи́ну житія́ на́шего ми́рну і безболі́зненну, до́брий отві́т на Стра́шнім Суди́щі Христо́ві і Ца́рства Небе́снаго наслі́діє, да зове́м ті ра́достно:","Ра́дуйся, пра́ведною кончи́ною пра́ведность житія́ твоєго́ запечатлі́вий;","ра́дуйся, бли́зость отше́ствія твоєго́ предуві́дівий.","Ра́дуйся, со світи́льником горя́щим Небе́снаго Жениха́ душі́ твоєя́ срі́тивий;","ра́дуйся, в день кончи́ни твоєя́ с жена́ми-мироно́сицями Воскре́сшаго Спаси́теля узрі́вий.","Ра́дуйся, чту́щих тя і по сме́рті ніколи́же своєго́ предста́тельства лиша́яй;","ра́дуйся, вся усе́рдно тебі́ моля́щіяся благода́тію і попече́нієм свої́м покрива́яй.","Ра́дуйся, тве́рдо держа́тися єди́ния і́стинния святи́я правосла́вния ві́ри ча́да твоя́ учи́вий;","ра́дуйся, вся прельще́нія єрети́чеськая прийма́ти і увіща́нієм їх лука́вим внима́ти стро́го запрети́вий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 12","ps":["Благода́ть даде́ся ті от Бо́га, святи́телю Христо́в Ігна́тіє, моли́тися за ни і путево́ждствовати нас на путі́ спасе́нія, да, покая́нієм очище́ни, в Черто́г Спа́сов преукраше́нний вни́дем і та́мо с тобо́ю і со всі́ми угоди́вшими Бо́гу ра́достно воспоє́м Єму́: Аллилу́я!"]},{"h":"Ікос 12","ps":["Пою́ще Бо́га, ди́внаго во святи́х Свої́х, хва́лим тя, Ігна́тіє блаже́нне, я́ко дру́га Христо́ва, блаже́нство ра́йськоє неукло́нним творе́нієм за́повідей Госпо́дніх стяжа́вшаго. Моли́ о нас грі́шних, да і ми о́бщници с тобо́ю ве́чері Госпо́дней бу́дем, умиле́нно зову́ще ті:","Ра́дуйся, глубоча́йшим смире́нієм твої́м, нището́ю духо́вною Ца́рство Небе́сноє обріти́й;","ра́дуйся, доброді́тель сію́ во основа́ніє всіх по́двигов і́ночеських полага́ти запові́давий.","Ра́дуйся, во пла́чі о грісі́х свої́х Сами́м Го́сподом уті́шенний;","ра́дуйся, за кро́тость душі́ твоєя́ наслі́діє жи́зні ві́чния получи́вий.","Ра́дуйся, в земні́м житії́ пра́вди Христо́вой іска́вий, ни́ні же на небесі́х є́ю оби́льно насища́яйся;","ра́дуйся, за милосе́рдіє твоє́ к бли́жнім от Бо́га Щедрода́вця поми́лованний.","Ра́дуйся, за ангелоподо́бную чистоту́ се́рдця твоєго́ Бо́га узрі́вий;","ра́дуйся, вся клевети́ і поноше́нія ненави́дящим тя Го́спода ра́ди проща́вий і за сіє́, я́ко миротво́рець, вели́каго сокро́вища — усиновле́нія Бо́гу сподо́бивийся.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 13","ps":["О преди́вний уго́дниче Христо́в, святи́телю о́тче Ігна́тіє! Прийми́ сіє́ ма́лоє, оба́че от лю́б'ящих і чту́щих тя серде́ць приноси́моє ті моле́ніє і ізба́ви нас твої́м всемо́щним предста́тельством от вся́кия ско́рби, болі́зні і печа́лі, согрі́й охладе́вшия ду́ші на́ша огне́м ві́ри і любве́ к Бо́гу, да́руй нам пре́жде конця́ покая́ніє, бу́ди нам к Ца́рствію Небе́сному путево́ждь, да та́мо с тобо́ю і со всі́ми угоди́вшими Бо́гу во ві́ки віко́в поє́м Єму́: Аллилу́я!","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели удивля́хуся житію́ твоєму́, святи́телю о́тче Ігна́тіє, ка́ко ти от літ ма́лих к Бо́гу ве́ліє раче́ніє імі́л єси́ і по за́повідем Єго́ житіє́ твоє́ неукло́нно проводи́л єси́. Див'я́щеся таково́му благоразу́мію твоєму́, со умиле́нієм взива́єм ті:","Ра́дуйся, скорб'я́щих безча́дних роди́телей твої́х рожде́нієм свої́м уті́шивий;","ра́дуйся, ро́да честна́го о́трасль прекра́сная.","Ра́дуйся, А́нгела-храни́теля твоєго́ непреста́нноє весе́ліє;","ра́дуйся, роди́телей і наста́вников твої́х своє́ю кро́тостію і поко́рностію удиви́вий.","Ра́дуйся, от літ младе́нчеських ко і́ночеському послуша́нію себі́ приугото́вивий;","ра́дуйся, ду́шу свою́ младе́нчеськую к Бо́гу устреми́вий.","Ра́дуйся, в моли́тві і богоми́слії о́трочеськия своя́ досу́ги проводи́вий;","ра́дуйся, для ме́ньших бра́тій і се́стер твої́х примі́р моли́тви і послуша́нія би́вий.","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Кондак 1","ps":["Ізбра́нний Небе́сним Царе́м і от Него́ просла́вленний, святи́телю о́тче Ігна́тіє, ни́ні всечестну́ю твою́ па́м'ять пра́зднующе, мо́лим тя усе́рдно: путево́дствуй нас на путі́ спасе́нія, ізба́ви от враг ви́димих і неви́димих, от скорбе́й і болі́зней, да с любо́вію зове́м ті:","Ра́дуйся, святи́телю Ігна́тіє, покая́нія і моли́тви ді́лателю і учи́телю ізря́дний!"]},{"h":"Молитва","ps":["О вели́кий і пречу́дний уго́дниче Христо́в, святи́телю о́тче Ігна́тіє! Ми́лостиво прийми́ моли́тви на́ша, с любо́вію і благодаре́нієм тебі́ приноси́мия! Усли́ши нас, си́рих і безпомо́щних, к тебі́ с ві́рою і любо́вію припа́дающих і твоєго́ те́плаго предста́тельства о нас пред Престо́лом Го́спода Сла́ви прося́щих. Ві́ми, я́ко мно́го мо́жеть моли́тва пра́ведника, Влади́ку умилостивля́ющая. Ти от літ младе́нчеських Го́спода пла́менно возлюби́л єси́ і Єму́ єди́ному служи́ти восхоті́в, вся кра́сная ми́ра сего́ ні во что́же вміни́л єси́. Ти, отве́ргся себе́ і взем крест твой, Христу́ послі́довал єси́. Ти путь у́зький і приско́рбний житія́ і́ночеськаго ізбра́л єси́ і на сем путі́ доброді́телі вели́кия стяжа́л єси́. Ти писа́ньми твої́ми сердца́ челові́ков глубоча́йшаго благогові́нія і поко́рности пред Всемогу́щим Творцо́м ісполня́л єси́, грі́шников же па́дших му́дрими словеси́ твої́ми в созна́нії своєго́ нічто́жества і своєя́ грехо́вности, в покая́нії і смире́нії прибіга́ти к Бо́гу наставля́л єси́, ободря́я їх упова́нієм на Єго́ милосе́рдіє. Ти ніколи́же притека́вших к Тебі́ отверга́л єси́, но всім оте́ць чадолюби́вий і па́стир до́брий бил єси́. І ни́ні не оста́ви нас, усе́рдно тебі́ моля́щихся і твоєя́ по́мощі і предста́тельства прося́щих. Іспроси́ нам у Человіколюби́ваго Го́спода на́шего здра́віє душе́вноє і тіле́сноє, утверди́ ві́ру на́шу, укріпи́ си́ли на́ша, ізнемога́ющия во іскуше́ніїх і ско́рбіх ві́ка сего́, согрі́й огне́м моли́тви охладе́вшая сердця́ на́ша, помози́ нам, покая́нієм очи́стившимся, христия́нськую кончи́ну живота́ сего́ получи́ти і в Черто́г Спа́сов преукраше́нний вни́ти со всі́ми ізбра́нними і та́мо ку́пно с тобо́ю покланя́тися Отцю́ і Си́ну і Свято́му Ду́ху во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Правосла́вія побо́рниче, / покая́нія і моли́тви ді́лателю і учи́телю ізря́дний, / архієре́єв богодухнове́нноє украше́ніє, / мона́шествующих сла́во і похвало́: / писа́нії твої́ми вся ни уцілому́дрил єси́. / Цівни́це духо́вная, Ігна́тіє богому́дре, / моли́ Сло́ва Христа́ Бо́га, / Єго́же носи́л єси́ в се́рдці твоє́м, // дарова́ти нам пре́жде конця́ покая́ніє."]},{"h":"Кондак, глас 8","ps":["А́ще і соверша́л єси́ стезю́ житія́ земна́го, святи́телю Ігна́тіє, / оба́че непреста́нно зрел єси́ зако́ни битія́ ві́чнаго, / сему́ поуча́я ученики́ словеси́ мно́гими, // і́мже послі́довати і нам, свя́тче, помоли́ся."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Ігна́тіє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст благовірному великому князю Дмитру Донському","e":"Akathist to the Right-Believing Grand Prince Demetrius of the Don","secs":[{"h":"Кондак 1","ps":["Ізбра́нному воєво́ді землі́ Ру́ськия свято́му благові́рному вели́кому кня́зю Дими́трію благода́рственная пі́нія прино́сим ми, си́нове і дще́рі украї́нськия, я́ко ізба́вившему Русь Святу́ю от і́га і наше́ствія ага́рянскаго і призва́вшаго мно́гія ру́ськия лю́ди свя́то стоя́ти за ві́ру Христо́ву, за Оте́чество Правосла́вноє і за дру́ги своя́, і душей не страши́тися сме́рті тіле́сной за ві́ру Бо́жию і всегда́ готовими би́ти положи́ти на по́лі бра́ні глави́ своя́. Сего́ ра́ди с ві́рою і любо́вію вопіє́м:","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Ікос 1","ps":["А́нгельськоє от млади́х ногте́й стяжа́в житіє́, свя́те кня́же Дими́тріє і от ю́ности возлюби́в Бо́га, воспита́н у́бо бисть во благоче́стії с наставленіями душеполезними. Ті́мже прославля́юще Го́спода, возне́сшаго в слав'янських земля́х ізбра́нника Божієго і воєво́ду ди́внаго, вопіє́м та́ко:","Ра́дуйся, кня́же Дими́тріє, благоче́стіє от роди́телей унаслі́довавий.","Ра́дуйся, кро́тостію нра́ва украше́нний.","Ра́дуйся, слав'янський род імі́вий от святи́я вели́кия равноапо́стольния княги́ні О́льги.","Ра́дуйся, пречестна́я лі́торасль свята́го вели́каго равноапо́стольнаго кня́зя Влади́мира.","Ра́дуйся, правнук яви́вийся свято́му вели́кому кня́зю Алекса́ндру Не́вскому.","Ра́дуйся, благомужество і му́дрость сего́ восприя́вий.","Ра́дуйся, ізмла́да Бо́га возлюби́вий.","Ра́дуйся, Єму́ єди́ному себ'я́ всеці́ло преда́вий.","Ра́дуйся, вся́кую пра́здность возненави́дівий.","Ра́дуйся, доброді́телі христия́нськия в се́рдці своє́м носи́вий.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 2","ps":["Ви́дя святи́тель моско́вський Алексі́й ю́ность о́трока Дими́трія сиротствующего і заменивше єму́ єго́ роди́теля, яви́лся я́ко друг богому́дрий і ско́рий сові́тник юнну кня́зю Дими́трію Іоанновичу. Сего́ же архієре́я Бо́жия Алексі́я, за добро́ту душі́ єго́ зіло́ любля́ху всі, найпа́че же почита́ху єго́ в до́мі великокняжеськом, та́ко Бо́гу пещи́ся ізво́лившему о благоче́стії наслі́дника престо́ла моско́вськаго Дими́трія, єму́ же поє́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум вели́кий дарова́л ті Госпо́дь от ю́ности твоєя́, вели́кий кня́же Дими́тріє. І́бо єгда́ ізи́де вели́кий князь Іоа́нн с тобо́ю і мно́гим духовенством і наро́дом за град Москву́ на встречу первосвяти́теля своєго́, возвратившагося із татарськой Орди, ти рекл єси́, ю́ний кня́же святи́телю Бо́жию та́ко: \"Влади́ко, что воздади́м ті за труди́ твоя́? Ти да́руєши нам живо́т ми́рен.\" Помина́я сіє́ пра́ведноє смире́ніє і почита́ніє святи́теля Бо́жия, со умиле́нієм вопіє́м ті:","Ра́дуйся, смире́ніє Христо́во стяжа́вий.","Ра́дуйся, горди́ню дия́вольськую дале́че от себ'я́ отгна́вий.","Ра́дуйся, по успе́нії роди́теля своєго́ к святи́телю Алексі́ю приліпи́вийся.","Ра́дуйся, к среді́ ру́ськаго подви́жничества ізді́тська приобщи́вийся.","Ра́дуйся, детство своє́ под покро́вом митрополи́та-ста́рця проведший.","Ра́дуйся, я́ко окормитель твой друго́м преподо́бному Се́ргію пребива́вий.","Ра́дуйся, обще́ніє і єдиноми́сліє со ученика́ми сего́ свята́го ігу́мена імі́вий.","Ра́дуйся, я́ко Бо́жиє Провиденіє дарова́ ті пестунов і му́дрих сові́тников.","Ра́дуйся, я́ко моли́твами їх дух твой укріпля́шеся.","Ра́дуйся, на вели́коє служе́ніє Всеви́дящим Бо́гом предизбранний.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 3","ps":["Си́лой сви́ше укріпля́ємий святи́й благові́рний кня́же, єгда́ святи́тель Алексі́й благослови́ тебі́ по успе́нії вели́каго кня́зя Іоа́нна путеше́ствіє в Орду Мамаєву соверши́ти, даби́ свої́ми очи́ма узрі́ти ага́рян зіло́ мучивших наро́д ру́ський бо́ліє ста літ. Ми же благодаря́ще Бо́га, да́вшему ті такову́ю любо́в к Оте́честву земно́му, поє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я, свя́те Дими́тріє, в се́рдці своє́м ві́ру крі́пкую, наде́жду несумні́нную, любо́в і́стинную ко Творцю́ Бо́гу вся́чеських, посему́ і возлюби́л єси́ кня́же, благослове́нную Зе́млю Ру́ськую, на ней же рожде́н і воспита́н бисть во ві́рі правосла́вной, разділя́я вся тяготи́ і ско́рби с людьми́ землі́ своєя́. І Бог взира́я на се́рдці ізбра́нника своєго́, болезнующего о сла́ві Русі́ Свято́й, соді́ла тя вели́ким князе́м моско́вським. Ми же радующієся сему́, вопіє́м:","Ра́дуйся, о́трок сущ лі́тами, му́дростію же зіло́ украше́нний.","Ра́дуйся, Бо́гу ті поспішеству́ющу, дре́вній обряд вокняженія восприя́вий.","Ра́дуйся, под руководством святи́теля Алексі́я ра́зум держа́внаго прави́теля приобріти́й.","Ра́дуйся, сто́льний град Москву́ возви́сивий.","Ра́дуйся, Московськоє княжество укріпи́вий.","Ра́дуйся, я́ко свято́ю Влади́мирською іко́ною святи́тель Алексі́й на великокняженіє тя благослови́вий.","Ра́дуйся, в єдиноми́слії єдинодержавія Святу́ю Русь сплотивий.","Ра́дуйся, усе́рдний попечи́телю во вели́ком і спаси́тельном ді́лі би́вий.","Ра́дуйся, у́ме чи́стий, Бо́га зря́щий.","Ра́дуйся, благи́я жела́нія седрця своєго́ єди́ному Го́споду посвящавий.","Ра́дуйся, святи́тельськоє благослове́ніє Божієго архієре́я на вся́коє до́броє ді́ло бра́ша.","Ра́дуйся, і́бо на всіх твої́х великокняженських діла́х благода́ть святи́теля Алексі́я почива́ше.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́яй дванадесятилетній князь, Бо́жий о́трок Дими́трій, єгда́ взем в немощни́я свої́ ру́ці корми́ло правле́нія госуда́рства Ру́ськаго, повсю́ду же раздробленнаго, теснимаго ізвні́ і́гом магометан і возмущаємаго і раздираємаго вну́тренним междуусобієм меж князьми́ і прости́м людом. Кто возмо́жеть ізрещи́ мно́гія ско́рби і страда́нія под'ятия на ра́мена твоя́, свя́те кня́же Дими́тріє? Ми же вопіє́м ко Го́споду Бо́жиїх Сил: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша благові́рний князь, свято́й Дими́трій, я́ко суть нестроє́нія в Суздальськом кня́жестве і соблаговоли ско́ро укріпи́ти сою́з с се́ю земле́ю через вінча́ніє с княжною Євдокиєю, даби́ положить зача́ло возвише́нію Москви́ в до́брой сла́ві. І́бо та́ко яви́ся во́ля Бо́жия благоче́стно упрочити кня́зю Дими́трію семейними у́зами со́бственний дом. Ми же див'я́щеся му́дрости княжеськой, вопіє́м си́це:","Ра́дуйся, я́ко супру́га твоя́ подви́жничеськоє житіє́ на землі́ провожда́ше.","Ра́дуйся, я́ко тріє́ ча́да твої́ креще́ніє от вели́каго ігу́мена Се́ргия прия́ша.","Ра́дуйся, я́ко в цілому́дрії і свя́тості с супру́жницею пожи́вий.","Ра́дуйся, мно́гія а́лчущия хлі́бом княжеським ще́дро напита́вий.","Ра́дуйся, мно́гія жаждущия до́брі напоі́вий.","Ра́дуйся, оби́димих покрови́телю.","Ра́дуйся, сиро́т призрі́ніє.","Ра́дуйся, вдов заступле́ніє.","Ра́дуйся, наги́х одія́ніє.","Ра́дуйся, Землі́ Ру́ськия печа́льниче.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́бен бил єси́, святи́й благові́рний кня́же Дими́тріє, обходя́ Зе́млю Ру́ськую і спаса́я єя́ от враго́во вні́шніх і вну́тренних. І осо́бо при́сния кня́жества: Ніжегородськоє, Рязанськоє і Тверськоє. Ми же хва́лим Бо́га, да́вшему ті ра́зум духо́вний і вопіє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Ві́дуще благові́рний князь Дими́трій вку́пі со святи́телем Алексі́єм, я́ко суть многочи́сленни по́лчища Ольгерда литовськаго движущієся чрез Ру́ськую Зе́млю к Москві́ і вся́кия непотребства творя́ща на путі́ своє́м, не попусти́ша єго́, но затвори́шася в стольнем гра́де Москві́ і помоли́шася Бо́гу. Борзя́ся при́йде же Ольгерд литовський і смути́ єго́ вид ка́меннаго Кремля моско́вськаго і посліди́ тріє́х дній возврати́ся всп'ять. Ми же ви́дяще сію́ си́лу моли́тв вели́каго кня́зя і святи́теля Бо́жия, вопіє́м всі:","Ра́дуйся, я́ко Бог ті во бра́ніх не то́кмо земни́х, но і духо́вних помога́ше.","Ра́дуйся, я́ко ві́рою Христо́вою всіх враго́в Оте́чества своєго́ превозмогаше.","Ра́дуйся, і ни́ні Правосла́вной Украї́нській страні́ крі́пкий стра́же.","Ра́дуйся, я́ко всі святі́ї землі́ Ру́ськия ті помога́ху і моли́твами свої́ми от ко́зней вра́жеських ограждаху.","Ра́дуйся, пра́вим путе́м ви́ну ше́ствовавий.","Ра́дуйся, святи́теля Алексі́я во всю жизнь свою́ помо́щником себі́ імі́вий.","Ра́дуйся, я́ко же го́рести і ра́дости с ним вку́пі разділи́вий.","Ра́дуйся, благоду́шно вся посила́ємия іспита́нія от Бо́га прийма́вий.","Ра́дуйся, с Новуградом і Псковом сою́з чрез кня́зя Влади́мира заключи́вий.","Ра́дуйся, я́ко князья Смоле́нський і Брянський за по́мощ Литве досто́йноє Господнєє наказа́ніє претерпі́ша.","Ра́дуйся, я́ко си́лою духо́вною тя Всеблаги́й Бог снабдивий.","Ра́дуйся, я́ко ти сподо́бился єси́ ві́рним сино́м Свято́й Сла́ви Бо́жієй Русі́ би́ти наслі́дником.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 6","ps":["Пропові́дуєть страна́ Украї́нськая по́двиги твоя́ і болі́зні, под'ятия ра́ди земна́го Оте́чества і бли́жніх. Єгда́ Тверськой князь Михаї́л ізи́де к Мамаю проси́ти ярлик для своєго́ великокняженія. Ти же ніка́коже сего́ убоя́хся, но предаваясь на во́лю Бо́жию, піл єси́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л а́ки со́лнце вели́коє в Ру́ськой страні́, свя́те кня́же Дими́тріє, праведностью і благому́жеством свої́м. Сего́ ра́ди, боя́ся тя злочести́вий хан Мамай. І мно́гажди наблюдахом за тобо́ю, устраши́лся, я́ко ти не восхочеши дань платити. Посему́ і пригласи́ тя во град Влади́мир на великопрестольноі вінча́ніє Михаї́ла, ти же сіє́ приглашеніє му́жественно отве́ргл єси́. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, я́ко би богоблажен єси́, і́бо Єди́наго Го́спода Ісу́са Христа́ крі́пці возлюби́вий.","Ра́дуйся, на Него́ же все упова́ніє своє́ возложи́вий.","Ра́дуйся, я́ко святи́й великому́ченик Дими́трій Солунський явле́йся твої́м небе́сним покровителем.","Ра́дуйся, я́ко і о́ний сей святи́й бисть на землі́ Ру́ськой воєво́дою.","Ра́дуйся, град Влади́мир Тверсько́му кня́зю не отда́вий.","Ра́дуйся, в Переяславлі своя́ ра́тники поста́вивий.","Ра́дуйся, я́ко по сло́ву Госпо́дню му́дрость змії́ну в управле́нії Моско́вським княжеством проявивий.","Ра́дуйся, орди́нському послу́ христия́нськую любо́в показа́вий.","Ра́дуйся, безбоя́зненно путеше́ствіє в Орду сотвори́вий.","Ра́дуйся, на сіє́ благослове́ніє святи́тельськоє імі́вий.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 7","ps":["Восхоті́л єси́ Ру́ськой Земле́ Бо́жию Сла́ву стяжа́ти, не убоя́лся вели́кий кня́же Дими́тріє отправитися в Орду, і́бо імі́л єси́ на сіє́ благослове́ніє Свято́й Це́ркві Христо́вой в ли́ці благочести́ваго ста́рця-митрополи́та Алексі́я, єго́ же моли́твенноє провожде́ніє імі́л єси́ до гра́да Коломни. Святи́й же архієре́й, ве́лію значимость придавал сему́ путешествію воспитанника своєго́, і упова́я на по́мощ Бо́жию, піл єси́: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вен Бог во святи́х свої́х, і́бо моли́твами святи́теля Алексі́я, преподо́бнаго Се́ргия і свята́го Фео́дора Симановськаго, твоє́ благочести́воє му́жество благослове́нно бисть, благоче́стне кня́же Дими́тріє, єгда́ своє́ богоуго́дноє путеше́ствіє в Орду предпринял єси́, і єгда́ со сла́вою с пра́вом великокняженія із Орди возврати́лся єси́, па́ки в ра́досте благословля́ху і моля́шеся за тя, кня́же, сі́ї святі́ї му́жи, всегда́ імі́ющиє ве́ліє дерзнове́ніє пред Го́сподем. Ми же див'ящієся си́лі Божієго Ду́ха в тебі́ обита́ющаго, воспіва́єм і рцем ті:","Ра́дуйся, с Бо́гом вся творя́щий і за Него́ ратоборствовавший.","Ра́дуйся, ца́рським са́ном облаченний.","Ра́дуйся, житіє́ великоняжеськоє а́нгельськи проводивий.","Ра́дуйся, в пості́ і воздержа́нії стро́го пребива́вий.","Ра́дуйся, в моли́твах нелі́ностно упражнявийся.","Ра́дуйся, крест Христо́в на ра́менах свої́х носи́вий.","Ра́дуйся, сідя́й на престо́лі висо́цім, се́рдцем же об отше́льничеськом житії́ помишля́вий.","Ра́дуйся, вся́кий день в мона́шеськия ри́зи облещи́ся жела́вий.","Ра́дуйся, в чистоті́ все божественниє дні поста́ Це́ркві Правосла́вной соблюда́вий.","Ра́дуйся, святи́х Христо́вих Тайн вся́кую неді́лю приобщавийся.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 8","ps":["Всяк во́зраст і всяк му́жеський і же́нський род Землі́ Ру́ськия свя́то чтить па́м'ять твою́, великосла́вний кня́же Дими́тріє, і́бо ність бо́ліє той любві́, да кто ду́шу свою́ положи́ть за дру́ги своя́, єя́же ти імі́л єси́. Сві́тло рек Госпо́дь наш і Спаси́тель ми́ра во єва́нгельськой про́повіді свяще́нния сі́ї словеса́, ко́ї найпа́че си́льно і ди́вно іспо́лнишася на тебі́, вели́кий кня́же Донськой Дими́тріє. Ми же удивля́шеся благородству душі́ твоєя́, поє́м Бо́гу велегла́сно: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил іспо́лнен ре́вности о ві́рі правосла́вной, встал єси́ на защи́ту Оте́чества ро́да слав'янськаго, избавля́я наро́д свой от нечести́вих ага́рян, і подвизаясь на битву с врага́ми, Бо́га імі́л помо́щником себе́. І сіє́ благочествіє почита́єм в тебі́, доблестний кня́же Дими́тріє, єгда́ ти тридесять літ укріпля́ше дух свой богому́дрим наставничеством і моли́твами святи́х муже́й, до́брі во́їнствовал єси́ с врага́ми Оте́чества твоєго́. Ми же зря́ще благода́тний плод ві́ри твоє́й, крі́пость ду́ха і си́лу воїнськую, воспіва́єм та́ко:","Ра́дуйся, Успенський Строминський монасти́р в Москві́ основа́вий.","Ра́дуйся, благослове́нієм на сіє́ святи́м ігу́меном аввой Се́ргиєм покрове́нний.","Ра́дуйся, боголюбе́зних моли́твенников Землі́ Ру́ськия в сію́ оби́тель собра́вий.","Ра́дуйся, із моли́твами духо́вно укріпи́ти всю Русь пред решающей бранью вожделі́вий.","Ра́дуйся, ігу́меном в сію́ оби́тель богобоязненнаго Лео́нтія поста́вивий.","Ра́дуйся, благочести́ваго сего́ ученика́ преподо́бнаго Се́ргия почти́вий.","Ра́дуйся, за Бо́жию ві́ру биться с врага́ми і за Бо́га Христа́ пострада́ти восхоті́вий.","Ра́дуйся, в поході на Волжськую Булгарію успі́х возимевий.","Ра́дуйся, воєво́ду Бегича сла́вно побіди́ша.","Ра́дуйся, я́ко сія́ брань преддве́рієм вели́каго сраже́нія би́ша.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 9","ps":["Ві́тіії многовіща́нния не возмо́гуть досто́йно ізрещи́ твоє́ смире́ніє і му́жество, благові́рне кня́же Дими́тріє. Єгда́ ти па́дше колінопреклоне́нно пред святи́м аввой Се́ргиєм, ігу́меном Радонежським і сле́зно умоляше єго́ о по́мощі духо́вной, кро́тко моля́ себі́ благослове́ніє на святу́ю брань с по́лчищем поганським. На смире́ніє же твоє́ і кро́тость твою́ сле́зно воззрі́л вели́кий а́вва Се́ргій, і я́ко ве́лій проро́к Бо́га Ви́шняго предре́к ті побі́ду над войськом Мамая, прорекая і о мно́гих венцях на глава́х правосла́вних во́їнов свята́го войська княжеськаго. Сих же вели́ких знаменательних собитій вспоминающе, поє́м Трієди́ному Бо́гу в Тро́йці Живонача́льній сла́в'яще: Аллилу́я."]},{"h":"Ікос 9","ps":["Вся́коє єстество́ А́нгельськоє і Арха́нгельськоє возвесели́шася, богосветлиє небесниє собо́ри святи́х му́чеников, великому́чеников подвигнулись, праведниє, преподобниє му́жи і жени́, со́нми святи́телей і Бо́жії уго́дники возра́довашеся, предстоя́ у престо́ла Бо́га Вседержи́теля і с небе́с восхваля́ху і благословля́ху тя, благові́рне кня́же Дими́тріє, єгда́ ви́дяще твою́ решимось і безстра́шіє ідти́ на свяще́нную битву проти́ву враго́в Оте́чества твоєго́ Правосла́внаго. Сего́ ра́ди ми то́кмо рцем всі:","Ра́дуйся, бесі́дою с вели́ким святи́м Землі́ Ру́ськия преподо́бним ігу́меном Се́ргиєм уті́шенний.","Ра́дуйся, на єго́ богомощния моли́тви і на всю небе́сную Бо́жию по́мощ уповавий.","Ра́дуйся, ве́ліє благослове́ніє Бо́жиє от преподо́бнаго ста́рця Се́ргия получи́вий.","Ра́дуйся, я́ко сим благослове́нієм на битву с Мамаєм, я́ко на вели́коє пра́воє ді́ло поспіши́вий.","Ра́дуйся, і нас упова́ти на Бо́га в ско́рб'ях су́щих науча́яй.","Ра́дуйся, ізвіще́ніє от а́вви Се́ргия, светоча Землі́ Ру́ськия, о побі́ді многочи́сленних і го́рдих ага́рян па́ки прия́вий.","Ра́дуйся, я́ко двух мона́хов в свято́є во́йсько твоє́ от і́ночеськаго ли́ка преподо́бний Се́ргій на сопроти́вних в по́мощ тебі́ да́вий.","Ра́дуйся, я́ко пре́жде би́тви Алекса́ндр і Родіо́н от рук вели́каго ігу́мена Се́ргия постриженієм схимничеським освященниє.","Ра́дуйся, я́ко о́ниє два мона́ха-во́їна от свята́го ігу́мена Бо́гом благословенниє.","Ра́дуйся, я́ко ті́ї два мона́ха Алекса́ндр Пересвет і Родіо́н Ослаб'я би́шася в пе́рвих рядах проти́в супоста́тов.","Ра́дуйся, я́ко в ли́ці сих двух схимона́хов, а́ки сам а́вва Се́ргій ідя́ше на брань с тобо́ю.","Ра́дуйся, я́ко от сугу́баго благослове́нія ста́рця Се́ргия но́ви си́ли в себі́ ощутивий.","Ра́дуйся, я́ко в ли́ці схимона́ха Алекса́ндра Пересві́та сам а́вва Се́ргій проти́в галіяфськаго во́їна мамаєва противоставий і побіди́вий.","Ра́дуйся, я́ко і ти кня́же моли́твами преподо́бнаго Се́ргия, к Бо́гу вопія́, на враги́ побі́ду сотвори́л єси́.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ще Всемогу́щий Бог Зе́млю Ру́ськую от нечести́вих ага́рян показа́ чу́до і си́лу Бо́жию, є́же бисть во гра́ді Влади́мире. Єгда́ бя́ху сама́ собо́ю откри́шася ра́ка со святи́ми моща́ми благові́рнаго вели́каго кня́зя Алекса́ндра Не́вскаго. Сіє́ же Бо́жиє зна́меніє узрі́ і́нок-понома́р среди́ нощі́ і зіло́ удивля́шеся, я́ко свіщи́ пред гробни́цею са́мі собо́ю возжегошася. Разумі́я же прису́тствіє Бо́жиє, і ми со стра́хом і тре́петом воспоє́м Непостижи́мому Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Я́ко ве́лія адамантова стіна́ і Господнєє заступле́ніє, яви́шися сіє́ зна́меніє Бо́жиє, укріпля́ше теб'я́, всечестни́й кня́же Дими́тріє, єгда́ пра́дід твой святи́й благові́рний вели́кий князь Алекса́ндр Не́вский, воста́л із ра́ки моще́й свої́х ду́хом свої́м, і а́ки лев пробужденний в си́лі і сла́ві Бо́жієй поте́к на брань с нечести́вими агарянами. Сіє́ же стра́шно бисть, єгда́ узрі́л понома́р, і па́ки двух светолепних ста́рцев, прише́дших із алтаря ко гро́бу вели́каго кня́зя, повеліва́я і взива́ше к нему́, даби́ ско́ро шел на по́мощ і посо́бствовал в побі́ді правнуку своєму́, кня́зю Дими́трію. Ми же сему́ таково́му Бо́жиєму явле́нію див'я́щеся, вопіє́м:","Ра́дуйся, кня́же Дими́тріє Боже́ственним сим зна́менієм укрепленний.","Ра́дуйся, на враго́во ви́димих, я́ко го́рній орлан, безстра́шно ополчивийся.","Ра́дуйся, по́ле Куликово к ве́лієй битве ізбра́вий.","Ра́дуйся, я́ко пред свято́ю бранью с Мамаєм мо́щі твоєго́ пра́діда вели́каго кня́зя Не́вскаго нетлі́нними обріта́шеся.","Ра́дуйся, я́ко по́мощ Госпо́дня от пра́діда твоєго́ незри́мо при́йде на тя.","Ра́дуйся, по путі́ іді́же ізбра́нна по́ле би́тви, іко́на с о́бразом святи́теля Мир-Ликійськаго Никола́я чуде́сно обрі́теся.","Ра́дуйся, я́ко сіє́ мі́сто богоявле́нія от хла́да сме́ртной би́тви тя угреша.","Ра́дуйся, я́ко зна́меніє явленной іко́ни сей благоприя́тний знак тебі́ би́ша.","Ра́дуйся, я́ко сіє́ нача́лом основа́нія Нико́ло-Угрешському монастирю́ яви́шися.","Ра́дуйся, і́бо сами́м вели́ким святи́телем Никола́єм сіє́ мі́сто благослови́ся.","Ра́дуйся, я́ко ве́лієм белокаменним хра́мом на мі́сті сем в Бо́жієй сла́ві возвели́чися.","Ра́дуйся, я́ко не всу́є прия́л єси́ от кня́зя Владислава Серпуховська́го престо́л великокняженія, а благовре́менно.","Ра́дуйся, я́ко той князь уступиша тебі́ престо́л Моско́вський, да об'єдиниши землі́ ру́ськия смиренному́дренно.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим ті, свя́те кня́же Дими́тріє, єгда́ во смире́нії се́рдця своєго́ возви́сил єси́ глас свой пред во́їни свої́ми, призива́я їх му́жественно сражаться і не посрамиться в день пра́зднованія Рождества́ Цари́ці Пресвято́й Богоро́диці. Ди́вно бисть, я́ко ти, великокняже Дими́тріє, в моли́твах призива́л єси́ Трієди́наго Бо́га, Си́лу Честна́го Креста́ і Богоро́дицю, с сокруше́нним се́рдцем возложи́во всю печа́ль свою́ і наде́жду побі́ди на Го́спода Савао́фа. І ми зді смире́нно помо́лимся Бо́гу, времена́ і лі́та во своє́й вла́сті положившему, і воспоє́м Єму́ побі́дную піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоприємним світи́льником свята́го княжеськаго ро́да яви́лся ти єси́ пред воїнами свої́ми, благові́рне кня́же Дими́тріє, призива́я всіх до́блестно сража́тися Го́спода ра́ди на по́лі бра́ні с врага́ми Бо́жиїми, і та́ко же ре́вностно храни́ти святи́ні Христо́вих церкве́й і чистоту́ ві́ри правосла́вной. Ти же, болі́знуя о сла́ві Свято́й Русі́, мно́гажди взива́ху к воїнам свої́м: не убо́йтеся сме́рти і враго́в, душі́ не могу́щих уби́ти. Сто́йте за Русь Святу́ю! І́бо сме́ртію за Бо́жию ві́ру і Оте́чество Богохрани́моє, обріте́м себі́ живо́т ві́чний. Ми же, поклоня́ємся ті, святи́й вели́кий кня́же Дими́тріє, я́ко сві́тлому воєво́ді войська ру́ськаго, і помина́я твою́ любо́в к Бо́гу, єгда́ по-арха́нгельськи призива́л ра́тников свої́х, непреста́нно увіщева́я їх, нікогда́же в бою с врага́ми помишля́ти о земни́х ве́щіх, но па́че всего́ ревнова́ти о венцях небе́сних. І ми преклоненниє пред му́жеством твої́м, поє́м ті умиле́нно:","Ра́дуйся, в день Рождества́ Пресвяти́я ді́ви Богоро́диці брань на агарянскиє по́лчища сотвори́вий.","Ра́дуйся, живота́ своєго́ ра́ди любві́ к бли́жнім свої́м не щадивий.","Ра́дуйся, ізбра́нниче Бо́жієй Ма́тері преізря́дний.","Ра́дуйся, чистото́ю се́рдця своєго́ Єй благоче́стне угоди́вий.","Ра́дуйся, ре́кший воїнам свої́м: \"Я́ко а́ще бу́дем жи́ви, ра́ди Го́спода своєго́\".","Ра́дуйся, па́ки ре́кший: \"Я́ко а́ще смерть при́ймем, ра́ди Го́спода своєго́\".","Ра́дуйся, с о́бразом Нерукотворнаго Спа́са на зна́менії вої́нськом ра́товати ізво́ливий.","Ра́дуйся, благоче́стію предко́в свої́х поревнова́вий.","Ра́дуйся, на тебі́ воі́стину сби́стся сло́ва: \"не в си́лі Бог, а в пра́вді\".","Ра́дуйся, части́цю Животворящего Дре́ва Креста́ Госпо́дня при себі́ імі́вий.","Ра́дуйся, я́ко пе́рвий твой во́їн Алекса́ндр Пересвет скороте́чно на визов сопроти́вника отозвашеся.","Ра́дуйся, я́ко о́ний благослове́нний во́їн ста́рця Се́ргия за всю Святу́ю Русь в єдиноборство с го́рдим Челубеєм сла́вне вступися.","Ра́дуйся, іді́же ізнемога́єть плоть, та́мо побіжда́єть Дух Бо́жий.","Ра́дуйся, кня́же, я́ко твой во́їн Алекса́ндр не шле́мом і кольчугой, а схимонашеськими крестами покрове́нний.","Ра́дуйся, я́ко той Алекса́ндр-і́нок, во́їнським копіє́м і ві́рою Христо́вою проти́в іноземця вооружи́вийся.","Ра́дуйся, я́ко княжеський і́нок за вся во́їнства Держа́ви Ру́ськия бой держа́ше.","Ра́дуйся, я́ко на по́лі бра́ні вся земля́ Ру́ськая от удара двух соше́дшихся во́їнов содрогнушася і пробудишася.","Ра́дуйся, я́ко са́мий си́льний во́їн агарянський низложи́ся.","Ра́дуйся, я́ко сла́вний во́їн Пересвет мертв сущ в седлі удержа́ся.","Ра́дуйся, я́ко той жив сущ в гриву своєго́ коня́ заблаговременно крі́пці вцепися.","Ра́дуйся, я́ко сиденієм свої́м в седлі, всіх во́їнов-братієв свої́х воодушевивий і приободривий.","Ра́дуйся, я́ко сіє́ до́брим знаком яви́ся.","Ра́дуйся, я́ко і ме́ртвий Пересвет, на том коні́ по всему́ по́лю до конця́ би́тви скака́ше і побі́ду предвозвещаше.","Ра́дуйся, кня́же Дими́тріє, я́ко твої́м во́їном Свята́я Русь во вся ві́ки просла́вися.","Ра́дуйся, я́ко і ти не во великокняжеських одеяніях, но в рубищних оде́ждах простого во́їна в пе́рвих рядах ре́вностно сражавийся.","Ра́дуйся, я́ко мно́гими ра́нами за ві́ру святу́ю із'язвленний.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 12","ps":["Благода́ть ті дана́ от Бо́га, святи́й кня́же, ізнача́ла юнна во́зраста, во є́же до́брі пра́вити страной Ру́ськой і наро́дом єя́ правосла́вним. Ті́мже благодарі́м Го́спода, даровавшего Украї́нськой земле́ хра́браго воєво́ду, пла́меннаго моли́твенника, му́драго строї́теля церко́вних святи́нь, смире́ннаго послу́шника і собесі́дника святи́х уго́дников Бо́жиїх, і ру́ськаго побідоно́сця, столь ди́вную побі́ду над врага́ми іноплеме́нними сотво́ршему. Ми же до́блесть твою́ почита́єм і побі́ду твою́ над Мамаєм по́мним, і духо́вно преданниє тебі́, тре́петно глаго́лем із уст в уста́ свято́є житіє́ твоє́, із ро́да в род на́ми храни́моє, прославля́я і поя́ Христу́ Спаси́телю і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще священниє по́двиги твоя́, святолі́пний кня́же Дими́тріє, содеянниє в сей вре́менній жи́зні, найпа́че же побі́ду в побоїщі над Мамаєм одержавшего і спасшего через сіє́ Оте́чество на́ше правосла́вноє от злові́рія ага́рянськаго. Поклоня́ємся ті, я́ко тече́ніє своє́ до́брі соверши́л єси́, ві́ру соблю́л і ни́ні вінце́м нетлі́нним увінча́ тя Бог Христо́с, Небе́сний Цар і подвигополо́жник на́шего спасе́нія. Сего́ ра́ди мо́лим тя, свя́те кня́же Дими́тріє, я́ко ти і́маши дерзнове́нно предстательствовать о нас у Престо́ла Царя́ Сла́ви, к тебі́ же ра́достно вопіє́м всі:","Ра́дуйся, в лютой бра́ні на рекі Доне Донським нарече́нний.","Ра́дуйся, богомощним іску́сним полководцем в бранях с врага́ми явле́нний.","Ра́дуйся, знак Бо́жий в сопростивном ві́трі распознавий і засадний полк богомудро удержа́вий.","Ра́дуйся, я́ко той полк обоюдоо́стрим мече́м на сокруше́ніє враго́в соблюда́шеся.","Ра́дуйся, і на по́лі бра́ні ві́рний ісполни́телю слов Христо́вих, рекшего, я́ко нікто́ не мо́жеть без Мене́ твори́ти нічесо́же.","Ра́дуйся, я́ко в явленном благоприятном ві́трі во́лю Бо́жию усмотревше і своєвременно вступи́ти в бой кня́зю воли́нському повелі́ша.","Ра́дуйся, я́ко полк засадний в сечі ру́ських с пога́ними благоприя́тний ісхо́д би́тви принесо́ша.","Ра́дуйся, боголюби́вий ратобо́рче, я́ко в сем ві́трі сам Госпо́дь с тобо́ю пребива́ше.","Ра́дуйся, я́ко той ветер тебі́ помога́ше разверза́я зна́м'я с лико́м Госпо́днім, даби́ всіх враго́в погуби́ти.","Ра́дуйся, я́ко светлиє а́нгели во главі́ с Архистрати́гом Михаї́лом помога́ху ті воїнствовати.","Ра́дуйся, я́ко с тобо́ю і с воїнами твої́ми святі́ї му́ченици ше́ствоваху по небесі́.","Ра́дуйся, я́ко с тобо́ю і с твої́ми воїнами спребивал Гео́ргій Побідоно́сче, Дими́трій Мироточи́вий і страстоте́рпці Глі́бе і Бори́се.","Ра́дуйся, я́ко із о́блака Божієго мно́жество вінце́в опускахуся на глави́ правосла́вних во́їнов.","Ра́дуйся, я́ко в предначалії бра́ні мно́гія моле́нія ко Спа́су і Богоро́дице сотвори́вий.","Ра́дуйся, я́ко сама́ Пресвята́я Небе́сная Цари́це со святи́ми Апо́столами душі́ убіє́нних во́їнов на по́лі бра́ні отпевала.","Ра́дуйся, я́ко Ма́ти Бо́жия їх, я́ко чад свої́х в свої́ пречи́стия ру́ці принимала.","Ра́дуйся, я́ко полки́ пога́них ага́рян в три раза число́м превосходя́щих Бо́жиєю по́мощію побіди́вий.","Ра́дуйся, ма́лим число́м свої́х во́їнов, я́ко ма́лим ста́дом Христо́вим сатанинськую си́лу посрами́вий.","Ра́дуйся, в наде́жді на засту́пничество і хода́тайства а́вви Се́ргия преподо́бнаго не посрами́л тя Бог Христо́с.","Ра́дуйся, я́ко Госпо́дь сохрани́ тя в бра́ні сей живи́м су́ща.","Ра́дуйся, па́ки благода́рні посіти́вий преподо́бнаго ігу́мена і слу́жби по убіє́нним во́їном в Тро́йцькой оби́телі со мно́гими слеза́ми соверши́вий.","Ра́дуйся, я́ко вся си́ли тіле́сния во сме́ртном бою істощи́вий, Ду́хом же Бо́жиїм не уга́сший.","Ра́дуйся, і по ни́ні коєго́ждо лі́то па́м'ять творя́ть всі православниє украї́нськиє ча́да во церквях по всім убіє́нним во́їном в суббо́ту Димитрієвськую.","Ра́дуйся, я́ко ти сподо́бился християнськими таїнствами пред своє́ю кончи́ною от рук преподо́бнаго Се́ргия приобщи́тися.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 13","ps":["О вели́кий ру́ський воєво́до і хра́брий во́їне земни́й, благові́рний кня́же, ізбра́нниче Бо́жий, граждани́не небе́снаго Ца́рствія ви́шняго Ієрусали́ма, святи́й добропобі́дний Христо́в страстоте́рпче Дими́тріє! Прийми́ от нас ни́ні возноси́мия тебі́ мольби́ і спаси́ Оте́чество Украї́нськоє і Це́рков Ру́ськую і лю́ди Бо́жії от і́га іноплеме́нников. Умоли́ Го́спода Небе́сних Сил, да пода́сть нам си́лу сви́ше к погубле́нію враго́во ви́димих і неви́димих. Бу́ди хода́тай крі́пкий о слав'янськом наро́ді Бо́жиєм, да і ми грешниє і недостойниє потомки Вели́кой Держа́ви твоє́й вку́пі с тобо́ю на землі́, я́ко і на небесі́ воспоє́м сла́ву Живонача́льній Пресвято́й Тро́йце ві́чно благода́рственную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськоє от млади́х ногте́й стяжа́в житіє́, свя́те кня́же Дими́тріє і от ю́ности возлюби́в Бо́га, воспита́н у́бо бисть во благоче́стії с наставленіями душеполезними. Ті́мже прославля́юще Го́спода, возне́сшаго в слав'янських земля́х ізбра́нника Божієго і воєво́ду ди́внаго, вопіє́м та́ко:","Ра́дуйся, кня́же Дими́тріє, благоче́стіє от роди́телей унаслі́довавий.","Ра́дуйся, кро́тостію нра́ва украше́нний.","Ра́дуйся, слав'янський род імі́вий от святи́я вели́кия равноапо́стольния княги́ні О́льги.","Ра́дуйся, пречестна́я лі́торасль свята́го вели́каго равноапо́стольнаго кня́зя Влади́мира.","Ра́дуйся, правнук яви́вийся свято́му вели́кому кня́зю Алекса́ндру Не́вскому.","Ра́дуйся, благомужество і му́дрость сего́ восприя́вий.","Ра́дуйся, ізмла́да Бо́га возлюби́вий.","Ра́дуйся, Єму́ єди́ному себ'я́ всеці́ло преда́вий.","Ра́дуйся, вся́кую пра́здность возненави́дівий.","Ра́дуйся, доброді́телі христия́нськия в се́рдці своє́м носи́вий.","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Кондак 1","ps":["Ізбра́нному воєво́ді землі́ Ру́ськия свято́му благові́рному вели́кому кня́зю Дими́трію благода́рственная пі́нія прино́сим ми, си́нове і дще́рі украї́нськия, я́ко ізба́вившему Русь Святу́ю от і́га і наше́ствія ага́рянскаго і призва́вшаго мно́гія ру́ськия лю́ди свя́то стоя́ти за ві́ру Христо́ву, за Оте́чество Правосла́вноє і за дру́ги своя́, і душей не страши́тися сме́рті тіле́сной за ві́ру Бо́жию і всегда́ готовими би́ти положи́ти на по́лі бра́ні глави́ своя́. Сего́ ра́ди с ві́рою і любо́вію вопіє́м:","Ра́дуйся, святи́й благові́рний вели́кий кня́же і воєво́до Донськой Дими́тріє, правосла́вной ві́ри і Свято́й Русі́ защи́тниче."]},{"h":"Молитва","ps":["О, святи́й уго́дниче Бо́жий, пра́ведне Дими́тріє! По́двигом до́брим подвиза́вся на землі́, восприя́л єси́ на Небесі́х віне́ць пра́вди, єго́же угото́вал єсть Госпо́дь всім лю́б'ящим Єго́. Ті́мже взира́юще на святи́й твой о́браз, ра́дуємся о пресла́внім сконча́нії жи́тельства твоєго́ і чтим святу́ю па́м'ять твою́. Ти же, предстоя́ Престо́лу Бо́жию, прийми́ моле́нія на́ша і ко Всеми́лостивому Бо́гу принеси́, о є́же прости́ти нам вся́коє прегріше́ніє і помощі́ нам ста́ти проти́ву ко́знем дия́вольским, да ізба́вльшеся от скорбе́й, болі́зней, бід і напа́стей і вся́каго зла, благоче́стно і пра́ведно поживе́м в ни́нішнем ві́ці і сподо́бимся предста́тельством твої́м, а́ще і недосто́йни єсьми́, ви́діти блага́я на землі́ живи́х, сла́в'яще Єди́наго во святи́х Свої́х сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Во́йська ру́ськаго Христо́ва собира́телю, сла́вне кня́же і воєво́до Донськой Дими́тріє, му́дрий воєнноначальниче, му́ченичеськаго со́нма святи́х Христо́вих во́їнов предводи́телю, со мно́гими кня́зі, подру́чними слуга́ми і ві́рними дру́гами ду́шу свою́ за ві́ру Святу́ю і Правосла́вноє Оте́чество положи́вий, от преподо́бнаго Се́ргия Ра́донежськаго благослове́нний, Богоро́дицею возлю́бленний, моли́ся ко Пресвяті́й Тро́йце, да всі Бо́жії во́їни в землі́ украї́нській меж собо́ю разобще́нния і ду́хом зло́би сатани́нськой разділе́нния во єди́но ста́до Христо́во со́брани бу́дуть, ві́рою правосла́вною і любо́вію Бо́жієй друг со друго́м сплоченниє і тобо́ю водительствуємиє, на поля́х духо́вной бра́ні і в битвах земни́х всіх враго́в ненави́дящих Бо́га победить ско́ро і́муть, і сла́ву Свято́й Русі́ умно́жать, благода́ть на зе́млю Ру́ськую привлеку́ть, і правосла́вноє Ца́рство Бо́жиє на своє́й украї́нськой земле́ у́зрять; досто́йний плод покая́нія о греха́х свої́х принесу́ть; і я́ко ве́лій дар Бо́жий, богопомазанним царе́м в землі́ слав'янськой увенчани бу́дуть; і от сего́ Богоізбра́ннаго Правосла́внаго самодержа́внаго ру́ськаго царя́ благослове́ніє при́ймуть; і под святи́тельською єго́ вла́сті благоче́стію правосла́вних вірнопо́дданних нави́кнуть; і́го сатани́нськоє сокруша́ть і чистоту́ єва́нгельськаго сві́та всему́ ми́ру яв'я́ть, я́коже і ти, всечестни́й кня́же Дими́тріє, зри́ши ни́ні Ца́рство Небе́сноє, і стої́ши пред Вели́ким Архієре́єм, Го́сподом і Спа́сом Ісу́сом Христо́м, і от всевишней Єго́ Бо́жієй Бла́гости, ві́руєм, я́ко іспросить нам великіє ми́лости мо́жеши, да і ми при́сно Сла́ву Бо́га Отця́, Бо́га Си́на і Бо́га Свята́го Ду́ха всегда́ велича́ющії, найпа́че же твоє́ свято́є вели́коє княжеськоє предстоя́ніє за Русь Святу́ю, я́ко вели́каго воєво́ду во вели́кой битве помина́єм і почита́єм, іді́же сла́ва пра́ведній жи́зні твоє́й, кня́же Дими́тріє, сія́єть пред всі́ми небе́сними А́нгелами і Арха́нгелами, святи́ми челові́ками і грі́шними людьми́, і нам на землі́ при́сно явля́ємая, всіх нас за ві́ру Христо́ву, Оте́чество і Царя́ до сме́рти стоять вдохновляємая, всегда́, ни́ні, при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, святи́й благові́рний вели́кий кня́же Дими́тріє! А́ще і не мно́зі би́ша дні́є земна́го житія́ твоєго́, оба́че вели́к жре́бій прия́л єси́ от Соді́теля всіх Го́спода, є́же просла́витися в землі́ Украї́нській і блаже́нство ві́чноє на Небесі́х получи́ти. Усли́ши нас, моли́твенниче те́плий, предста́телю наш пред Го́сподем неуси́пний! Во дні ми́ра і в годи́ну нестроє́ній не оста́ви нас попече́нієм твої́м, научи́ ни поко́рни би́ти Боже́ственному Промишле́нію, вся в житії́ на́шем ко бла́гу направля́ющему, оте́чество на́ше моли́твами твої́ми от наше́ствій вра́жиїх, раздо́ров і нестроє́ній защити́ і укріпи́ те́плим твої́м предста́тельством. О свя́тче Бо́жий! Моли́, ку́пно со свято́ю супру́жницею і сподви́жницею твоє́ю благові́рною княги́нею Євдоки́єю, да зна́менається на нас світ лиця́ Бо́жия, і, тім наставля́ємі, дости́гнем Ца́рства Пра́вди Христо́ви, несконча́ємаго і ві́чнаго. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Вели́ка обрі́те в біда́х тя побо́рника земля́ Ру́ськая, / язи́ки побіжда́юща. / Я́коже на Дону́ Мама́єву низложи́л єси́ горди́ню, / на по́двиг сей прия́в благослове́ніє преподо́бнаго Се́ргия, / та́ко, кня́же Дими́тріє, / Христу́ Бо́гу моли́ся, // дарова́ти нам ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["По́двиги твої́ми, свя́те Дими́тріє, / страну́ на́шу Бог сохрани́, / да́вий тебі́ си́лу непобіди́мую. / І ни́ні, предста́телю крі́пкий, / соблюда́й моли́твами святи́ми / град твой Москву́ невреди́м // от всіх наві́т вра́жиїх."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й благові́рний вели́кий кня́же Дими́тріє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Мефодію, ігумену Пєшношському","e":"Akathist to our Venerable Father Methodius, Abbot of Peshnosha","secs":[{"h":"Кондак 1","ps":["Ізбра́нний учениче́ вели́каго учи́теля, богоно́снаго чудотво́рця Се́ргія, і ди́вний подража́телю житія́ єго́ свята́го, преподо́бне о́тче Мефо́діє, пі́сньми восхваля́єм тя с любо́вію, засту́пника на́шего: ти же я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся ви́ну о спасе́нії нас грі́шних, от вся́ких бід избавля́я зову́щих ті:","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Ікос 1","ps":["А́нгелом любезную чистоту́ от ю́ности твоєя́ возлюби́в, преподо́бне о́тче Мефо́діє, к доброді́телей подви́жнику, преподо́бному Се́ргію, в оби́тель прите́кл єси́, і от него́ во і́ночество облече́нний, подража́тель ре́вностний по́двигов єго́ бил єси́. Ті́мже сла́вим тя воззва́нії си́ми:","Ра́дуйся, пусти́ні до́броє прозябе́ніє.","Ра́дуйся, ча́до і́стиннаго послуша́нія.","Ра́дуйся, Єва́нгелія Христо́ва ві́рний послі́дователю.","Ра́дуйся, за́повідей Ісу́сових ре́вностний ісполни́телю.","Ра́дуйся, богоно́снаго Се́ргія при́сний учениче́.","Ра́дуйся, доброді́телей єго́ наслі́дниче.","Ра́дуйся, посто́м умертви́вий в себі́ душетлі́нния стра́сті.","Ра́дуйся, моли́твами усе́рдними отрази́вий вся іскуше́нія диявольськая.","Ра́дуйся, возше́дий на висоту́ соверше́нства духо́внаго.","Ра́дуйся, прини́кий во глубину́ смире́нія свята́го.","Ра́дуйся, слез твої́х теченми уплодоносивий ни́ву душе́вную.","Ра́дуйся, і́же із глубини́ воздиха́нми приобріти́й чистоту́ серде́чную.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 2","ps":["Ви́дів Всеви́дець Госпо́дь, благо́є душі́ твоєя́ ізволе́ніє, о́тче Мефо́діє, є́же на єди́ні рабо́тати Єму́ в безмо́лвії пусти́ннім, внуши́ преподо́бному Се́ргію благослови́ти тя на особноі пусти́нноє пребива́ніє: ти же, благослове́ніє свята́го с ві́рою приє́м, в пусти́ню суровую, в мі́ста блатная і непроходи́мая отше́л єси́, і та́мо поселился єси́, єди́н Єди́ному Бо́гу рабо́тая в пі́ніїх, бді́ніїх і поще́ніїх, немо́лчно вопія́ Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в проізволе́ніє Бо́жиє, преподо́бний Се́ргій, созда́тися оби́телі іночестей в твоє́й пусти́ні, о́тче Мефо́діє, при́йде к тебі́ і ізбра́ мі́сто, удо́бноє на сооруженіє оби́телі, є́же благослови́в і освяти́в моли́твою своє́ю, запові́да тебі́ устро́їти та́мо кинові́ю пусти́нную: ти же за́повідь єго́ іспо́лнил єси́, і в сооруже́нії хра́ма Бо́жия і оби́телі усе́рдно потруди́лся єси́. О сем тя хва́лим і зове́м:","Ра́дуйся, безмо́лвія люби́телю, пусти́ню по́двиги твої́ми освяти́вий.","Ра́дуйся, жесто́коє пусти́нноє житіє́ проходивий.","Ра́дуйся, псалмопі́нії немо́лчними Бо́га славивий.","Ра́дуйся, моли́тви непреста́нния Го́сподеві возноси́вий.","Ра́дуйся, по́стниче не ізнемога́яй, би́лієм пусти́нним питавийся.","Ра́дуйся, трудолю́бче нелицемі́рний, пра́здность возненави́дівий.","Ра́дуйся, худи́я і многошвенния ри́зи носи́вий.","Ра́дуйся, колінопреклоне́нія мно́гія соверша́вий.","Ра́дуйся, в терпі́нії і смире́нії преуспі́вий.","Ра́дуйся, равноа́нгелен на землі́ би́вий.","Ра́дуйся, оби́тель пусти́нную многотру́дно сооруди́вий.","Ра́дуйся, в ней мно́гія ду́ші челові́чеськія Христу́ уневі́стивий.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укріпля́ємий, Мефо́діє преподо́бне, труди́ вели́кия под'ял єси́ при созида́нії оби́телі твоєя́ пусти́нния, древеса́ сіки́й і зда́нія оби́телі сооружа́я рука́ма твої́ма, і при́сно моля́ся ко Го́споду, да благослови́ть ді́ло рук твої́х во сла́ву і́мені Єго́ Свята́го, і на спасе́ніє бли́жніх твої́х, ї́хже приме́ром твої́м научи́л єси́, нелі́ностно возноси́ти хвале́бную піснь Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я по́мисл чист і непоро́чну ду́шу, о́тче Мефо́діє, свяще́нства благода́ть досто́йно восприя́л єси́, і во ігу́мена оби́телі твоєя́ поста́вленний, ре́вностно подвиза́лся єси́ о спасе́нії душе́внім Бо́гом вруче́ннаго тебі́ стада́ слове́сних ове́ць. Сего́ ра́ди сли́шиши от нас благохвале́нія такова́я:","Ра́дуйся, непоро́чний олтаря́ Госпо́дня служи́телю.","Ра́дуйся, досто́йний Та́їнств Боже́ственних соверши́телю.","Ра́дуйся, преподо́бния ру́ці твої́ со дерзнове́нієм го́ре воздія́вий.","Ра́дуйся, моли́тви благоумиленния у престо́ла Бо́жия приноси́вий.","Ра́дуйся, учи́телю благоче́стія.","Ра́дуйся, наста́вниче богому́дрія.","Ра́дуйся, дре́во благосінноли́ственноє, при вода́х пусти́нних возра́стшеє.","Ра́дуйся, плоди́ сла́дкия Христу́ принеси́й.","Ра́дуйся, сотвори́вий і научи́вий, і ве́лій нарече́нний во Ца́рствії Небе́снім.","Ра́дуйся, за по́двиги вре́меннаго житія́ обріти́й поко́й ві́чний.","Ра́дуйся, спасе́нія мно́гих душ челові́чеських вино́вниче.","Ра́дуйся, ангелонравний челові́че.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 4","ps":["Бу́рю многом'яте́жную жите́йськаго мо́ря безбі́дно преше́д єси́, преподо́бне, і в при́стань безстра́стія дости́гл єси́, окормляєм заповедми Христа́ Бо́га, я́же би́ша світи́льник нога́м твої́м, і світ стезя́м твої́м. Ті́мже ни́ні в го́рніх оби́теліх водворя́єшися, і сла́дці поє́ши Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше мно́зі о богоуго́днім житії́ твоє́м, о́тче Мефо́діє, прихожда́ху к тебі́, о́ви послу́шати поуче́ній твої́х душеполе́зних, о́ви же сожи́тельствовати тебі́ в оби́телі твоє́й пусти́нній, ї́хже ти с оте́чеською любо́вію приє́мля, руково́дствовал єси́ стезе́ю пра́вою ко спасе́нію, я́ко всім зва́ти тебі́:","Ра́дуйся, пра́вило ві́ри і́стинния.","Ра́дуйся, о́бразе кро́тости духо́вния.","Ра́дуйся, челові́че Бо́жий, преподо́бієм украше́нний.","Ра́дуйся, во́їне Христо́в, полки́ неви́димих враго́в побіди́вий.","Ра́дуйся, ми́ра дольнего му́дрий стра́нниче.","Ра́дуйся, в доброді́теліх благоїску́сний подви́жниче.","Ра́дуйся, вели́ких пустинножи́телей ві́рний подража́телю.","Ра́дуйся, дре́вніх богоно́сних оте́ць ре́вностний послі́дователю.","Ра́дуйся, преподо́бнаго Се́ргія нра́ви себі́ усво́ївий.","Ра́дуйся, того́ житію́ богоуго́дному поревнова́вий.","Ра́дуйся, сино́внюю любо́в к нему́ стяжа́вий.","Ра́дуйся, і от него́ зіло́ возлю́бленний.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 5","ps":["Боготечноє світи́ло бив, всіх к со́лнцю пра́вди Христу́ путеводи́л єси́, уго́дниче Бо́жий, сло́вом і приме́ром житія́ твоєго́ свята́го, є́же все посвящено бисть на служе́ніє Бо́гу і бли́жнім твої́м: ни́щия і безкро́вния пита́л єси́ в оби́телі твоє́й щедролю́бно, і рука́ твоя́ нікогда́ оскуді́ на подая́ніє ми́лостині тоя́ тре́бующим. Ті́мже блаже́нство ми́лостивих унаслі́довал єси́, преподо́бне о́тче, і со святи́ми поє́ши ві́чно хвале́бную піснь Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим тя, преподо́бне о́тче Мефо́діє, дости́гшаго в му́жа соверше́нна о Христі́ і преіспо́лненнаго дарова́ній боже́ственних, в Єва́нгелії Христо́вом обітова́нних ві́рним последователем вопло́щшагося Бо́га Сло́ва. Ті́мже чудя́щеся твої́м по́двигом, вопіє́м ті хвале́бно:","Ра́дуйся, блаже́нний іска́телю благ ві́чних і нетлі́нних.","Ра́дуйся, неуси́пний ді́лателю виногра́да Христо́ва.","Ра́дуйся, обріти́й во глубину́ се́рдця твоєго́ би́сер драги́й Го́спода Ісу́са.","Ра́дуйся, і́м'я Єго́ боже́ственноє ви́ну імі́вий во уста́х і в се́рдці твоє́м.","Ра́дуйся, і́скренно возлюби́вий і́го Христо́во благо́є і ле́гкоє.","Ра́дуйся, терпіли́во носи́вий крест скорбе́й і лише́ній пусти́нних.","Ра́дуйся, алкавий і жаждавий на землі́, ни́ні же насищаяйся нетлі́нния пи́щі на небесі́.","Ра́дуйся, нищету́ храни́вий, да обогати́шися да́ри боже́ственними.","Ра́дуйся, до́брий настоя́телю общежи́тія і́ночеськаго.","Ра́дуйся, благоїску́сний врачу́ болі́знующих гріхми́.","Ра́дуйся, оте́чеськи возлюби́вий всю о Христі́ бра́тію твою́.","Ра́дуйся, учи́вий благовре́менно і безвре́менно ча́да твоя́ духо́вная богоугожде́нію і́стинному.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 6","ps":["Пропові́дник бил єси́ єва́нгельських доброді́телей бра́тії твоє́й, преподо́бне о́тче Мефо́діє, і ча́да твоя́ духо́вная ві́рно руководи́л єси́ к Сіо́ну, іді́же єсть жили́ще всіх спасе́нних милосе́рдієм Христа́ Бо́га, прише́дшаго в мир спасти́ па́дшеє челові́чество, і да́вшаго Своя́ спаси́тельния за́повіді во спасе́ніє всім, і́же подо́бно тебі́ возлюби́ша Єго́ се́рдцем чи́стим, і навико́ша пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́во в пусти́ні твоє́й я́ко богосві́тлоє світи́ло, о́тче Мефо́діє, сві́том до́брих діл твої́х озари́л єси́ ду́ші і се́рдця челові́ков, іскавших от тебе́ наста́витися во спасе́ніє. Мно́зі бо ві́дяху тя равноа́нгельна житіє́м, і прихожда́ху к тебі́, да сли́шать от тебе́ глаго́ли живота́ ві́чнаго. Тебе́ у́бо, свято́му учи́телю небе́сния і́стини, сотвори́вшему і научи́вшему, і ми смире́ннії зове́м хвале́бно:","Ра́дуйся, Єва́нгелія Христо́ва немо́лчний пропові́дниче.","Ра́дуйся, апо́стольських преда́ній ре́вностний храни́телю.","Ра́дуйся, Правосла́вія святи́я догма́ти в душі́ твоє́й до́брі утверди́вий.","Ра́дуйся, ві́рою пра́вою і ді́ли благи́ми Бо́гу угоди́вий.","Ра́дуйся, во слід себі́ ко Христу́ приведи́й собо́р ученико́в твої́х.","Ра́дуйся, с ни́ми, я́ко оте́ць со ча́ди, возше́дий прия́ти мзду небе́сную от Го́спода.","Ра́дуйся, не сокри́вий тала́нт, тебі́ вруче́нний Всевишнім Домовладикою.","Ра́дуйся, ку́плю мно́гу їм сотвори́вий, спасе́ніє душ челові́чеських.","Ра́дуйся, твої́ми бо уче́нми грі́шнії покая́нієм Бо́гу угоди́ша.","Ра́дуйся, твої́ми бо наставленми заблуждшії пра́вий путь спасе́нія обріто́ша.","Ра́дуйся, бли́жнія твоя́ і́скренно возлюби́вий.","Ра́дуйся, спасе́нію їх душе́вному усе́рдно послужи́вий.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 7","ps":["Хоті́ніє єди́но імі́л єси́, преподо́бне о́тче, є́же Бо́гу благоугожда́ти, і спасе́нію душе́вному бли́жніх твої́х благоче́стно служи́ти: ті́мже оби́тель твоя́ свята́я бисть приста́нище благоути́шноє вся́кому челові́ку, треволне́нієм мо́ря жите́йськаго утомленному. Ти бо, я́ко ко́рмчий бо́дрий, вся ученики́ твоя́ наставля́л єси́ сло́вом і приме́ром твої́м, вдали ми́ра і єго́ сує́ть, се́рдцем і усти́ немо́лчно возглаша́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя Анто́нія Вели́каго, наста́вника душеспаси́тельнаго, позна́вше, преподо́бне о́тче, в пусти́нній оби́телі твоє́й, сла́вния води́ мо́ря жите́йськаго безбі́дно преше́дшаго, і в приста́нище безстра́стія дости́гшаго, к нему́же і ча́да твоя́ духо́вная благоприя́тно приводи́л єси́, нелі́ностно і усе́рдно рабо́тати Го́сподеві в преподо́бії і чистоті́, научи́хомся зва́ти тебі́:","Ра́дуйся, кри́не пусти́ннаго прозябе́нія.","Ра́дуйся, ми́ро Христо́ва благоуха́нія.","Ра́дуйся, пусти́ню духо́вно уплодоносивий.","Ра́дуйся, селе́ніє і́ночеськоє в ней возградивий.","Ра́дуйся, ча́да послуша́нія і смире́нія в ней населивий.","Ра́дуйся, оте́ць чадолюби́вий ученико́м твої́м би́вий.","Ра́дуйся, па́ству твою́ слове́сную упаси́й на па́житіх живоно́сних Єва́нгелія Христо́ва.","Ра́дуйся, оби́тель твою́ пусти́нную созидавий по преда́нію святи́х і богоно́сних оте́ць.","Ра́дуйся, преподо́бнаго Се́ргія пра́вила і уста́ви себі́ усво́ївий.","Ра́дуйся, єго́ благослове́нієм і моли́твою освяще́нний.","Ра́дуйся, ди́вний учениче́ ди́внаго учи́теля.","Ра́дуйся, соверше́нний подража́телю соверше́ннаго о Христі́ отця́ твоєго́ духо́внаго.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 8","ps":["Странника і прише́льця в ми́рі сем помишля́л єси́ себе́ би́ти, Мефо́діє преблаже́нне, ті́мже о бога́тстві земно́м вся́коє попече́ніє отложи́л єси́, і оби́тель твою́ во убо́жестві зі́льнім созида́л єси́, вся́коє стяжа́ніє су́єтноє в ней возбраня́я, ни́щия же і убо́гія от трапе́зи твоєя́ щедролю́бно пита́л єси́, разділя́я хліб твой с неімущею бра́тією, в ї́хже лице́ самому́ Христу́ служи́л єси́, зови́й Єму́ от любве́ те́плия: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив, о́тче преподо́бне, о Бо́зі і угожде́нії Єму́, при́сно бесі́довал єси́ со ученики́ твої́ми, і сле́зи мно́гія ізливал єси́ от оче́с твої́х при бесі́дах сих, умоля́я ча́да твоя́ духо́вная, нічто́же предпочита́ти па́че Любве́ Христо́ви. Помина́юще у́бо такови́я твоя́ душеспаси́тельния бесі́ди, зове́м ті си́це:","Ра́дуйся, ти́хостію слове́с твої́х грі́шники на покая́ніє наста́вивий.","Ра́дуйся, благоумиленною бесі́дою твоє́ю миролю́бці ко Христу́ обрати́вий.","Ра́дуйся, наставленми твої́ми богому́дрими сластолю́бці воздержа́нію научи́вий.","Ра́дуйся, нищелю́бець соверше́нний би́вий.","Ра́дуйся, блаже́нство нищих ду́хом унаслі́дивий.","Ра́дуйся, о́браз соверше́нства о Христі́ в себі́ яви́вий.","Ра́дуйся, ни́щия пита́вий і упокоєвавий в твоє́й оби́телі.","Ра́дуйся, во дні гла́да всім приходившим к тебі́ пи́щу подава́вий.","Ра́дуйся, послі́днія укру́хи хлі́ба твоєго́ с неімущими разділя́ти возжела́вий.","Ра́дуйся, любо́в твою́ к Бо́гу, любо́вію к бли́жнім твої́м свидетельствовавий.","Ра́дуйся, Бо́гом возлю́бленний і бли́жніми твої́ми благословляємий.","Ра́дуйся, похвала́ми моли́твенними до днесь в оби́телі твоє́й почита́ємий.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 9","ps":["Всім приходившим в оби́тель твою́ святу́ю, моли́тви і благослове́нія ра́ди, преподо́бне о́тче, ди́вно бисть ви́діти тя, в раздранной і многошвенной ри́зі ходи́вшаго, і зіло́ нищетно в ке́ллії твоє́й пребивавшаго, оба́че ти всіх ра́вною любо́вію принимал єси́, бога́тих і убо́гих, вельмо́ж і прости́х, і коєму́ждо сло́во на по́льзу душе́вную ізрекал єси́, поуча́я їх благоче́стно служи́ти і благоугожда́ти Бо́гу, ві́рою пра́вою і ді́ли благи́ми, і зва́ти Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́й прему́дрих превзоше́л єси́, преподо́бне о́тче, благода́тним пома́занієм слове́с твої́х, і́миже грі́шния на покая́ніє приводи́л єси́, ка́ющияся уцілому́дрил єси́, подвиза́ющияся в доброді́телі укріпи́л єси́, і всім путь спаси́тельний ко Христу́ показа́л єси́, по нему́же сам неукло́нно ше́ствовал єси́ до блаже́нния твоєя́ кончи́ни, досто́йний воі́стину похва́л такови́х:","Ра́дуйся, написа́вий на скрижа́ліх се́рдця твоєго́ зако́н Христо́в.","Ра́дуйся, от глубини́ серде́чния ізносивий до́брая і душеспаси́тельная наставле́нія челові́ком.","Ра́дуйся, я́ко би́ша словеса́ твоя́ ме́да сладча́йша жаждавшим уче́нія духо́внаго.","Ра́дуйся, я́ко твої́ми наставленми спасо́шася мно́зі.","Ра́дуйся, главо́ свята́я, благода́тію Бо́жиєю осіне́нная.","Ра́дуйся, пропові́дниче сладкоглаголивий, віща́вий словеса́ жи́зні ві́чния.","Ра́дуйся, пусти́нний граждани́не, гра́ди і ве́сі наполнивий сла́вою твої́х по́двигов.","Ра́дуйся, ма́слино Бо́жия благослове́нія, єя́же плоди́ напита́шася ві́рнії.","Ра́дуйся, приведи́й ко Христу́ ученики́ твоя́, в доброді́теліх преуспевшия.","Ра́дуйся, угото́вавий уче́нми твої́ми Го́сподеві подви́жники соверше́нния.","Ра́дуйся, воєво́до благоїску́сний полка́ і́ночеськаго.","Ра́дуйся, руководи́телю предо́брий пустинножи́телей.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 10","ps":["Спасе́нія наде́жду стяжа́л єси́ при ісхо́ді твоє́м, преподо́бне о́тче Мефо́діє, і я́ко пшени́ця зрі́лая, во вре́м'я пожа́тая, кончи́ною благо́ю пресели́лся єси́ от землі́ в оби́телі го́рнія, прия́ти мзду от руки́ пра́веднаго Мздовоздая́теля Христа́, І́же вчини́ ду́шу твою́ со ду́си святи́х, немо́лчно возглаша́ющих пред Престо́лом сла́ви Єго́, побі́дную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ ві́рний раб і послі́дователь бил єси́, о́тче Мефо́діє, ті́мже по нело́жному Єго́ глаго́лу: «Іді́же єсьм Аз, ту і слуга́ мой бу́деть», ми чту́щії тя, ві́руєм несомні́нно, я́ко ти со Христо́м в оби́теліх блаже́нства ві́чнаго водворя́єшися, і ра́дости нетлі́нния наслажда́єшися, я́ко і́стинний Того́ уго́дник, от нас же сли́шиши благохвале́нія сія́:","Ра́дуйся, ра́достно преда́вий ду́шу твою́ в ру́ці Бо́жії.","Ра́дуйся, святу́ю кончи́ну получи́вий во возме́здіє твої́м по́двигом.","Ра́дуйся, пресели́вийся от землі́ к оби́телем небе́сним.","Ра́дуйся, та́мо со святи́ми наслажда́яйся блаже́нства ві́чнаго.","Ра́дуйся, со а́нгельськими во́ї воспіва́яй Творця́ а́нгелов і челові́ков.","Ра́дуйся, открове́нним лице́м созерца́яй сла́ву Трисія́ннаго Божества́.","Ра́дуйся, ті́лом сме́ртним в оби́телі твоє́й погребе́нний.","Ра́дуйся, душе́ю безсме́ртною к Сіо́ну Го́рнему воспаривий.","Ра́дуйся, плач неуті́шен ученико́м твої́м кончи́ною твоє́ю сотвори́вий.","Ра́дуйся, слеза́ми те́плими от них почте́нний.","Ра́дуйся, во гро́бі смире́ннім от них с любо́вію положе́нний.","Ра́дуйся, чудеси́ мно́гими просла́вленний.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце го́ре прино́сиши, преподо́бне о́тче наш Мефо́діє, і о оби́телі твоє́й святі́й, і подвиза́ющихся в ней, при́сно хода́тайствуєши, прося́ ми́ра сви́ше, і благопоспешенія во всем благо́м ча́дом твої́м духо́вним, от ни́хже почитаєшися достодо́лжними похвали́, с пі́нієм Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льника тя до́брих діл, преподо́бне о́тче, іспові́дуєм би́ти, і прославля́єм просла́вльшаго тя Го́спода, І́же чудеси́ мно́гими гроб твой озна́менова: струї́ бо ісціле́ній благода́тних істоча́єши от него́ неду́жним, і подвиза́єши ві́рния вопи́ти тебі́:","Ра́дуйся, земни́й а́нгеле і небе́сний челові́че.","Ра́дуйся, безме́зднаго врачева́нія істо́чниче.","Ра́дуйся, сокро́вищниця даро́в Бо́жия благода́ті.","Ра́дуйся, ми́ра многоціле́бнаго преіспо́лненний фіяле.","Ра́дуйся, от го́рних висо́т к земноро́дним ми́лостиво приникаяй.","Ра́дуйся, от ра́ки твоєя́ святи́я ісціле́нія оби́льно подава́яй.","Ра́дуйся, скорб'я́щих уті́шителю.","Ра́дуйся, боля́щих ціли́телю.","Ра́дуйся, унива́ющих ободрителю.","Ра́дуйся, бі́дствующих ізба́вителю.","Ра́дуйся, в со́ніїх і виді́ніїх ві́рния посіща́яй.","Ра́дуйся, оби́тель твою́ святу́ю от вся́ких бід соблюда́яй.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 12","ps":["Благода́ть Госпо́дню іспроси́ нам, преподо́бне о́тче Мефо́діє, почита́ющим с любо́вію святу́ю па́м'ять твою́, і усе́рдно притека́ющим к честні́й ра́ці моще́й твої́х, от нея́же чуде́сная ісціле́нія подає́ши неду́жним. Ті́мже тебе́, чудотворе́нія да́ром от Го́спода просла́вленному, прилі́жно мо́лимся: ісціли́ на́ша неду́ги душе́вния і тіле́сния, і помози́ нам предста́тельством твої́м спасе́ніє ві́чноє получи́ти, да вку́пі с тобо́ю воспоє́м Ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по́двиги твоя́, преподо́бне о́тче, ублажа́єм равноа́нгельноє житіє́ твоє́, диві́мся мно́гим чудотворе́нієм твої́м, моли́твенно почита́єм святу́ю па́м'ять твою́, і припа́дающе к ра́ці моще́й твої́х, уми́льно глаго́лем:","Ра́дуйся, Пресвяти́я Тро́йці ві́рний служи́телю.","Ра́дуйся, Пресвяти́я Богоро́диці досто́йний предстоя́телю.","Ра́дуйся, а́нгельських лико́в собесі́дниче.","Ра́дуйся, всіх святи́х сожи́телю.","Ра́дуйся, пустинножи́телей сла́во і похвало́.","Ра́дуйся, Украї́нськаго ца́рства духо́вноє украше́ніє.","Ра́дуйся, святи́я оби́телі твоєя́ при́сноє охране́ніє.","Ра́дуйся, подвиза́ющихся в ней благонаде́жноє заступле́ніє.","Ра́дуйся, приходя́щих в ню на поклоне́ніє благи́й предста́телю.","Ра́дуйся, почита́ющих святу́ю па́м'ять твою́ небе́сний покрови́телю.","Ра́дуйся, душе́вних неду́гов благосе́рдний ціле́бниче.","Ра́дуйся, тіле́сних болі́зней преди́вний врачу́.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 13","ps":["О преподо́бне і богоно́сне о́тче Мефо́діє! Ти го́ре на небесі́, ми до́лу на землі́, удале́нния от тебе́ не толи́ко мі́стом, коли́ко гріхо́вною нечистото́ю на́шею, оба́че дерза́єм приноси́ти тебі́ сіє́ ма́лоє похва́льноє пі́ніє, є́же ми́лостивно приє́м, моли́ Го́спода і Влади́ку на́шего, ізба́вити нас поги́белі ві́чния, і сподо́бити блаже́нства святи́х, вопію́щих Єму́ ві́чно хвале́бную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом любезную чистоту́ от ю́ности твоєя́ возлюби́в, преподо́бне о́тче Мефо́діє, к доброді́телей подви́жнику, преподо́бному Се́ргію, в оби́тель прите́кл єси́, і от него́ во і́ночество облече́нний, подража́тель ре́вностний по́двигов єго́ бил єси́. Ті́мже сла́вим тя воззва́нії си́ми:","Ра́дуйся, пусти́ні до́броє прозябе́ніє.","Ра́дуйся, ча́до і́стиннаго послуша́нія.","Ра́дуйся, Єва́нгелія Христо́ва ві́рний послі́дователю.","Ра́дуйся, за́повідей Ісу́сових ре́вностний ісполни́телю.","Ра́дуйся, богоно́снаго Се́ргія при́сний учениче́.","Ра́дуйся, доброді́телей єго́ наслі́дниче.","Ра́дуйся, посто́м умертви́вий в себі́ душетлі́нния стра́сті.","Ра́дуйся, моли́твами усе́рдними отрази́вий вся іскуше́нія диявольськая.","Ра́дуйся, возше́дий на висоту́ соверше́нства духо́внаго.","Ра́дуйся, прини́кий во глубину́ смире́нія свята́го.","Ра́дуйся, слез твої́х теченми уплодоносивий ни́ву душе́вную.","Ра́дуйся, і́же із глубини́ воздиха́нми приобріти́й чистоту́ серде́чную.","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Кондак 1","ps":["Ізбра́нний учениче́ вели́каго учи́теля, богоно́снаго чудотво́рця Се́ргія, і ди́вний подража́телю житія́ єго́ свята́го, преподо́бне о́тче Мефо́діє, пі́сньми восхваля́єм тя с любо́вію, засту́пника на́шего: ти же я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся ви́ну о спасе́нії нас грі́шних, от вся́ких бід избавля́я зову́щих ті:","Ра́дуйся, преподо́бне о́тче наш Мефо́діє."]},{"h":"Молитва","ps":["О, свяще́нная главо́, земни́й А́нгеле і Небе́сний челові́че, преподо́бне і Богоно́сне о́тче наш Мефо́діє! Припа́даєм к тебі́ с ві́рою і любо́вію, і мо́лимся прилі́жно: яви́ нам, смире́нним і грі́шним, свято́є оте́чеськоє твоє́ заступле́ніє: се бо гріх ра́ди на́ших не і́мами свобо́ди чад Бо́жиїх, проси́ти о потре́бах на́ших Го́спода і Влади́ку на́шего, но тебі́, моли́твенника благоприя́тнаго к Нему́ предлага́єм, і про́сим тя со усе́рдієм мно́гим, іспроси́ нам у бла́гости Єго́ благопотре́бния да́ри душа́м і тілесе́м на́шим: ві́ру пра́ву, наде́жду спасе́нія несомні́нну, любо́в ко всім нелицемі́рну, в іскуше́ніїх му́жество, в злострада́ніїх терпі́ніє, в моли́твах постоя́нство, душе́ і тілесе́ здра́віє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, жите́йських потре́б дово́льство, ми́рноє і безм'яте́жноє житіє́, благу́ю христия́нськую кончи́ну і до́брий отві́т на Стра́шном Суді́ Христо́ві. Іспроси́, уго́дниче Бо́жий, у Царя́ ца́рствующих і Го́спода госпо́дствующих правосла́вним христия́ном спасе́ніє і на враги́ одолі́ніє і всему́ оте́честву на́шему мир, тишину́ і благостроє́ніє. Не лиши́ нас по́мощі твоєя́ Небе́сния, но моли́твами твої́ми всіх нас приведи́ в приста́нище спасе́нія і наслі́дники яви́ нас би́ти всесві́тлаго Ца́рствія Христо́ва, да поє́м і сла́вим неізрече́нния щедро́ти Человіколю́бця Бо́га, Отця́ і Си́на і Свята́го Ду́ха і твоє́ свято́є оте́чеськоє заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, вели́кий уго́дниче Христо́в і пресла́вний чудотво́рче, преподо́бне о́тче наш Мефо́діє! При́зри на ни грі́шния, обурева́ємия треволне́нієм жите́йських страсте́й і к тебі́ вопію́щия: ми бо, ча́да твоя́ духо́вная і огра́ди твоєя́ слове́сния о́вці, на тя, по Бо́зі і Богоро́дице, упова́ніє на́ше возлага́єм, і тя со умиле́нієм про́сим: хода́тайством ко Го́споду Бо́гу іспроси́ нам мир, здра́віє, долгоде́нствіє, возду́ха благорастворе́ніє, землі́ плодоно́сіє, дожди́ благовре́менни, і вся ни ізба́ви от вся́ких бід: гра́да, гла́да, пото́па, огня́, меча́, вредоно́снаго че́рвія сніда́ющаго плоди́ земни́я, тлітво́рних вітро́в, смертоно́сния я́зви і напра́сния сме́рти, і во всіх ско́рбіх і печа́ліх на́ших бу́ди нам уті́шитель благи́й і помо́щник ско́рий, сохраня́я нас моли́твами твої́ми от паде́ній гріхо́вних і сподобля́я наслі́дники би́ти Ца́рствія Небе́снаго: да прославля́єм вку́пі с тобо́ю всіх благ пода́теля, в Тро́йці сла́вимаго і покланя́ємаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Боже́ственною любо́вію от ю́ности распала́єм, / вся, я́же в ми́рі кра́сная, возненави́дів, / Христа́ Єди́наго возлюби́л єси́, / і, сего́ ра́ди в пусти́ню всели́вся, / в ней оби́тель сотвори́л єси́, / і, собра́в і́нок мно́жество, / прия́л єси́ от Бо́га чуде́с дар, о́тче Мефо́діє, / і бил єси́ о Христі́ собесі́дник і спо́стник преподо́бному Се́ргію, / с ни́мже у Христа́ Бо́га іспроси́ правосла́вним Христия́ном здра́віє, і спасе́ніє, // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Послуша́нія до́брий рачи́тель бив, / безпло́тния враги́ сле́зними моли́твами твої́ми крі́пко посрами́л єси́ / і яви́лся єси́ Пресвяти́я Тро́йці жили́ще, / Ю́же зря, блаже́нне, я́сно, / Богому́дре Мефо́діє преподо́бне, / чуде́с дар от Нея́ прия́л єси́. / Ті́мже ісціля́єши с ві́рою приходя́щих неду́ги, / утоля́єши ско́рби // і мо́лишися непреста́нно о всіх нас."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Мефо́діє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Варлааму Хутинському","e":"Akathist to our Venerable Father Barlaam of Khutyn","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Чудотво́рче, і ізря́дний Уго́дниче Христо́в, мно́гим воздержа́нієм на землі́ житіє́ Твоє́ украси́вий; сего́ ра́ди і вінце́м от Христа́ на Небесі́ вінча́нний, і с ві́рою приходя́щим істоча́яй многоціле́бния да́ри. Восхваля́єм Тя, Засту́пника на́шего, преподо́бне О́тче Варлаа́ме: Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Варлаа́ме, вели́кий і пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелом уподо́бился єси́, Богому́дре О́тче Варлаа́ме, непоро́чним житіє́м Твої́м на землі́: доброді́тельми укра́шен, пресели́лся єси́ от землі́ на Не́бо, ди́вний о́браз соверше́нства духо́внаго нам оста́вив, да подража́єм доброді́телем Твої́м. Ти же со А́нгели і всі́ми святи́ми предстоя́ Престо́лу Го́спода Сла́ви, моли́ся о нас, почита́ющих Тя і во умиле́нії зову́щих Ті такова́я:","Ра́дуйся, О́трасле Богодарова́нная ко́рене благочести́ваго;","ра́дуйся, Вели́каго Нова́града Прозябе́ніє пречестно́є.","Ра́дуйся, Ча́до возлю́бленноє Благода́ті Ду́ха Бо́жия іспо́лненноє;","ра́дуйся, Отроча́ Боголюбе́зноє.","Ра́дуйся, ізмла́да Боже́ственними Писа́ньми ду́шу Твою́ наси́тивий;","ра́дуйся, во мла́дости му́дрость ста́рця стяжа́вий.","Ра́дуйся, воздержа́нієм роди́телі Твоя́ ізуми́вий;","ра́дуйся, смире́нієм і послуша́нієм мно́гих удиви́вий.","Ра́дуйся, ю́ность Твою́ Непоро́чностію житія́ украси́вий;","ра́дуйся, целому́дріє ді́вства невреди́мо сохрани́вий.","Ра́дуйся, от ю́ности в же́ртву Благоприя́тну Го́сподеві Сам Себ'я́ принеси́й;","ра́дуйся, во всем житії́ єди́но попече́ніє імі́вий є́же Трийпоста́сному Бо́гу то́кмо служи́ти.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дівше роди́телі ве́ліє воздержа́ніє Твоє́, О́тче Преблаже́нне, в печа́лі бя́ху, да не в болі́знь впаде́ши юн сий: Ти же Первоверхо́внаго Апо́стола глаго́лу внима́я, я́ко бра́шно і питіє́ не поставля́єть нас пред Бо́гом, но то́кмо пост і моли́тва, усе́рдно проси́л єси́ роди́телі Твоя́ да́ти Тебі́ посто́м і моли́твою стра́сті ю́ношеськия умерщвля́ти, да не порабо́тять сія́ Ду́ха: они́ же сли́шавше такова́я, почуди́шася і оста́виша Тя жи́ти благо́му Твоєму́ ізволе́нію, воспіва́юще Вразуми́вшему Тя Бо́гу благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум благи́й, благоро́дство і́стинноє, бога́тство неістощи́моє стяжа́л єси́, Богоблаже́нне Варлаа́ме, єгда́ от ю́ности возжела́в го́рняя му́дрствовати, а не земна́я, взиска́л єси́ стезі́ к Небе́сним Оби́телем в безмо́лвії і Богоми́слії. Ми же помина́юще толи́кую Твою́ к по́двигом духо́вним ре́вность, со умиле́нієм взива́єм Ті такова́я:","Ра́дуйся, безмо́лвія і Богоми́слія до́брий Рачи́телю;","ра́дуйся, потре́бнаго для душі́ сле́зний Іска́телю.","Ра́дуйся, во́лею Своє́ю і́го за́повідей Христо́вих под'я́вий;","ра́дуйся, угожде́ніє Бо́гу па́че всего́ предизбра́вий.","Ра́дуйся, кро́ткий Послі́дователю Христо́в;","ра́дуйся, живи́й о́бразе Єва́нгельськаго самоотверже́нія.","Ра́дуйся, воздержа́нія Пра́вило ізві́стноє;","ра́дуйся, я́ко от ю́ности нави́кнувий поще́нію.","Ра́дуйся, всего́ ми́ра кра́сная, зна́тность ро́да і по́чести мирськи́я Христа́ ра́ди ні во что вміни́вий;","ра́дуйся, то́кмо доброді́тельноє по Бо́зі житіє́ возлюби́вий.","Ра́дуйся, і нас земни́я ра́дости презира́ти науча́яй;","ра́дуйся, ко Го́рнему уми́ і сердця́ на́ша направля́яй.","Ра́дуйся, Варлаа́ме Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго ізмла́да вложи́ в се́рдці Твоє́, Преподо́бне О́тче наш Варлаа́ме, к і́ночеському житію́ ре́вность, є́юже руководи́м по сме́рті роди́телей Твої́х оста́вил єси́ дом їх, і во всем упова́ніє возложи́в на Го́спода, оби́телі Пресвяти́я Богоро́диці дости́гл єси́, іді́же і водвори́лся єси́, с рабо́тающими Бо́гу во і́ночеськом житії́ непреста́нно вопія́ Єму́ а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я непреодоли́моє жела́ніє І́го Христо́во на Себі́ прия́ти і во слід Христу́ поіти́, в послуша́ніє отцю́ Твоєму́ духо́вному преда́лся єси́ все́ю душе́ю і всім се́рдцем. Сей же проразумева́я в Тебі́ сосу́д ізбра́нний Свято́му Ду́ху, облече́ Тя во А́нгельський О́браз і нарече́ і́м'я Ті Варлаа́м. Ти же вся доброді́телі, подоба́ющий і́ноком, соверши́л єси́, і в новонача́лії Своє́м соверше́н би́ти і́нок і добр Подви́жник показа́лся єси́. Сего́ ра́ди із глубини́ серде́ць вопіє́м Ті такова́я:","Ра́дуйся, і́ночеськаго житія́ ско́рби і тісноту́ возлюби́вий;","ра́дуйся, сожи́тельство і собесе́дничество с преподо́бними ізбра́вий.","Ра́дуйся, ві́рою, любо́вію і упова́нієм Спасе́нія іспо́лненний;","ра́дуйся, обі́том ді́вства чистоту́ се́рдця яви́вий.","Ра́дуйся, обі́том нестяжа́нія висоту́ Ду́ха показа́вий;","ра́дуйся, обі́том послуша́нія всесоверше́нноє служе́ніє Своє́ Єди́ному Бо́гу утверди́вий.","Ра́дуйся, житію́ і по́двигом дре́вніх преподо́бних оте́ць поревнова́вий;","ра́дуйся, в труди́ і послуша́ніє отцю́ Твоєму́ духо́вному преда́тися усе́рдно восхоті́вий.","Ра́дуйся, іску́с долготерпі́нія благоуспі́шно проше́дий;","ра́дуйся, вся́коє послуша́ніє со смире́нієм і кро́тостію соверши́вий.","Ра́дуйся, благочи́нія монасти́рськаго ві́рний Храни́телю;","ра́дуйся, равноа́нгельнаго житія́ стро́гий Ревни́телю.","Ра́дуйся. Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю мирська́го житія́ і во́лни страсте́й преше́д, Богому́дре О́тче Варлаа́ме, обрі́л єси́ ти́хоє приста́нище во Оби́телі Пресвяти́я Богоро́диці, іді́же і всели́вся нелі́ностно порабо́тал єси́ Христу́ во мно́зі долготерпі́нії, со вся́ким воздержа́нієм смиря́я Свою́ ду́шу: ті́ло же Своє́ труда́ми і по́двигами утомля́я, я́ко всій бра́тії зіло́ удивля́тися вели́кому Твоєму́ смире́нію і послуша́нію, і прославля́ти о Тебі́ Бо́га, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав похваля́єма Тя би́ти во Оби́телі от челові́к, превозноше́нія су́єтнаго убоя́лся єси́, О́тче Преподо́бне, і те́плі моли́лся єси́ ко Го́споду да сподо́бит Тя в пусти́нном безмо́лвії Єму́ служи́ти. Ті́мже, я́ко іща́й Сла́ви Єди́наго Бо́га. Прише́л єси́ на го́ру Ху́тинськую, сви́ше Тебі́ луче́м Боже́ственнаго Сві́та указа́нную, да та́мо в ми́рі Єди́ному Го́споду рабо́таєши. Ми же, див'я́щеся Пречу́дному сему́ указа́нію, ра́достно зове́м Ті такова́я:","Ра́дуйся, презрі́вий сла́ву челові́чеськую. Я́ко су́єтную;","ра́дуйся, восприя́вий Свято́є Смире́ніє Ісу́сово.","Ра́дуйся, Благода́тію Бо́жиєю води́мий, я́ко єди́н от дре́вніх Патріа́рхов;","ра́дуйся, освяти́вий го́ру Ху́тинськую Твої́м прише́ствієм.","Ра́дуйся, Луч о́гнен ви́дівий на ней;","ра́дуйся, чрез сіє́ прия́вий от Го́спода благо́є ізвіще́ніє о мі́сті поко́я Твоєго́.","Ра́дуйся, Зри́телю Боже́ственних виді́ній;","ра́дуйся, Го́рлице пустиннолюби́вая, Ху́тинськую дебр огласи́вшая пі́нієм Сла́ви Бо́жия.","Ра́дуйся, Кри́не благоуха́ющий в пусти́ні;","ра́дуйся, моли́тв благово́нноє Кади́ло.","Ра́дуйся, псалмопі́нія Орга́не ізя́щний.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чною Звіздо́ю преше́д на го́ру Ху́тинськую, блиста́я і́ночеськими по́двиги Твої́ми, Преподо́бне О́тче Варлаа́ме, ди́внаго виді́нія сподо́бился єси́, єгда́ узрі́в Луч Боже́ственнаго Сві́та, указа́вший Тебі́ мі́сто по́двигов Твої́х, зіло́ умили́лся єси́ в се́рдці Твоє́м, сла́в'я Бо́га і воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Спасти́ хотя́й ду́шу Твою́, Уго́дниче Бо́жий, а́ще і всемі́рно бі́гал єси́ сла́ви, я́же от челові́к: ві́рно оба́че Сло́во Го́спода, я́ко не мо́жеть град укри́тися верху́ гори́ стоя́, та́ко бо і о Твоє́м пусти́нном по́двизі уві́діша Вели́каго Нова́града лю́діє, і нача́ша благогові́йно приходи́ти к Тебі́, прося́ у Тебе́ моли́тв, душеполе́зних наставле́ній і благослове́нія. Ти же всіх с любо́вію приє́мля, поуча́л єси́ от Боже́ственнаго Писа́нія є́же твори́ти За́повіді Госпо́дні і імі́ти любо́в нелицемі́рну. Ми же ублажа́юще Тя вопіє́м Ті такова́я:","Ра́дуйся, Гра́де, верху́ гори́ стоя́й і не моги́й укри́тися;","ра́дуйся, Світи́льниче, Боже́ственним Пла́менем возже́нний.","Ра́дуйся, Огневи́дний Сто́лпе, наставля́яй на путь Спасе́нія;","ра́дуйся, Лучеза́рний Світи́льниче, ві́рния просвіща́яй.","Ра́дуйся, Цві́те духо́вний, Благода́тію привлека́яй взо́ри душе́вния к Тебі́ приходя́щих;","ра́дуйся, Пчело́ трудолюби́вая, со́ти доброді́телей в насище́ніє а́лчущих с Собо́ю нося́щая.","Ра́дуйся, грі́шния на путь Спасе́нія направля́яй;","ра́дуйся, скорб'я́щия сла́достію слове́с Твої́х утіша́яй.","Ра́дуйся, ю́ния наставля́яй;","ра́дуйся, ста́рия не сло́вом то́чію, па́че житіє́м укріпля́яй.","Ра́дуйся, притека́ющим к Тебі́, те́плий Моли́твенниче і Боговіща́нний Учи́телю;","ра́дуйся, і нас всіх обремене́нних гріхи́ мно́гими, в любві́ друг ко дру́гу Ди́вний Наста́вниче.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дника терпі́нія, му́жества і кро́тости зрим Тя, Богому́дре О́тче Варлаа́ме, во всіх озлобле́ніїх, я́же творя́ху Ті ду́си зло́би: сі́ї бо іногда́ во о́бразі звіре́й ди́віїх, іногда́ во о́бразі змій ядови́тих явля́хуся к Тебі́ і устраша́ху, понужда́я Тя отити́ от мі́ста того́. Ти же ві́рою і кре́стнаго зна́менія си́лою вся ко́зні їх сла́вно побіди́л єси́ і змі́єв ядови́тих от Оби́телі Твоєя́ навсегда́ дале́че отгна́л єси́. Сего́ ра́ди ми, прославля́юще о Тебі́ Го́спода, во умиле́нії благода́рственно вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́в от Вели́каго Нова́града, О́тче наш Варлаа́ме, просвіти́л єси́ чу́дним житіє́м Твої́м го́ру Ху́тинськую, на не́йже і Оби́тель і́ноком во спасе́ніє Бо́жиїм ізволе́нієм устро́їл єси́, і це́рков во І́м'я Преображе́нія Госпо́дня созда́л єси́, і свяще́нства Благода́ть восприя́ти чрез святи́теля Бо́жия і Ігу́меном созда́нния Тобо́ю Оби́телі от него́ нарещи́ся не уклони́лся єси́, а́ще і тужа́ше дух Твой, ужаса́яся висоти́ сея́. Ми же, прославля́юще Тя, любо́вію вопіє́м Ті:","Ра́дуйся, во удале́нії от ми́ра су́єтнаго пусти́нную Оби́тель ра́ди і́щущих спасе́нія до́брі основа́вий;","ра́дуйся, водвори́вшимся в ней Вели́кий Учи́телю і Богому́дрий Наста́вниче.","Ра́дуйся, благогові́йний алтаря́ Госпо́дня Служи́телю, о ві́рних моля́йся;","ра́дуйся, со мно́гим дерзнове́нієм о нас недосто́йних ко Го́споду предста́тельствующий.","Ра́дуйся, Та́їн Бо́жиїх і́стинний Строї́телю;","ра́дуйся, слове́снаго ста́да Твоєго́ До́брий Па́стирю.","Ра́дуйся, Предводи́телю Богому́дрий в путі́ Спасе́нія;","ра́дуйся, вождю́ до́блій, Мно́гих приведи́й ко спасе́нію.","Ра́дуйся, святи́я Во́лі Бо́жия Ісполни́телю;","ра́дуйся, оте́чеських преда́ній усе́рдний Храни́телю.","Ра́дуйся, і́ноков благочести́вих Похвало́ і Украше́ніє;","ра́дуйся, і о нас грі́шних Судії́ Пра́веднаго Умоле́ніє.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́щу Ті угоди́ти Єди́ному Го́споду, Богоно́сне О́тче Варлаа́ме! Весь вда́лся єси́ безмі́рним по́двигом і глубині́ смире́нія: труди́ же Твоя́, і моли́тви і поще́нія ко́є сло́во ізглаго́лати мо́жеть ві́ми то́кмо, я́ко вери́гами тя́жкими і власяни́цею обле́клся єси́, претерпіва́я болі́зні любве́ ра́ди Бо́жия. Сего́ ра́ди Человіколю́бець Госпо́дь, ви́дя смире́ніє Твоє́, возвели́чи Тя Благода́тію Чудотворе́ній, Єго́же благодаря́ще, вопіє́м Єму́ ку́пно с Тобо́ю: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вноє і пресла́вноє чу́до показа́ Тобо́ю на землі́ всіх чуде́с Творе́ць і Влади́ка, єгда́ преміни́шася єстества́ уста́ви: среди́ бо лі́та мраз си́лен і сніг глубо́к яви́стася в преде́лах Нова́града, є́же Ти предре́кл єси́ о́ному святи́телю; Святи́тель Бо́жий і лю́діє Нова́града смути́шася тогда́ зіло́, боя́хубося, я́ко глад ве́лій наста́неть в страні́ їх. Єгда́ же усли́шаша от Тебе́ ізволе́ніє Бо́жиє, явле́нноє во ви́димом і благо́є промишле́ніє о лю́діх Свої́х, ра́дости іспо́лнишася і возблагодари́ша Бо́га Ди́внаго во Святи́х Свої́х. Ми же, див'я́щеся Си́лі Бо́жієй, обита́ющей в Тебі́ і помина́юще ско́роє Твоє́ заступле́ніє, со умиле́нієм покланя́ємся Тебі́, я́ко ве́ліє дерзнове́ніє іму́щему пред Го́сподем і благода́рственно вопіє́м:","Ра́дуйся, в ми́рі преми́рним яви́вийся;","ра́дуйся, страну́ Новагра́дськую удиви́вий чудеси́.","Ра́дуйся, і́мже о Си́лі Бо́жієй єстества́ уста́ви преміни́шася;","ра́дуйся, і́мже лю́діє Нова́града от гла́да ізба́вишася.","Ра́дуйся, Ді́лателю чуде́с пресла́вних;","Ра́дуйся, Хода́таю і Пода́телю дарова́ній многообра́зних.","Ра́дуйся, мно́гія от тя́жких напа́стей і скорбе́й ізба́вивий;","ра́дуйся, ско́рий Помо́щниче всіх в біда́х су́щих.","Ра́дуйся, Нова́града Красото́ і Утвержде́ніє;","ра́дуйся, гори́ Ху́тинськия Сла́во і Похвале́ніє.","Ра́дуйся, Промишле́ніє о лю́діх благо́є Прия́телище;","ра́дуйся, і нас грі́шних прибіга́ющих под кров Твой, неуси́пний Засту́пниче.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 8","ps":["Неістощи́мий Істо́чник вели́ких чуде́с яви́лся єси́, Достосла́вне О́тче наш Варлаа́ме! Прия́л бо єси́, єще́ в ми́рі сем жив'я́, дар от Бо́га не то́кмо неду́ги ісціля́ти, но і ме́ртвия воскреша́ти, я́коже воскреси́л єси́ моли́твою о́наго о́трока: і бу́дущая прориця́ти, я́коже предре́кл єси́ кня́зю Новагра́дському о рожде́нії єму́ си́на. По сме́рті же найпа́че просла́ви Тя Бог мно́гими чудотворе́нії, да всі Чудотворя́щему Тобо́ю Бо́гу вопіє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ с ві́рою к Тебі́ притека́ющим воі́стину Помо́щник Вели́кий, Уго́дниче Бо́жий Варлаа́ме! Не то́чію прибега́ющим к цільбоно́сним моще́м Твої́м, но і дале́че отстоя́щим і призива́ющим всечестно́є І́м'я Твоє́. Ті́мже во умиле́нії зове́м Ті, я́ко воі́стину досто́йному благохвале́ній:","Ра́дуйся, Утіше́ніє! Скорб'я́ми жите́йськими утесне́нних;","ра́дуйся, Весе́ліє, в печа́ліх су́щих.","Ра́дуйся, злостра́ждущих от духо́в зло́би Ско́рий Помо́щниче і Ізба́вителю;","ра́дуйся, я́же нікто́же с ві́рою притека́яй, тощ отхо́дить от Тебе́.","Ра́дуйся, я́ко су́щим в пучи́ні скорбе́й Добр обріта́єшися Ко́рмчий;","ра́дуйся, я́ко Ми́лостивий при жи́зні, благотвори́ши всім тре́бующим і по сме́рті.","Ра́дуйся, пла́вающих ле́гкоє по вода́м Прехожде́ніє;","ра́дуйся, путеше́ствующих До́брий Путеводи́телю.","Ра́дуйся, си́льний вдови́ць Покрови́телю;","ра́дуйся, сиро́т милосе́рдий і благопопечи́тельний Храни́телю.","Ра́дуйся, а́лчущих любвеоби́льний Пита́телю;","ра́дуйся, всіх безпомо́щних ві́рний пред Го́сподем Хода́таю.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́кия ско́рби і труди́ до́бльственно претерпі́л єси́, О́тче наш Варлаа́ме! Ше́ствуя по путі́ Спасе́нія до масти́тия ста́рости. Скончава́я же тече́ніє вре́менния жи́зні сея́, всіх поуча́л єси́ ісполне́нієм Во́лі Бо́жієй благоугожда́ти Го́сподеві. Ми же грі́шнії, і́щуще с ві́рою Твоєго́ заступле́нія і припа́дающе к Тебі́ я́ко Отцю́ благосе́рдому, смире́нно мо́лим Тя бу́ди нам Покро́в і Защище́ніє в день кончи́ни на́шея, да неосужде́нно предста́нем Престо́лу Судії́ всіх, і вопіє́м Єму́ с Тобо́ю і со всі́ми Небе́сними Си́лами А́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йствующий язи́к недоумі́єть досто́йно воспі́ти Твоя́ по́двиги і труди́, Благи́й Ра́бе Бо́жий, я́же поне́сл єси́ любве́ ра́ди і спасе́нія душ при́сних Твої́х: яви́лся бо єси́ Пропові́дник воздержа́нія і терпі́нія і́ноком пустиннолюби́вим і всім Учи́тель Му́дрий, наставля́яй на путь спасе́нія. Ми же, чудя́щеся висоті́ і си́лі Твоєя́ доброді́телі, зане́ ви́дим плоди́ єя́ в Твої́х ученика́х і сподви́жниках Анто́ніє, Ксенофо́нте, Косьме́ і Константи́не, уже́ просла́вленних вмі́сті с Тобо́ю во Ца́рствії Отця́ Небе́снаго, любо́вію прославля́єм Тя си́це:","Ра́дуйся, Трудолю́бче, тече́ніє жи́зні Твоєя́ во вели́ких по́двигах соверши́вий;","ра́дуйся, терпі́нію Христо́ву ві́рно Подража́вий.","Ра́дуйся, сві́том доброді́телей Твої́х Бо́га просла́вивий;","ра́дуйся, Сі́м'я До́броє, на землі́ бла́зі посе́янноє і стори́чний Плод прине́сшеє.","Ра́дуйся, Світи́ло благоче́стія Немерца́ющеє;","ра́дуйся, Звіздо́, ко спасе́нію путь ві́рним показу́ющая.","Ра́дуйся, не сло́вом то́чію, но па́че житіє́м поуча́яй;","ра́дуйся, і́ноком путь і́стинний ко спасе́нію показа́вий.","Ра́дуйся, по́стничества і терпі́нія О́браз преди́вний;","ра́дуйся, воздержа́нія Учи́телю.","Ра́дуйся, за́повідей Христо́вих ві́рний Ісполни́телю;","ра́дуйся, і всіх нас в любві́ к при́сним ди́вний Наста́вниче.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й ду́ші учени́к Твої́х, Преподо́бне О́тче Варлаа́ме! І проразумі́вий, є́же к Бо́гу Твоє́ отше́ствіє, призва́л єси́ всю бра́тію Твою́, і я́ко Оте́ць чадолюби́вий наставля́я їх, предре́кл єси́ о би́ти іме́ющем по блаже́нній кончи́ні Твоє́й прославле́нії Оби́телі Твоєя́, а́ще любо́в соблюду́ть друг ко дру́гу. Ни́ні же, по предрече́нію Твоєму́ ісполня́ємая зря́ще, в ра́дості ку́пно с Тобо́ю вопіє́м Го́споду і Бо́гу благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго возлюби́во всім се́рдцем Твої́м і все́ю душе́ю Твоє́ю і все́ю ми́слію Твоє́ю, до конця́ жи́зні Твоєя́ в терпі́нії і по́двизі неосла́бно преби́л єси́, і єгда́ дости́гнув в мі́ру во́зраста і в му́жа соверше́нна, позна́л приближе́ніє вре́мені, ну́жнаго челові́ку ізміне́нія, во є́же тлі́нному наслі́довати обетова́нноє безсме́ртіє, тогда́ завіща́л єси́ ученико́м Твої́м вся потре́бная ко спасе́нію, наста́вника же в Себі́ мі́сто Анто́нія сподви́жника Твоєго́ оста́вил єси́, єму́же і Оби́тель Святу́ю вручи́л єси́ і бра́тію: Та́же благослови́во всіх, пре́дал єси́ Святу́ю ду́шу Твою́ в ру́ці Бо́жії. Ми же, помина́юще сія́, із глубини́ серде́ць вопіє́м Ті такова́я:","Ра́дуйся, і́скреннюю любо́в к Бо́гу в душе́ і се́рдце непреста́нно імі́вий;","ра́дуйся, то́юже любо́вію к духо́вним ча́дам Твої́м, при отше́ствії іспо́лненний.","Ра́дуйся, страх Бо́жий в се́рдці ви́ну сохрани́вий;","ра́дуйся, Єди́ному Го́споду до конця́ послужи́вий.","Ра́дуйся, благоче́стно тече́ніє вре́менния жи́зні сконча́вий;","ра́дуйся, кончи́ну Свою́ предуві́дівий.","Ра́дуйся, я́ко с тве́рдим наді́янієм Благ Ві́чних преста́вился єси́ к Бо́гу;","ра́дуйся, я́ко Цар ца́рствующих прия́л Тя в Небе́сноє Ца́рствіє.","Ра́дуйся, я́ко свя́тостію житія́ Ми́лость Бо́жию обрі́л єси́;","ра́дуйся, Ра́бе Благи́й і Ві́рний вше́дий в ра́дость Го́спода Твоєго́.","Ра́дуйся, я́ко от Оби́телі земни́я в Оби́тель Небе́сную пресели́лся єси́;","ра́дуйся, я́ко с Небе́сних висо́т на мольби́ на́ша ми́лостивно призира́єши.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє погреба́льноє слеза́ми растворя́шеся у гро́ба Твоєго́, Досточу́дне О́тче Варлаа́ме, мно́жества же ра́ди свеще́й і благово́нія кади́льнаго, сві́тлим торжество́м явля́шеся погребе́ніє Твоє́, і мно́зі тогда́ неду́жнії получи́ша ісціле́ніє прикоснове́нієм ко Святи́м моще́м Твої́м, ра́дующеся і благода́рственно взива́юще к Чудотворя́щему Тобо́ю Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє Світи́ло, на Ху́тинськой го́ре возсія́вшеє, і по честні́м успе́нії Твоє́м зрим Тя, Богому́дре О́тче Варлаа́ме, зане́ і ни́ні сві́тиши нам зна́менії і чудеси́, от Святи́х моще́й Твої́х істека́ющими, я́же ізволе́нієм Бо́жиїм земля́ яви́ Святи́телю Євфи́мію і би́вшим во хра́мі с ним ігу́мену Тара́сію, іподия́кону Іоа́нну, я́ко многоці́нноє і Благода́ті іспо́лненноє Сокро́вище. Ті́мже і ми, благода́рственная Бо́гу принося́ о тебі́ пі́нія, взива́єм к тебі́ си́це:","Ра́дуйся, нетлі́нієм моще́й твої́х сла́вно от Бо́га возвели́ченний;","ра́дуйся, от моще́й твої́х ісціле́нія неду́гов Благода́тію Бо́жієй істоча́яй.","Ра́дуйся, Ча́ше, ізлива́ющая то́ки Милосе́рдія Бо́жия;","ра́дуйся, чуде́с Пучи́но, сви́ше ізлія́нная.","Ра́дуйся, пре́жде сме́рти яви́вий ди́вная;","ра́дуйся, і по успе́нії соверша́яй чу́дная.","Ра́дуйся, я́ко і по сме́рті жив пребива́єши, явля́я в Себі́ си́ли Боже́ственния;","ра́дуйся, я́ко моли́твенно Тя призива́ющия, ско́ро посіща́єши.","Ра́дуйся, немощни́х Ціли́телю;","ра́дуйся, ско́рбних Уті́шителю.","Ра́дуйся, я́ко і по преставле́нії твоє́м при́сно с на́ми пребива́єши;","ра́дуйся, я́ко і жив'я́ в селе́ніїх Ра́йських нас не оставля́єши.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 12","ps":["Хотя́ сокрове́нную та́йну яви́ти, показа́л єси́ ди́вная боголюби́вому му́жу Тара́сію о поги́белі і потопле́нії Вели́каго Нова́града: оба́че сам же ти і вели́кий Покро́в гра́ду бил єси́ і гнів Бо́жий моли́твами твої́ми ум'ягчи́л єси́, і град твой от ка́зні ізба́вил єси́. Тогда́ всі лю́діє ви́дівше тя ко Го́споду Пречу́днаго хода́тая, вопія́ху к Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Ди́вен показа́лся єси́ ученико́м твої́м, єгда́ єди́наго от осужде́нних, нікому́ же тя моля́щу, от ка́зні сме́ртния свободи́л єси́, друга́го же і мно́гим тя о нем прося́щим от сме́рти ізба́вити не восхоті́л єси́. Ми же не дерза́єм іспи́тивати сокрове́нная Суде́б Бо́жиїх Та́йни, но со стра́хом к тебі́ взива́єм:","Ра́дуйся, таї́нниче вели́кий, Бо́жия Благода́ті;","ра́дуйся, защи́тниче, от бід і сме́рті непови́нния.","Ра́дуйся, свяще́нний у́ме, постига́яй Боже́ственния Та́йни;","ра́дуйся, ра́зуме просвіще́нний сві́том Го́рнія Сла́ви.","Ра́дуйся, ду́ше, освяще́нний Благода́тію Бо́жиєю;","Ра́дуйся, се́рдцем очище́нним зряй Непостижи́мия Бо́жия Судьби́.","Ра́дуйся, вну́тренняя се́рдця іспиту́яй;","ра́дуйся, прозрева́яй сокрове́нния ми́слі.","Ра́дуйся, сві́тлий у́ме озаре́нний Невече́рнім Сві́том;","ра́дуйся, чи́стий душе́ю, просветле́нний Со́лнцем Пра́вди.","Ра́дуйся, Варлаа́ме, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О, вели́кий і Пречу́дний О́тче наш Варлаа́ме! К Тебі́ припа́дая со умиле́нієм мо́лим: прийми́ сіє́ ма́лоє хвале́бноє пі́ніє на́ше і Богоприя́тним Твої́м Хода́тайством іспроси́ нам от Христа́ Ми́лостиваго Бо́га на́шего проще́ніє прегріше́ній на́ших, дарова́ніє нам грі́шним христия́нськия кончи́ни живота́ на́шего і Ца́рствія Небе́снаго наслі́діє, да сподо́бимся с Тобо́ю і со всі́ми Святи́ми во Ві́ки воспіва́ти Бо́гу і Спаси́телю на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом уподо́бился єси́, Богому́дре О́тче Варлаа́ме, непоро́чним житіє́м Твої́м на землі́: доброді́тельми укра́шен, пресели́лся єси́ от землі́ на Не́бо, ди́вний о́браз соверше́нства духо́внаго нам оста́вив, да подража́єм доброді́телем Твої́м. Ти же со А́нгели і всі́ми святи́ми предстоя́ Престо́лу Го́спода Сла́ви, моли́ся о нас, почита́ющих Тя і во умиле́нії зову́щих Ті такова́я:","Ра́дуйся, О́трасле Богодарова́нная ко́рене благочести́ваго;","ра́дуйся, Вели́каго Нова́града Прозябе́ніє пречестно́є.","Ра́дуйся, Ча́до возлю́бленноє Благода́ті Ду́ха Бо́жия іспо́лненноє;","ра́дуйся, Отроча́ Боголюбе́зноє.","Ра́дуйся, ізмла́да Боже́ственними Писа́ньми ду́шу Твою́ наси́тивий;","ра́дуйся, во мла́дости му́дрость ста́рця стяжа́вий.","Ра́дуйся, воздержа́нієм роди́телі Твоя́ ізуми́вий;","ра́дуйся, смире́нієм і послуша́нієм мно́гих удиви́вий.","Ра́дуйся, ю́ность Твою́ Непоро́чностію житія́ украси́вий;","ра́дуйся, целому́дріє ді́вства невреди́мо сохрани́вий.","Ра́дуйся, от ю́ности в же́ртву Благоприя́тну Го́сподеві Сам Себ'я́ принеси́й;","ра́дуйся, во всем житії́ єди́но попече́ніє імі́вий є́же Трийпоста́сному Бо́гу то́кмо служи́ти.","Ра́дуйся, Варлаа́ме, Вели́кий і Пресла́вний Чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний Чудотво́рче, і ізря́дний Уго́дниче Христо́в, мно́гим воздержа́нієм на землі́ житіє́ Твоє́ украси́вий; сего́ ра́ди і вінце́м от Христа́ на Небесі́ вінча́нний, і с ві́рою приходя́щим істоча́яй многоціле́бния да́ри. Восхваля́єм Тя, Засту́пника на́шего, преподо́бне О́тче Варлаа́ме: Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Варлаа́ме, вели́кий і пресла́вний чудотво́рче."]},{"h":"Молитва","ps":["О, преподо́бне і богоно́сне о́тче наш Варлаа́ме! Усли́ши нас моля́щихся тебі́ і бу́ди нам помо́щник в ско́рбіх на́ших, і ізба́ви нас от напа́стей, за мно́жество прегріше́ній находя́щих на ни; умоли́, уго́дниче Христо́в, всеблага́го Бо́га дарова́ти нам оставле́ніє всіх от ю́ности на́шея до настоя́щаго дне і часа́, ді́лом, сло́вом, помишле́нієм і всі́ми чу́встви соді́янних на́ми согріше́ній, ісхода́тайствуй нам невозбра́нний вход в Небе́сноє Ца́рствіє, да прославля́єм непреста́нно сла́вимую от а́нгел всесвяту́ю Тро́йцю: Отця́, і Си́на, і Свята́го Ду́ха, і твоє́ ми́лостивноє предста́тельство в безконе́чния ві́ки. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Богодухо́вния благода́ті іспо́лнився / і разже́гся любо́вію Животворя́щия Тро́йці, / млад яви́ся Бо́гу угожда́яй, / ревну́я святи́м отце́м преподо́бним, / вели́кия труди́ возлюби́в, / і поне́сл єси́, і де́монськия посрами́в, мно́жества низложи́л єси́, / і преста́вися во ві́чний поко́й, / і ни́ні подає́ши прося́щим неоску́дноє ісціле́ніє, / ісціля́я многоразли́чния неду́ги, / мо́лимтися, святи́й преподо́бне о́тче Варлаа́ме, // непреста́нно моли́ся ко Го́споду о душа́х на́ших."]},{"h":"Кондак, глас 8","ps":["Я́коже други́й Ілия́ о́тче, дождь с небесе́ свел єси́: / он у́бо огнь сведе́, і царя́ удиви́, / ти же лю́ди твоя́ возвесели́л єси́, / і торжествова́ти устро́їл єси́. / Вели́кий бо Новгра́д вельми́ тобо́ю хва́литься, / імі́я мо́щі твоя́ в себі́, / єго́же сохраня́й от враг непоколеби́ма, да зове́м ті: // ра́дуйся, преподо́бне Варлаа́ме, о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Варлаа́ме, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобним Сергію і Герману, Валаамським","e":"Akathist to the Venerable Sergius and Herman of Valaam","secs":[{"h":"Кондак 1","ps":["Возбра́нним на́шего спасе́нія побо́рником і те́плим к Бо́гу моли́твенником похва́льноє Вам, преподо́бнії, прино́сим пі́ніє. Ви же, я́ко іму́щії дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́те, зову́щих:","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Ікос 1","ps":["А́нгельськи на землі́ пожи́вше, со а́нгели ни́ні на Небесі́ водворя́єтеся, отці́ преподо́бнії, сві́том трисо́лнечним осіява́ємі і боже́ственния добро́ти лицезрі́нія наслажда́ющеся. Ті́мже і нас, чад ва́ших, па́м'ять ва́шу любо́вію пра́зднующих і с ві́рою под о́тчий кров ваш прибіга́ющих, у Престо́ла Царя́ Сла́ви Христа́ не забу́діте, вопію́щих вам такова́я:","Ра́дуйтеся, в ра́дость Го́спода своєго́ вше́дшії:","ра́дуйтеся, вінці́ нетлі́нния от Него́ приє́мшії.","Ра́дуйтеся, Небе́снаго Сіо́на прекра́снаго гра́ждане:","ра́дуйтеся, ві́чнаго Ца́рствія Христо́ва наслі́дници.","Ра́дуйтеся, в жи́зні земні́й єди́наго Христа́ всім се́рдцем возлюби́вшії і Того́ єди́наго взиска́вшії:","ра́дуйтеся, любве́ ра́ди Єго́ вся преобидевшії і ми́ра кра́сная презрі́вшії.","Ра́дуйтеся, непреста́нним боже́ственним раче́нієм преви́ше ви́димих воспарившії:","ра́дуйтеся, дія́нієм виді́ніє стяжа́вшії.","Ра́дуйтеся, у́ми зря́щії Бо́га:","ра́дуйтеся, неусипния моли́тви істо́чници.","Ра́дуйтеся, Валаа́му ізря́дная похвало́:","ра́дуйтеся, ми́ру світи́льници.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 2","ps":["Ви́дяще преподо́бнії земни́я добро́ти непостоя́нноє і сла́ви житія́ сего́ суєту́, Оте́чество своє́ і сро́дники і дру́ги оста́виша, і от полу́денния страни́ к чужде́му і хладному сі́веру устреми́шася. Христо́ві бо тща́хуся невозбра́нно послужи́ти, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума духо́внаго і землі́ безстра́стія обетованния взиску́юще, Авраа́млю проізволе́нію подражасте, преподо́бнії, зе́млю Оте́чества своєго́ оста́вльше і в пусти́ні сей би́вше прише́льці. Ті́мже да́же і додне́сь свята́я оби́тель Валаамськая, на па́жити ва́шей вселящися, неуста́нно вопіє́ть вам се́рдцем і усти́:","Ра́дуйтеся, сі́м'я свято́є, землі́ сея́ стоя́ніє:","ра́дуйтеся, люде́й, о́крест живу́щих, Христо́ві присвоє́ніє.","Ра́дуйтеся, безпло́дную пусти́ню сію́ слез свої́х тече́ньми вспоївшії:","ра́дуйтеся, хла́дную страну́ сію́ моли́тв теплото́ю согреявшії.","Ра́дуйтеся, сла́вії доброгласнії, ра́йськую ве́сну от полу́дня нам прине́сшії:","ра́дуйтеся, гре́чеськаго ке́дра отра́сли ізбра́нния, і́ночества сад в горі́ сей прорастшия.","Ра́дуйтеся, я́ко Христа́ стяжа́сте в се́рдці своє́м:","ра́дуйтеся, я́ко Тро́йці яви́стеся чи́стоє жили́ще.","Ра́дуйтеся, привре́менними ві́чная купившії:","ра́дуйтеся, тлі́нними нетлі́нная наслі́довавшії.","Ра́дуйтеся, бога́тства неіждиваємаго блазі́ї рачи́тели:","ра́дуйтеся, би́сера до́браго вели́ції купці́.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 3","ps":["Си́лі от Ви́шняго предложе́нію ва́шему приложшейся, не всу́є тружда́стеся, преподо́бнії: Той бо бі вам стіна́ крі́пка от лиця́ вра́жия, ка́мень терпі́нія і му́жества сподвижник. Ду́хом же Єго́ услажда́єми і от си́ли в си́лу восходя́ще, сподо́бистеся і ча́сти ізбра́нних Єго́, с ни́миже зовете́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще ум богоприя́тен і ангеловидноє своє́ обіща́ніє непоколеби́мо на краєсекомом ка́мені ві́ри во Христа́, не разслабі́ша в по́двизіх свої́х преподо́бнії, ні возврати́шася всп'ять к па́м'яті пре́жняго житія́ мирська́го, но под'ятий на ся крест да́же до сме́рти понесоша і вся Христа́ ра́ди сла́дці претерпі́ша. Сего́ ра́ди і Бог я облагодати́ і а́нгельськи зрі́ти Єго́ чи́стим се́рдцем сподо́би, да і ми, житію́ їх подража́юще, усе́рдно зове́м к ним:","Ра́дуйтеся, гла́са Євангелськаго і́стиннії послу́шници:","ра́дуйтеся, Зако́на Христо́ва усе́рднії творці́.","Ра́дуйтеся, Го́споду своєму́ до сме́рти послужи́вшії:","ра́дуйтеся, я́зви Єго́ ви́ну на ті́лі своє́м носи́вшії.","Ра́дуйтеся, я́ко Ца́рствія ра́ди Небе́снаго ні в чесо́м же сами́х себі́ пощадили єсте́:","ра́дуйтеся, я́ко а́нгельським о́бразом обле́кшеся, до конця́ брань свою́ соверши́ли єсте́.","Ра́дуйтеся, Христо́ві ору́жници ві́рнії:","ра́дуйтеся, врага́ неустаннії запинателі.","Ра́дуйтеся, пусти́ні сла́дкоє прозябе́ніє:","ра́дуйтеся, воздержа́нія неув'яда́ємий цві́те.","Ра́дуйтеся, благода́ті сосу́ди ізбра́ннії:","ра́дуйтеся, ві́ри подви́жници.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 4","ps":["Бу́рю проти́вних ві́тров а́ще і воздви́же на преподо́бния дия́вол, оба́че потопи́ти їх не возмо́же, ніже́ гра́да душе́внаго їх разори́ти. Ті́ї бо щито́м ві́ри огра́ждшеся і меч моли́тви вращающе, вся стрі́ли лука́ваго нетру́дно угашаху, Христу́ пою́ще: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шана бисть, преподо́бнії, духо́вних по́двигов ва́ших молва́ і моли́тви непреста́нноє горе́ніє і житія́ во́льноє озлобле́ніє: не мо́жеть бо град укри́тися, вверху гори́ стоя́й. Сего́ ра́ди, я́ко єле́ни на істо́чники водни́я, всі а́лчущії покая́нія і жа́ждущії пра́вди, о Го́споді ревну́юще, к вам притеко́ша, і се оби́тель свята́я созда́ся і пусти́ня Валаамськая а́ки град благоцвіту́щ показа́ся. Ті́мже о мно́жестві спаса́ємих веселя́щеся, воспіва́єм вам си́це:","Ра́дуйтеся, оби́телі ва́шея первонача́льници:","ра́дуйтеся, вели́каго і́ноков со́нма отці́.","Ра́дуйтеся, покая́нія от жи́зні своєя́ пропові́дници:","ра́дуйтеся, люботруднаго житія́ законополо́жници.","Ра́дуйтеся, я́ко на па́жити спаси́тельния мно́гі о́вці ізведо́сте:","ра́дуйтеся, я́ко Христа́ о мно́жестві ка́ющихся возрадовасте.","Ра́дуйтеся, дух пра́вий спасе́нія в лю́діх обновившії:","ра́дуйтеся, ре́вность о Бо́зі в сердця́х уни́лих возжегшії.","Ра́дуйтеся, душ христия́нських возста́ніє:","ра́дуйтеся, спя́щих злі пробужденіє.","Ра́дуйтеся, к Небе́сному Ца́рствію ко́рмчії:","ра́дуйтеся, пестуни во Христа́.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 5","ps":["Боготе́чния я́ко зві́зди, на сі́вері не́ба возшли́ єсте́, преподо́бнії, і сві́том ві́ри і по́двиг ва́ших страну́ Каре́льськую просвіти́ли єсте́, уча́ще приходя́щия к вам лю́ди суєві́рія і бісо́вськия оби́чаї отложи́ти і єди́наго то́чію Бо́га боя́тися і Єму́ єди́ному служи́ти, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше о́крест себі́ ча́да своя́, нося́щая ві́тві благодія́нія, возвесели́шася преподо́бнії і, я́ко віне́ць житія́, блаже́нную кончи́ну улучи́вше, ра́дующеся к небесі́ прейдо́ша, оба́че сою́за любве́ не расторго́ша, ніже́ ча́да своя́ оста́виша си́ра: не оскуді́ша бо і по сме́рті за ня Христу́ ви́ну моля́щеся і во іскуше́ніїх і біда́х я назира́юще і спаса́юще. Сего́ ра́ди сли́шаху от них такова́я:","Ра́дуйтеся, в ну́ждах на́ших помо́щници:","ра́дуйтеся, в ско́рбіх уті́шители.","Ра́дуйтеся, язв гріхо́вних ціли́телі:","ра́дуйтеся, бісо́вських наважде́ній отгнателі.","Ра́дуйтеся, ви бо колі́на, уни́нієм разсла́бленная, ско́ро укріпля́єте:","ра́дуйтеся, ви бо угасающия світи́льники на́ша єле́єм моли́тв ва́ших ісполня́єте.","Ра́дуйтеся, страстьми́ порабоще́нних ско́рії свободители:","ра́дуйтеся, подви́жников ко спасе́нію неле́стнії вожди́.","Ра́дуйтеся, цілому́дрія на́шего блюсти́телі:","ра́дуйтеся, нестяжа́нія ізві́стноє пра́вило.","Ра́дуйтеся, крі́пкоє на́ше огражде́ніє:","ра́дуйтеся, непости́дноє на́ше упова́ніє.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 6","ps":["Пропові́дници Сла́ви Бо́жия і по сме́рті яви́стеся, преподо́бнії, от ра́ки честни́х моще́й ва́ших неоску́дния струї́ ісціле́ній істоча́юще і всім тре́бующим разли́чная дарова́нія подаю́ще, я́же ви́дівше ча́да ва́ша благода́рно воспі́ша просла́вльшему вас Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вше па́ки і па́ки сла́ва ва́ша, преподо́бнії, і оби́тель ва́ша возраста́ше і мно́жашеся, а́ще і многаші нечести́вії воєва́ху ю, хра́ми єя́ разоря́юще і і́ноки ізбивающе і ізгоняюще: от жива́ бо су́ща, а́ще і посі́чена, ко́рене па́ки і па́ки лі́торасль восхожда́ше і мно́гі доброді́телей подви́жники под сінь свою́ собира́ше, да злостраждуще за Христа́, в терпі́нії стяжава́ють ду́ші своя́, вам же, я́ко первоначальником свої́м, воспіва́ють си́це:","Ра́дуйтеся, світи́ла ві́ри, при́сно возсіява́ющая:","ра́дуйтеся, істо́чници моли́тви, ніколи́же оскудевшії.","Ра́дуйтеся, хлі́бе сла́дкий і́щущим покая́нія:","ра́дуйтеся, питіє́ безсме́ртноє подви́жником поще́нія.","Ра́дуйтеся, ви бо би́сте благода́тноє всім смире́нним прибі́жище:","ра́дуйтеся, ви бо показа́стеся недви́жноє послу́шним утвержде́ніє.","Ра́дуйтеся, ізгна́нним пра́вди ра́ди готовії спу́тници:","ра́дуйтеся, оби́димих за Христа́ соприча́стници.","Ра́дуйтеся, ни́щих ду́хом сожи́тели:","ра́дуйтеся, кро́тких се́рдцем собесі́дниці.","Ра́дуйтеся, злострада́нія живі́ї о́бразі:","ра́дуйтеся, терпі́нія независтнії да́телі.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 7","ps":["Хотя́ще нечести́вії сві́ї в коне́ць ві́ру правосла́вную істреби́ти, оби́тель Валаа́мськую до основа́нія істощиша, оба́че світи́льника ва́шего угаси́ти не возмого́ша: і́нуді бо преста́вленний, па́че возсія́ на сві́щниці висо́ці, да і та́мо весели́ть ча́да церко́вная і пі́ти Бо́гу подвиза́єть: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий Ісра́їль яви́шася духо́вная ча́да ва́ша, я́же, многоціле́бную ра́ку моще́й ва́ших на ра́мена восприї́мше, от губи́тельства ізбіго́ша: ревнова́ху бо святи́ні не би́ти поруганней от пога́них. Ті́мже і в Но́вград притеко́ша, іді́же все́льшеся і моще́м вас, отце́в свої́х, присідя́ще, не преста́ша за́повіді ва́ша храни́ти і воспіва́ти вам си́це:","Ра́дуйтеся, сокро́вище на́ше некра́домоє:","ра́дуйтеся, світи́льници на́ші неугасимії.","Ра́дуйтеся, вожди́, ніколи́же нас оставля́ющії:","ра́дуйтеся, наста́вници, ви́ну с на́ми су́щії.","Ра́дуйтеся, столпи́ сві́та, путь к небесі́ нам указу́ющії:","ра́дуйтеся, о́блаці благода́ті, от ле́сти нас покрива́ющії.","Ра́дуйтеся, Амали́ка всегуби́теля победнії бори́тели:","ра́дуйтеся, фарао́на ми́сленнаго правіїї обличи́телі.","Ра́дуйтеся, сла́ноє мо́ре суєти́ до́брі преше́дшії:","ра́дуйтеся, в пусти́ню страсте́й му́жественно всельшіїся.","Ра́дуйтеся, небе́сния ма́нни прича́стници:","ра́дуйтеся, нас грі́шних пред Бо́гом спору́чници.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 8","ps":["Странноприємий ра́ку моще́й ва́ших боже́ственне возвесели́ся Вели́кий Но́вград, собо́р святи́х свої́х дві звізді́ приложи́вий, ди́вним сві́том чуде́с сія́ющия і благода́ть ісціле́ній неоску́дно всім подаю́щия. Сего́ ра́ди возопи́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всеці́лою ми́слію у Го́спода водворя́ющеся і зрі́нієм нетлі́нния сла́ви Єго́ наслажда́єми, не небрегли́ єсте́, преподо́бнії, о разоре́нії святи́я оби́телі ва́шея, ніже́ потерпесте, да уга́снеть світи́льник, возжже́нний на Валаа́мі: но неєміїною печа́лію поболі́сте і моли́твою помолистеся, да пору́ган бу́деть дия́вол, злі совещавий на страну́ сію́. Ті́мже моли́твою ва́шею воста́ от пе́пла оби́тель свята́я сія́ і лику́ющи честни́я мо́щі ва́ша от Нова́града гряду́щия сріта́єть, вам же вопіє́ть сицева́я:","Ра́дуйтеся, ра́дости небе́сния ві́стници:","ра́дуйтеся, ми́лости Бо́жия посли́.","Ра́дуйтеся, сла́во на́ша, па́ки воста́вшая:","ра́дуйтеся, ві́нче наш, нам па́ки возданний.","Ра́дуйтеся, я́ко прише́ствієм ва́шим ві́ра пра́вая па́ки зді утверди́ся:","ра́дуйтеся, я́ко світи́льник ві́чния жи́зні па́ки во оби́телі ва́шей возсія́.","Ра́дуйтеся, зла́го на страну́ сію́ сові́та дия́воля разруше́ніє:","ра́дуйтеся, наро́да окрестнаго от ро́ва є́ресі ізбавле́ніє.","Ра́дуйтеся, Це́ркве Правосла́вния но́воє торжество́:","ра́дуйтеся, врат а́дових вя́щшеє посрамле́ніє.","Ра́дуйтеся, а́нгелов го́рніх висо́кая піснь:","ра́дуйтеся, земни́х челові́к ликова́ніє.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 9","ps":["Вся стро́яй о спасе́нії челові́честім, вдал єси́, Христе́, стра́жа До́му Твоєго́ во страні́ сей святу́ю оби́тель на́шу. Не попусти́ у́бо ю уни́нієм воздремати, ні ку́плями жите́йськими отяготитися, ніже́ путь добрі́йший Креста́ Твоєго́ оста́вити, но ку́пно с преподо́бними Твої́ми да ви́ну поє́ть Ті: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ям многовіща́нним ві́ка сего́ юро́дство єсть є́же мир возненави́діти і плоть свою́ умертви́ти: недоумі́ють бо духо́вная духо́вними востя́зовати, ніже́ жи́зні сокрове́нния во Христі́ пости́гнути, я́же утаї́ Бог от прему́дрих і разу́мних і откри́ младе́нцем. Ті́мже, преподо́бнії, я́ко Ца́рствія Небе́снаго наслі́дници і благода́тния ра́дости о́бщници, моли́твою ва́шею ви́ну наста́віте нас, да тще́тния пре́лести житія́ сего́ ізби́вше, невозвра́тним по́мислом по́прище на́ше тече́м, пою́ще вам такова́я:","Ра́дуйтеся, духо́внаго любому́дрія подателі:","ра́дуйтеся, безстра́стія сосу́ди.","Ра́дуйтеся, чистоти́ серде́чния сокро́вища:","ра́дуйтеся, смире́нія зерца́ло.","Ра́дуйтеся, ви бо му́дрих ми́ра сего́ яви́стеся посрамле́ніє:","ра́дуйтеся, ви бо юро́дивих о Христі́ би́сте похвала́.","Ра́дуйтеся, я́ко ва́ми врага́ низлага́єм хоті́нія:","ра́дуйтеся, я́ко ва́ми суєти́ отріва́єм прило́ги.","Ра́дуйтеся, во бра́ніх духо́вних нам посо́бници:","ра́дуйтеся, во іскуше́ніїх всемощнії засту́пниці.","Ра́дуйтеся, обурева́ємих приста́нище:","ра́дуйтеся, немощни́х ісціле́ніє.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 10","ps":["Спаси́тельний путь поста́ возлюби́вшії і яре́м Христо́в на ся во́лею взе́мшії, прийді́те всі к сему́ ти́хому от бу́рі гріхо́вния приста́нищу, в покая́нії припаде́м к неосла́бним моли́твенником на́шим і отце́м, я́ко моли́твою їх при́сно воздвиза́ємі, обря́щем сла́ву і воспоє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єсте́ оби́телі ва́шей і всім с ві́рою к вам притека́ющим, преподо́бнії: ва́шим бо бо́дренним заступле́нієм собла́зни ми́ра отгоня́ються і страсте́й взигра́нія угашаються. Ті́мже мо́лим вас: не отри́ніте нас в не́мощіх на́ших, во іскуше́ніїх і ско́рбіх. Внегда́ оскудіва́ти духо́вній крі́пости на́шей, не оста́віте нас, но бу́діте нам при́сноє защище́ніє, покро́в же і отра́да, да воспоє́м вам благодаря́ще:","Ра́дуйтеся, пусти́нних ти́хоє утіше́ніє:","ра́дуйтеся, уєдине́нних та́йноє ра́дованіє.","Ра́дуйтеся, в моли́тві пребива́ющих незримії сомолитвенници:","ра́дуйтеся, во благогові́нії су́щих благодатни сподви́жници.","Ра́дуйтеся, наста́вници на́ші, і́миже к соверше́нству призиваємся:","ра́дуйтеся, отці́ на́ші, і́миже по́стничества жела́ннаго конця́ доспі́ти упова́єм.","Ра́дуйтеся, крі́посте на́ша, є́юже сті́ну гріха́ на́шего пре́йдем:","ра́дуйтеся, утвержде́ніє на́ше, і́мже тяготу́ зло́би на́шея отлага́єм.","Ра́дуйтеся, гріхми́ обремене́нних любвеобильнії восприємници:","ра́дуйтеся, ка́ющихся те́плі блазі́ї хода́таї.","Ра́дуйтеся, ю́ноши к цілому́дрію возводя́щії:","ра́дуйтеся, ста́рцем терпі́ніє подаю́щії.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 11","ps":["Пі́нію немолчному безпло́тних подража́юще і на жесто́коє житіє́ отце́в на́ших взира́юще, не обліні́мся, о бра́тіє: возлю́бим в моли́твах всенощноє бді́ніє, не устраші́мся тлі́нния пло́ті утісне́нія, да преподо́бним на́шим соприча́стници бу́дем і со а́нгели воспоє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рния світи́льники, сві́том і́стиннаго благоче́стія сі́верную страну́ сію́ просвіща́ющия, зрим ви, преподо́бнії: в земні́м бо житії́ ва́шем мно́гі от ле́сти бісо́вськия ко Христу́ приведо́сте, і по сме́рті то́ки благода́тних дарова́ній ізлива́юще і оби́тель свою́ во благогові́нії і трудолюбії содержа́ще, правосла́вную ві́ру зді утверждаєте, і вся окре́стния лю́ди духо́вним хлі́бом питаєте, і от Люторова па́губнаго нече́стія і тьми неві́дінія ізбавля́єте. Сего́ ра́ди приймі́те от нас сицева́я:","Ра́дуйтеся, і́стини неле́стнії свиді́теліє:","ра́дуйтеся, мра́чних суєві́рій отгнателі.","Ра́дуйтеся, Си́ли Бо́жия ди́вноє явле́ніє:","ра́дуйтеся, благода́ті Христо́ви чу́дноє зна́меніє.","Ра́дуйтеся, ва́ми бо Ца́рствіє Бо́жиє в се́рдця мно́гих при́йде:","ра́дуйтеся, ва́ми бо Денни́ця і́стиннаго сві́та во омраче́нних гріхо́м возсія́.","Ра́дуйтеся, вра́чеве святі́ї, сумнящихся ду́ші благода́тно ісціля́ющії:","ра́дуйтеся, па́стиріє до́брії, о́вці своя́ от че́люстей звіри́них ізимающії.","Ра́дуйтеся, правосла́вним Христо́во благоуха́ніє:","ра́дуйтеся, єретичествующим сме́ртная воня́.","Ра́дуйтеся, Карелії сла́внії апо́столи:","ра́дуйтеся, Украї́нськия землі́ украше́ніє.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 12","ps":["Благода́тію Твоє́ю боже́ственною раздра́в гріх на́ших рукописа́ніє, благода́ть Твоєго́ синоположе́нія обнови́ в нас, Сло́ве Бо́жий, і даждь нам про́чеє в покая́нії благоугоди́ти Тебі́, да с преподо́бними Твої́ми воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пресланую па́м'ять ва́шу, єли́ко по си́лі на́шей, восхваля́єм вас, преподо́бнії: ви бо, же́ртву чи́сту себі́ Христо́ві прине́сше, всім вся би́сте і всім прося́щим ту́не вся потре́бная подаєте́, да всі, благодаре́нію поучи́вшеся, в покая́ніє і ісправле́ніє при́йдем, вас же воспоє́м си́це:","Ра́дуйтеся, смире́нних мольба́м внимателі:","ра́дуйтеся, убо́гих воздиха́нія послу́шателі.","Ра́дуйтеся, вдов і сиро́т наказа́телі і кормители:","ра́дуйтеся, оби́димих отра́до і утіше́ніє.","Ра́дуйтеся, в ну́ждах і обстоя́ніїх су́щих ско́роє і ізві́стноє ізбавле́ніє:","ра́дуйтеся, всіх к ра́ці моще́й ва́ших с ві́рою притека́ющих незави́стноє ісціле́ніє і спасе́ніє.","Ра́дуйтеся, предста́телі на́ші, умиле́нния сле́зи на́ша приє́млющії:","ра́дуйтеся, моли́твенниці на́ші, во благи́х проше́нія ві́рних ісполня́ющії.","Ра́дуйтеся, мона́шествующих всегда́ гото́воє прибі́жище:","ра́дуйтеся, мирськи́х челові́к упова́ніє.","Ра́дуйтеся, госуда́рства на́шего крі́посте:","ра́дуйтеся, Це́ркве Правосла́вния удобре́ніє.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 13","ps":["О всепі́тії і пресла́внії чудотво́рці на́ші і моли́твенниці, Се́ргіє і Ге́рмане преподо́бнії! Ни́нішнєє смире́нноє приноше́ніє от недосто́йних чад ва́ших приє́мше, от вся́ких напа́стей, скорбе́й і болі́зней, наві́тов вра́жиїх і обстоя́ній ізба́віте нас, і в стра́шний час сме́ртний бу́діте нам крі́пції предста́телі, я́ко да ві́чния сме́рти ізба́вльшеся, воспоє́м просла́вльшему вас Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськи на землі́ пожи́вше, со а́нгели ни́ні на Небесі́ водворя́єтеся, отці́ преподо́бнії, сві́том трисо́лнечним осіява́ємі і боже́ственния добро́ти лицезрі́нія наслажда́ющеся. Ті́мже і нас, чад ва́ших, па́м'ять ва́шу любо́вію пра́зднующих і с ві́рою под о́тчий кров ваш прибіга́ющих, у Престо́ла Царя́ Сла́ви Христа́ не забу́діте, вопію́щих вам такова́я:","Ра́дуйтеся, в ра́дость Го́спода своєго́ вше́дшії:","ра́дуйтеся, вінці́ нетлі́нния от Него́ приє́мшії.","Ра́дуйтеся, Небе́снаго Сіо́на прекра́снаго гра́ждане:","ра́дуйтеся, ві́чнаго Ца́рствія Христо́ва наслі́дници.","Ра́дуйтеся, в жи́зні земні́й єди́наго Христа́ всім се́рдцем возлюби́вшії і Того́ єди́наго взиска́вшії:","ра́дуйтеся, любве́ ра́ди Єго́ вся преобидевшії і ми́ра кра́сная презрі́вшії.","Ра́дуйтеся, непреста́нним боже́ственним раче́нієм преви́ше ви́димих воспарившії:","ра́дуйтеся, дія́нієм виді́ніє стяжа́вшії.","Ра́дуйтеся, у́ми зря́щії Бо́га:","ра́дуйтеся, неусипния моли́тви істо́чници.","Ра́дуйтеся, Валаа́му ізря́дная похвало́:","ра́дуйтеся, ми́ру світи́льници.","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Кондак 1","ps":["Возбра́нним на́шего спасе́нія побо́рником і те́плим к Бо́гу моли́твенником похва́льноє Вам, преподо́бнії, прино́сим пі́ніє. Ви же, я́ко іму́щії дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́те, зову́щих:","Ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Молитва","ps":["О, вели́ції отці́ на́ші, Христо́ви уго́дниці і те́плії предста́телі ко Спа́су о душа́х на́ших, Се́ргіє і Ге́рмане! Ви бо в неду́зіх ціли́телі яви́стеся, по мо́рю пла́вающим ко́рмчії, і утопа́ющим благонаде́жноє ізбавле́ніє, і от вся́каго смертоно́снаго наше́ствія храни́тели, па́че же от духо́в нечи́стих свобожде́ніє і вся́ких наві́тов, проти́ву нас содержи́мих, очище́ніє і по́мощ. О, преблаже́ннії отці́ і чудотво́рці пресла́внії, Се́ргіє і Ге́рмане, молі́теся ко Влади́ці Христу́ о нас, грі́шних, я́ко да ва́шими моли́твами сподо́бимся в день Су́дний десна́го предстоя́нія і наслажде́нія во Ца́рствії Бо́жії во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, преподо́бнії і Богоно́снії отці́ на́ші Се́ргіє і Ге́рмане! С ві́рою і любо́вію припа́даюше к святі́й іко́ні ва́шей, умиле́нно мо́лим вас: не забу́діте нас, недосто́йних і грі́шних (імена́), но предста́тельством ва́шим огради́те нас от злих ко́зней вра́жиїх: утолі́те возста́ніє страсте́й: укріпі́те не́мощ на́шу в духо́вних бра́ніх і по́двизіх, предлежа́щих нам: отжені́те вся́коє уни́ніє і печа́ль гріхо́вную от серде́ць на́ших, і Небе́сноє утіше́ніє низпослі́те нам во труді́х і ско́рбіх на́ших. В стра́шний же час сме́ртний предста́ніте всім нам, я́ко же блазі́ї хода́таї і те́мних зра́ков де́монських прогони́теліє: да в ми́рі і покая́нії сконча́вше земно́є по́прище на́ше, дости́гнем і ві́чних благ наслажде́нія, і ку́пно с ва́ми да воспоє́м і просла́вим всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Єва́нгелія Христо́ва і́стиннії послу́шници / яви́стеся, преподо́бнії, / мир і вся я́же в нем, я́ко не су́щая, / преоби́дівше любве́ ра́ди Христо́ви / і в морськи́й о́стров всели́стеся, / і трудолю́бно в нем проти́ву ко́зней неви́димих враго́в подвиза́стеся, / посто́м, бді́нієм же і всено́щним стоя́нієм / пло́ті своя́ ду́ху му́дру повину́ли єсте́. / Сего́ ра́ди от Вседержи́тельния десни́ці досто́йния вінці́ прия́ли єсте́. / І ни́ні Пресвяті́й Тро́йце предстоя́ще, / молі́теся, всеблаже́ннії отці́, Се́ргіє і Ге́рмане, / сохрани́тися в ми́рі оте́честву на́шему // і спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["От мирська́го житія́ ізше́дше, / отверже́нієм ми́ра Христу́ послі́довасте, / і достиго́сте вели́каго Не́ва є́зера, / і, в нем на о́строві Валаа́мі все́льшеся, / равноа́нгельноє житіє́ пожи́ли єсте́, / отону́дуже, веселя́щеся, прешли́ єсте́ к Небе́сним черто́гом. / І ни́ні со А́нгели Влади́чню Престо́лу предстоя́ще, / помина́йте нас, чад свої́х, / я́же собра́ли єсте́, богому́дрії, / да ра́достно от душі́ вопіє́м: // ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Величання","ps":["Ублажа́єм вас, / преподо́бнії отці́ Се́ргіє і Ге́рмане, / і чтим святу́ю па́м'ять ва́шу, / наста́вници мона́хов / і собесі́дниці а́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Андрію Рубльову, іконописцю","e":"Akathist to our Venerable Father Andrei Rublev, the Iconographer","secs":[{"h":"Кондак 1","ps":["І́стиннаго богосло́вія обрі́теніє, преподо́бне Андре́є, позна́во Всесвяту́ю Тро́йцю во Єди́ниці, начерта́л єси́ ізображе́нія свята́я, чудеса́ми просла́вленная, мир просвіща́ющая. Імі́яй дерзнове́ніє ко Пресвяті́й Тро́йце, моли́ просвіти́ти і на́ша душі́, да зове́м ті:","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Ікос 1","ps":["А́нгельськаго житія́ от ю́ности твоєя́ возжада́л єси́, преподо́бне: у́бо ко святі́й оби́телі вели́каго Се́ргия прите́кл єси́ і в послуша́нії а́вві землі́ ру́ськия, до́ндеже призва́ тя Госпо́дь в небе́сную оби́тель, живописа святі́ї о́брази єси́ і ни́ні благода́ть да́руяй всім припадающим к ним. Ті́мже і ми благода́рно вопіє́м ті:","Ра́дуйся, а́нгельськую чистоту́ возлюби́вий;","Ра́дуйся, во а́нгельстім о́бразе послужи́вий;","Ра́дуйся, в оде́жду послуша́нія облаченний;","Ра́дуйся, тезоіме́нний хра́брости, во і́ночестві Андре́єм нарече́нний.","Ра́дуйся, смире́нія ра́ди мирсько́є і́м'я сокри́вий;","Ра́дуйся, смире́нія о́брази на іко́нах яви́вий.","Ра́дуйся, Безнача́льния Тро́йці во Єди́ниці воспевателю;","Ра́дуйся, Трисві́тлаго Бо́га служи́телю.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 2","ps":["Ви́дя скорб і разоре́ніє землі́ ру́ськия от нечести́вих, Андре́є сла́вне, оста́вил єси́ наде́жду на князе́й і возложи́в єя́ на Єди́наго Человіколю́бця, науча́єши і нас с ві́рою взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богоозаренний, Андре́є всехва́льне, стяжа́в, в істощенней наше́ствії іноплеме́нними землі́ возскорбел єси́ оскудевшаго ві́рою Оте́чествія ра́ди і служи́телем Спаси́теля стал єси́. Сего́ ра́ди ми с любо́вію восклиця́єм ті:","Ра́дуйся, ско́рби землі́ ру́ськия в своє́ се́рдце сложивий;","Ра́дуйся, сосу́дом Бо́жиїм послужи́вий.","Ра́дуйся, полона іноплеме́ннаго ізбіжа́л єси́;","Ра́дуйся, от плі́на страсте́й се́рдце удержа́л єси́.","Ра́дуйся, в оби́телі Святи́я Тро́йці ду́хом возраста́вий;","Ра́дуйся, Трийпоста́сноє Божество́ воспевавий.","Ра́дуйся, в любві́ Христо́ві ни́ні пребива́єши;","Ра́дуйся, нас во ві́рі, наде́жде і любві́ укріпля́єши.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 3","ps":["Си́лою Всеви́шняго притекла́ благода́ть к воздви́женію монастиря́ Нерукотворе́ннаго о́браза Спасова, во́лею Го́спода напра́вился ти, преподо́бне, к сему́ мі́сту свято́му і піл єси́ Бо́гу піснь а́нгельськую: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я се́рдце, послу́шноє Бо́гу і а́вві Се́ргію, в оби́тель на Яузі ріці́ ко свято́му Андрони́ку напра́вился єси́, Андре́є богому́дре, ві́дал бо преподо́бний Се́ргій гряду́щеє прославле́ніє тобо́ю і́мені Бо́жия во гра́ді Москві́. Ми же, див'я́ся Бо́жию промишле́нію, воспіва́єм ті такова́я:","Ра́дуйся, благода́тію Бо́жиєю в град Москву́ приведенний;","Ра́дуйся, ко свято́му іконописательству опреділе́нний.","Ра́дуйся, іску́снаго живопи́сця Даниї́ла спо́стника обрі́л єси́;","Ра́дуйся, дар образописанія растил єси́.","Ра́дуйся, Єва́нгелія в красках воплотителю;","Ра́дуйся, Нерукотворе́ннаго Спа́са ізобрази́телю.","Ра́дуйся, я́ко іко́ни твоя́ свиді́тельство правосла́вния ві́ри яви́ли;","Ра́дуйся, я́ко чрез тебі́ явле́нния о́брази вселе́нную просвіти́ли.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 4","ps":["Бу́рею жите́йськаго мо́ря сокруша́єми єсьми́, созерцанієм ми́ра го́рняго на іко́нах твої́х, Андре́є пречу́дне, ти́хоє приста́нище обріта́єм. І сві́том ди́вним озарени єсьми́, поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав, созда́телю іко́н ди́вних, посвященіє вре́мені пра́здников Бо́гу Єди́ному, сі́ї дні не писа́л єси́ образо́в, но святи́я іко́ни созерца́л єси́. Ті́мже ті рцем такова́я:","Ра́дуйся, во дні Госпо́дськия і Богоро́дичния созерцанієм іко́н к первообразам восходивий;","Ра́дуйся, сле́зними мольба́ми у Го́спода по́двига іконописательства іспроси́вий.","Ра́дуйся, я́ко Пе́рвому Творцю́ іко́н, созда́вшему ве́тхаго Ада́ма уподо́блен єси́;","Ра́дуйся, я́ко Іскупи́теля Ада́мова паде́нія в ликах воплотил єси́.","Ра́дуйся, іконотворчеством о́кна в Ца́рство Бо́жиє откри́вий;","Ра́дуйся, себі́ в іко́ну Бо́жию претвори́вий.","Ра́дуйся, я́ко к неви́диму сві́ту ум возно́сиши;","Ра́дуйся, от ми́ра до́льняго к ми́ру го́рнему нас возво́диши.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 5","ps":["Богоро́дицю і Ма́тер Сві́та достойнословля, со тща́нієм писа́л єси́ о́брази Єя́, воздава́я хвалу́ Єди́наго от Тро́йці Бо́га Сло́ва Ро́ждшей, і воспіва́я: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів наше́ствіє гро́знаго врага́, Андре́є святи́й, моли́л єси́ со Це́рковію і всім наро́дом о дарова́нії ізбави от полчищ вра́жиїх. Ра́дость же спасе́нія Держа́вною Помо́щницею гра́да от супоста́та запечатлі́л єси́ в іко́ні Всемилостивия Засту́пниці. Ми же, ви́дя любо́в твою́ ко Пречи́стой, умиле́нно поє́м:","Ра́дуйся, любо́во ве́лію ко Всепі́той Ма́ти імі́яй;","Ра́дуйся, в печа́лі і ско́рби Єй моли́твенно предстоя́й.","Ра́дуйся, защити Оте́чествія ра́ди ко Пресвяті́й Засту́пнице взивавий;","Ра́дуйся, по ізгна́нії сопоста́тних пога́н Присноді́ву велича́вий.","Ра́дуйся, на ру́ку Своє́ю Царя́ Сла́ви несшую превозно́сиши;","Ра́дуйся, рука́ма свої́ма о́браз Присноцарствующей запечатлеваєши.","Ра́дуйся, срі́теніє с Бо́гом в се́рдці храни́вий;","Ра́дуйся, Сретенському монастирю́ о́браз Богома́тері подаривий.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 6","ps":["Пропові́дник живописательний Ца́рствія обітова́ннаго ві́рним бил єси́, і благи́м свої́м житіє́м і ми́лостію Бо́жиєю обрі́л єси́ єго́. Помози́, о́тче, дости́гнути ра́йських блаже́нств і нам, дерзающим взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л дар богодухнове́нний в собо́рній Це́ркві Благові́щенія Пресвяти́я Богоро́диці, єгда́ проро́чеськи созида́л єси́, Андре́є богоізбра́нне, со Феофаном Гречином і ста́рцем Про́хором с Городка. Дивляся виді́нію твоєму́, поє́м:","Ра́дуйся, ізря́дний моли́твенниче і по́стниче;","Ра́дуйся, Андре́є светлоподобниче.","Ра́дуйся, подо́бно ученико́м Христо́вим Фаворським сві́том освяще́нний;","Ра́дуйся, Небе́снаго Влади́ки служи́телю ві́рний.","Ра́дуйся, а́нгелов собесі́дниче;","Ра́дуйся, равноа́нгельнаго житія́ пропові́дниче.","Ра́дуйся, со Феофаном і Про́хором зерца́ло ра́йськаго блажества нам да́руєши;","Ра́дуйся, к Ца́рствію Небе́сному путь показу́єши.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 7","ps":["Хотя́ обнови́ти Успенський собо́р во гра́ді Влади́мире, вели́кий князь призва́ тя со спостником Данії́лом. Ви же дво́їця блаже́нная, возводя́ще ум к Невеще́ственному і Боже́ственному Сві́ту, вознесеста моли́тву: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вия і чу́дния о́брази написа́ли єста́, Данії́ле і Андре́є, во утихновеніє стра́ждущим. Украси́ли єста́ Владимирський собо́р Успе́нія Пресвяти́я Богоро́диці ше́ствієм в рай пра́ведних со святи́ми апо́столи Петро́м і Па́влом во главі́ і Второ́є прише́ствіє Го́спода Ісу́са Христа́ начертали єста́. Ми же, дивляся провозвещенію твоєму́, о́тче Андре́є, глаго́лем:","Ра́дуйся, собо́ра Успе́нія Пресвяти́я Богоро́диці обнови́телю;","Ра́дуйся, Не Оставляющия нас во Успе́нії Своє́м ди́вний похвалителю.","Ра́дуйся, ско́рбноє і сві́тлоє ше́ствіє пра́ведников в рай начерта́л єси́;","Ра́дуйся, а́нгелов огнь іспуска́ющих расписа́л єси́.","Ра́дуйся, Втора́го прише́ствія Го́спода Всеви́шняго прославителю;","Ра́дуйся, пространств і време́н просвіти́телю.","Ра́дуйся, ве́лію ра́дость гра́ду Влади́миру доставляяй;","Ра́дуйся, по оконча́нії трудо́во в Москві́ пребива́яй.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 8","ps":["Стра́нником на землі́ бі єси́ Андре́є светонаставниче, да́ра образописанія ра́ди во ві́си мно́гажди призива́єм. Но і пішеше́ствуя, ум і се́рдце в стоя́нії пред Бо́гом держа́л єси́, непреста́нно воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Ві́си іни́я преукрасив, ста́рче Андре́є, направи́л єси́ стопи́ твоя́ во Звениград, іді́же во собо́рі Успе́нія по благослове́нію свята́го Са́вви ігу́мена созда́л єси́ Деїсус чу́дно велми́. Сего́ ра́ди тебе́ зове́м:","Ра́дуйся, по зову́ Бо́жию стопи́ своя́ в путь направляєши;","Ра́дуйся, ум і се́рдце к стоя́нію пред Бо́гом принуждаєши.","Ра́дуйся, собо́ра Успе́нськаго ди́вний украси́телю;","Ра́дуйся, красоти́ соверше́нния в о́бразі Спасові явителю.","Ра́дуйся, Свяще́ннаго Писа́нія ревни́телю усе́рдний;","Ра́дуйся, Уче́нія Христо́ва живописателю ві́рний.","Ра́дуйся, Святи́я Русі́ прозябе́ніє;","Ра́дуйся, гра́да на́шего заступле́ніє.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 9","ps":["Весь монасти́р разоре́ніє от нечести́ваго кня́зя поне́сл єсть, ти же, Андре́є свя́те, ві́дая о упрежденії бра́тії оби́телі Пресвяти́я Тро́йці а́ввою Се́ргиєм в тонцем сні, возгласи́л єси́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії ка́ко мо́гуть пові́дати скорб і тісноту́ землі́ ру́ськия от наше́ствія кня́зя татарськаго, гра́ди жегущаго і граб'ящаго. Ти же, Андре́є преподо́бне, при́зван бил образописати в ка́меннім хра́мі во і́м'я Пресвяти́я Тро́йці, воздвигнутем вмі́сто сожженния древ'я́ния це́ркві. Мо́лим тебі́: укріпи́ ві́рою се́рдця на́ша, страстьми́ пожженная, і запечатлі́й в них о́браз Пресвяти́я Тро́йці. Ми́лостив бу́ди нам, пою́щим:","Ра́дуйся, свиді́телем спасе́нія бра́тії а́ввою Се́ргиєм ставий;","Ра́дуйся, іко́ну Го́спода Ісу́са Христа́-Спаси́теля написа́вий.","Ра́дуйся, учи́ши бо і по разоре́нії це́ркві не унива́ти;","Ра́дуйся, помога́єши бо кріпча́йший храм воздвиза́ти.","Ра́дуйся, о́брази в оби́телі обновля́єши;","Ра́дуйся, о́браз Бо́жий в сердця́х возставля́ти науча́єши.","Ра́дуйся, хра́ма во і́м'я Пресвяти́я Тро́йці украси́телю;","Ра́дуйся, себі́ в храм Трисія́ннаго Божества́ претворителю.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ зе́млю ру́ськую от розні ми́ра сего́ і па́м'ятуя о ревни́тели Святи́я і Живонача́льния Тро́йці преподо́бном отці́ на́шем Се́ргії, уподо́бился о́тче Андре́є Авраа́му гостеприїмцю, в о́бразі тріє́х стра́нник у ду́ба Мамври́йськаго Єди́наго Го́спода воспринимая, і написа́л єси́ іко́ну Пресвяти́я Тро́йці, непреста́нно моля́ся: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю необоримою бу́ди всім правосла́вним христия́ном, Андре́є славосло́вимий, дерзнове́нно моля́ Пресвяту́ю Тро́йцю о нас, пою́щих тебі́ си́це:","Ра́дуйся, сподо́бился єси́ явле́ніє Триіпоста́снаго Бо́га у ду́ба Мамври́йськаго написа́ти;","Ра́дуйся, помога́єши бо душа́м в Ца́рство Небе́сноє прорастати.","Ра́дуйся, Це́ркві Украї́нськия чу́дний пло́де;","Ра́дуйся, іконописателю та́їнственнаго догма́та Тро́йці.","Ра́дуйся, преподо́бнаго Ни́кона приле́жний послу́шниче;","Ра́дуйся, свята́го Се́ргия Ра́донежськаго чудотво́рця досто́йная похвало́.","Ра́дуйся, тобо́ю бо Єди́нство в Тро́йці Отця́ і Си́на і Свята́го Ду́ха прославля́ється;","Ра́дуйся, воззрі́нієм на чудотво́рния іко́ни твоя́ рознь ми́ра побіжда́ється.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 11","ps":["Пі́ніє а́нгельськоє ублажа тебі́, єгда́ возврати́вся в Андроникову оби́тель, в небе́сния оби́телі пресели́тися гото́вился єси́, вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоявле́нієм во сла́ві Данії́лу спостнику, на одрі́ сме́ртнім лежа́щу призва́л єси́ послі́довати себе́, і срі́тил єси́ с любо́вію от ми́ра сего́ отше́дшаго. Чесо́ ра́ди водворе́ніє тебі́, преподо́бне Андре́є, во Ца́рствіє Пресвяти́я Тро́йці воспіва́єм:","Ра́дуйся, земна́я странства завершивий;","Ра́дуйся, дру́га із ми́ра до́льняго і в ми́рі го́рнем любивий.","Ра́дуйся, свиді́тельство і́стини Правосла́вія всему́ ми́ру явля́єши;","Ра́дуйся, і ни́ні і́стинно Бо́га в Тро́йці прославля́єши.","Ра́дуйся, тала́нт вві́ренних умноже́ніє;","Ра́дуйся, Ца́рствія Святи́я Тро́йці достиженіє.","Ра́дуйся, і по преставле́нії нас не оставля́єши;","Ра́дуйся, ра́дость правосла́вним христия́ном доставляєши.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 12","ps":["Благода́ть хра́ма во і́м'я твоє́, іконопи́сче Андре́є, ізлива́ється о́крест і зове́ть всіх отврати́вся от тлі́ннаго, обрати́ти ум, се́рдце і діла́ к Бо́гу, прославля́я Єго́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще созида́ніє хра́ма твоєго́ в Раменках, ублажа́єм тя, о́тче наш Андре́є, я́ко моли́твеннаго предста́теля за ни Пресвяті́й Тро́йце і возглаша́єм ті такова́я:","Ра́дуйся, нас я́ко о́вчу заблудшую на ра́мена взя́вий;","Ра́дуйся, по прославле́нії мі́стом хра́ма своєго́ Раменки ізбра́вий.","Ра́дуйся, общину ві́рних Пресвяті́й Тро́йце созида́я;","Ра́дуйся, святи́м житіє́м твої́м к свя́тости призива́я.","Ра́дуйся, дерзнове́нієм к позна́нію і́стини поуча́єши;","Ра́дуйся, Отця́ і Си́на і Свята́го Ду́ха прославля́єши.","Ра́дуйся, єди́н із во́їнства Христо́ва;","Ра́дуйся, па́стирю наш предо́брий.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 13","ps":["О ди́вний іконопи́сче, преподо́бне і богоно́сне о́тче Андре́є! Прийми́ с любо́вію тебі́ приноси́моє ма́лоє сіє́ хвале́ніє і моли́ Пресвяту́ю Тро́йцю: да укріпи́ть ві́ру правосла́вную, да ізба́вить нас от розні і сподо́бит со ізбра́нними свої́ми воспіва́ти сла́вимаго в Тро́йці Бо́га: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськаго житія́ от ю́ности твоєя́ возжада́л єси́, преподо́бне: у́бо ко святі́й оби́телі вели́каго Се́ргия прите́кл єси́ і в послуша́нії а́вві землі́ ру́ськия, до́ндеже призва́ тя Госпо́дь в небе́сную оби́тель, живописа святі́ї о́брази єси́ і ни́ні благода́ть да́руяй всім припадающим к ним. Ті́мже і ми благода́рно вопіє́м ті:","Ра́дуйся, а́нгельськую чистоту́ возлюби́вий;","Ра́дуйся, во а́нгельстім о́бразе послужи́вий;","Ра́дуйся, в оде́жду послуша́нія облаченний;","Ра́дуйся, тезоіме́нний хра́брости, во і́ночестві Андре́єм нарече́нний.","Ра́дуйся, смире́нія ра́ди мирсько́є і́м'я сокри́вий;","Ра́дуйся, смире́нія о́брази на іко́нах яви́вий.","Ра́дуйся, Безнача́льния Тро́йці во Єди́ниці воспевателю;","Ра́дуйся, Трисві́тлаго Бо́га служи́телю.","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Кондак 1","ps":["І́стиннаго богосло́вія обрі́теніє, преподо́бне Андре́є, позна́во Всесвяту́ю Тро́йцю во Єди́ниці, начерта́л єси́ ізображе́нія свята́я, чудеса́ми просла́вленная, мир просвіща́ющая. Імі́яй дерзнове́ніє ко Пресвяті́й Тро́йце, моли́ просвіти́ти і на́ша душі́, да зове́м ті:","Ра́дуйся, преподо́бне о́тче Андре́є, іконопи́сче преди́вний."]},{"h":"Молитва","ps":["О, преди́вний іконопи́сче преподо́бне о́тче Андре́є! Усли́ши моле́нія нас, грі́шних, с ві́рою, наде́ждою і любо́вію взива́ющих тебі́, і бу́ди предста́телем на́шим пред Свято́ю Тро́йцею. Твори́вий благода́тно в хра́міх Бо́жиїх, помози́ і нам созида́ти хра́ми во сла́ву Бо́жию. Пости́гнув та́йни красоти́ і́стинния, озари́ нас позна́нієм красоти́ богослуже́нія нетлі́нния. Ісціля́яй ду́ші взира́нієм на іко́ни твоя́, да́руй нам і моще́й твої́х цільбу́. Послужи́вий єдине́нію ві́рних, ісхода́тай і нам єди́ним се́рдцем і єди́ни устни́ восхвали́ти утиша́ющаго ро́зні ми́ра сего́ в Тро́йці сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Андре́є! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х і благоприя́тних моли́твах к Бо́гу: пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х, моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́: не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя: помина́й нас недосто́йних у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши, не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с небе́сними си́лами, у престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться, ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чния му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, преподо́бне о́тче Андре́є, зіло́ облагода́тствованний пресві́тлим да́ром виді́нія первоо́бразов красоти́ Боже́ственних! О, ди́вний пло́де Це́ркве Украї́нськия, о́трасле блага́я Се́ргиєм вели́ким насажде́нного дре́ва! В гро́зноє бо вре́м'я поста́ви тя Госпо́дь свиді́теля своєго́ і землі́ на́шея моли́твенника вели́ка тя соді́ла. Кто іспові́сть безчи́сленния труди́ і по́двиги твоя́, ра́зум земни́й превосходя́щия і єди́ному то́кмо ві́домих Го́споду, і́миже благода́ть писа́нія чудотворя́щих іко́н стяжа́л єси́! Ти благоуха́нієм святи́х твої́х іко́н весь мир іспо́лнил єси́, найпа́че о́бразом Пресвяти́я Тро́йці, да воззрі́нієм нань побіжда́ється вся́кий гріх і ненави́стная рознь ми́ра сего́. О, преподо́бне і пречу́дне о́тче, при́зри с висоти́, іді́же в Боже́ственнім сві́те пребива́єши, і усли́ши моли́тви нас, грі́шних, і, я́ко імі́яй дерзнове́ніє ко Пресвяті́й Тро́йце, со преподо́бним Се́ргиєм і всі́ми святи́ми моли́ Влади́ку всіх, о є́же Це́рков єго́ укріпи́ти, разобще́нних соєдини́ти, расточе́нних собра́ти і в разумі́ніє і́стини всім прийти́, отврати́ти от нас пра́ведний гнів Свой і іспо́лнити даро́в Ду́ха Свята́го, любве́, ра́дости, ми́ра, долготерпі́нія, бла́гости, милосе́рдія, ві́ри, кро́тости, воздержа́нія, земно́є же стра́нствіє прейти́ нам, грі́шним, безбі́дно, в бу́дущем же ві́ці сподо́биться с тобо́ю і всі́ми святи́ми прославля́ти Пресвяту́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Боже́ственнаго сві́та луча́ми облиста́ємий, / преподо́бне Андре́є, / Христа́ позна́л єси́ Бо́жию Прему́дрость і Си́лу, / і іко́ною Святи́я Тро́йці всему́ ми́ру пропові́дал єси́ / Єди́нство во Святі́й Тро́йці. / Ми же со удивле́нієм і ра́достію вопіє́м ті: / імі́яй дерзнове́ніє ко Пресвяті́й Тро́йце // моли́ просвіти́ти ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["От ю́ности к Боже́ственній красоті́ устремля́яся, / чу́дний іконопи́сець в землі́ Украї́нській бил єси́, / і, богоно́сним твої́м учи́телем поревнова́в, / сія́нієм доброді́телей украси́лся єси́, преподо́бне Андре́є, // ті́мже і яви́ся Це́ркве на́шея похвала́ і ра́дованіє."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче наш Андре́є, о́браз Пресвяти́я Тро́йці нам дарова́вий, і тім луча́ми Триіпоста́снаго Божества́ всіх нас просвіти́вий."]}],"notes":[]},{"u":"Акафіст преподобному Афанасію Афонському","e":"Akathist to our Venerable Father Athanasius the Athonite","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от гра́да Трапезу́нта і во Афо́ні по́стничеськи просія́вий, ди́вний подви́жниче і чудотво́рче, преподо́бне о́тче Афана́сіє, ско́рий помо́щниче і ціле́бниче неду́гов душе́вних і тіле́сних, я́ко імі́яй ве́ліє дерзнове́ніє к просла́вльшему тя Го́споду, от вся́ких нас бід свободи́ і на спасе́нія стезі́ руководи́, да зове́м ті хвале́бно:","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов і всея́ тва́рі Соді́тель, ізбра́вий Го́ру Афо́нськую земни́м уді́лом Пречи́стия Своєя́ Ма́тере і дарова́вий ю во ві́чноє достоя́ніє і́ночествующих, яви́ тя в ней сві́тла світи́льника, весь собо́р преподо́бних украша́юща. Ті́мже у́бо, я́ко вели́кому уго́днику Христо́ву, воспіва́єм ті си́це:","Ра́дуйся, предо́брий і́ноков наста́вниче;","Ра́дуйся, пресла́вний а́нгелов собесі́дниче.","Ра́дуйся, цілому́дрія ди́вноє світи́ло;","Ра́дуйся, усе́рднійший ісполни́телю поста́ і воздержа́нія.","Ра́дуйся, духо́вной во Христі́ жи́зні прему́дрий учи́телю;","Ра́дуйся, сві́тлий о́бразе кро́тости і смире́нія.","Ра́дуйся, і́м'я твоє́ ді́ли безсме́ртія оправда́вий;","Ра́дуйся, дія́ніє і виді́ніє чу́дно в себі́ сочета́вий.","Ра́дуйся, преподо́бному Петру́ Афо́нському в равноа́нгельном житії́ подража́вий;","Ра́дуйся, ра́вную с ним на Небесі́ сла́ву восприя́вий.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 2","ps":["Єгда́, по блаже́нном успе́нії роди́телей твої́х, єще́ младе́нцю ті су́щу і не могу́щу о себі́ промишля́ти, Всеблаги́й Госпо́дь Боже́ственним Свої́м Про́мислом устро́ї єди́ну чернори́зицю пещи́ся о тебі́, і та воспитова́ше тя вмі́сто си́на, тогда́ ти, блаже́нне, ви́дя сію́ пита́тельницю твою́ пребива́ющу в поще́нії і моли́твах, потща́лся єси́, єли́ко бі мо́щно отроча́ти, подража́ти свято́му тоя́ житію́, поя́ с не́ю Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний дарова́ся тебі́, уго́дниче Бо́жий, єгда́ в Константинград прише́д, в любому́дрії кни́жнім обучи́тися тща́лся єси́: і́бо толи́ко в о́ном преуспі́в, я́ко в ма́лі вре́мені ізря́ден ри́тор і прему́др учи́тель показа́лся єси́. Ми же си́це Бо́гом умудре́нному ті прино́сим сицеви́я нему́дрия хвали́:","Ра́дуйся, нача́ло прему́дрости, страх Бо́жий, пра́вилом жи́зні себі́ предложи́вий;","Ра́дуйся, вся за́повіді Госпо́дні со тща́нієм храни́вий.","Ра́дуйся, любому́дрієм твої́м суєту́ ми́ра сего́ я́сно разсмотрі́вий;","Ра́дуйся, пещи́ся о душе́ своє́й усе́рдно вожделі́вий.","Ра́дуйся, в ю́ності посту́ і моли́тві обучи́вийся;","Ра́дуйся, в свяще́нних писа́ніїх прилі́жно поучи́вийся.","Ра́дуйся, ізмла́да сідино́ю му́дрости украси́вийся;","Ра́дуйся, о лише́нії роди́телей твої́х Го́сподем уті́шенний.","Ра́дуйся, воздержа́нієм па́че не́же млеко́м воспитавийся;","Ра́дуйся, от све́рстних тебі́ отроко́в наста́вником мона́хов презнаменовавийся.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла благода́ті Бо́жієй сочетава́яся благо́му проізволе́нію твоєму́, помо́же ті, блаже́нне, ізбіжа́ти многоплете́нних сіте́й ми́ра сего́ і посла́ тебі́ свята́го ста́рця Михаї́ла, вождя́ і наста́вника житію́ і́ночеському, в не́мже до кончи́ни твоєя́ до́брі подвиза́лся єси́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ве́ліє жела́ніє равноа́нгельнаго житія́ і́ночеськаго, Царгра́д оста́вил єси́, блаже́нне, і оби́телі Мале́їни дости́г, преподо́бним Михаї́лом в і́ночеськую власяни́цю, я́ко во́їн в броня́, оболче́н бил єси́; і та́ко му́жественно ополчи́лся єси́ проти́ву неви́димих враго́в ро́да челові́чеськаго. Сего́ ра́ди ублажа́єм тя си́це:","Ра́дуйся, от мла́да во́зраста вда́вий себе́ на служе́ніє Го́споду;","Ра́дуйся, Того́ єди́наго па́че всего́ возлюби́вий.","Ра́дуйся, Ца́рствія ра́ди Небе́снаго честь і сла́ву ми́ра оста́вивий;","Ра́дуйся, вся вре́менная я́ко уме́ти презрі́вий.","Ра́дуйся, плоть ду́ху покори́вий;","Ра́дуйся, ум твой в богоми́сліє впери́вий.","Ра́дуйся, по́мисли вра́жия бо́дро отрази́вий;","Ра́дуйся, святи́нею і чистото́ю а́нгелом уподо́бивийся.","Ра́дуйся, Киме́нськия оби́телі ве́ліє украше́ніє;","Ра́дуйся, Афо́ну сла́ва і благолі́піє.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 4","ps":["Сла́ви вре́менния і почита́нія от боголюби́вих воєво́д, я́ко бу́ри і волне́нія морська́го ізбіга́я, Киме́нськую оби́тель оста́вив, во святу́ю Го́ру Афо́нськую, я́ко в ти́хоє приста́нище, дости́гл єси́, преподо́бне Афана́сіє, і та́мо преда́лся єси́ в послуша́ніє ста́рцев подви́жников, поя́ с ни́ми Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще прот і про́чії отці́ Святи́я Гори́ сла́дкоє твоє́ Свяще́нних Писа́ній добровіща́ніє, удивля́хуся си́лі благода́ті із уст твої́х ісходя́щей і прославля́ху Бо́га; єди́н же от них, преподо́бний Па́вел, проро́чеськи о тебі́ рече́: сей, посліди́ нас прише́дий, бу́деть пе́рвійший доброді́телію і сла́вою в Ца́рствії Небе́снім. Сего́ проро́чества ми ни́ні сбитіє́ ві́дяще, ра́достно вопіє́м ті:","Ра́дуйся, ди́вний ізбра́нниче Бо́жий;","Ра́дуйся, пречестно́є Свята́го Ду́ха селе́ніє.","Ра́дуйся, преподо́бних отце́во восхвале́ніє;","Ра́дуйся, прорече́ній їх ісполне́ніє.","Ра́дуйся, ри́торе сладковіща́нний і богому́дрий;","Ра́дуйся, краснопи́сче предо́брий і трудолюби́вий.","Ра́дуйся, благочи́нія церко́внаго ревни́телю;","Ра́дуйся, душевре́дних в хра́мі шепта́ній іскорени́телю.","Ра́дуйся, прему́дрими твої́ми і благода́тними глаго́ли благочести́вия воєво́ди удиви́вий;","Радуся, на спасе́нія стезі́ тіх руководи́вий.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 5","ps":["Зві́зди світлі́є яви́ся ми́ру житіє́ твоє́, преподо́бне о́тче Афана́сіє: ти бо сам ше́ствуя путе́м ті́сним і ско́рбним, пра́во веду́щим в Ца́рствіє Небе́сноє, і іни́х мно́гих науча́л єси́ твори́ти во́лю Госпо́дню і предста́вил єси́ тіх Христу́ Бо́гу доброді́тельми сія́ющих, поя́ с ни́ми: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя враг ро́да челові́чеськаго созида́ніє тобо́ю оби́телі ко вселе́нію і́ночествующих, вельми́ раздражи́ся і рече́ друго́м свої́м: о дру́зі і си́ли мої́! Доко́лі терпи́м і не расто́ргнем вражде́бника на́шего Афана́сія? Ти же о́тче, моли́твою твоє́ю ко Го́споду, я́ко жезло́м, порази́л єси́ тіх ополче́нія. Сего́ ра́ди воспіва́єм ті си́це:","Ра́дуйся, до́брий во́їне Христо́в;","Ра́дуйся, сла́вний побіди́телю неви́димих враго́в.","Ра́дуйся, клеветавшия на тя ста́рці ра́достно прости́вий;","Ра́дуйся, враги́ твоя́ я́ко дру́ги возлюби́вий.","Ра́дуйся, Бо́гом вруче́нному ті ста́ду до́брий па́стир би́вий;","Ра́дуйся, слове́сния твоя́ о́вці от волко́в ми́сленних защити́вий.","Ра́дуйся, дар умиле́нія от Бо́га прия́вий;","Ра́дуйся, бога́тство доброді́телей собра́вий.","Ра́дуйся, Самаго́ Христа́ Го́спода во виді́нії зрі́ти сподо́бивийся;","Ра́дуйся, я́ко Того́ ни́ні зри́ши на Престо́лі Сла́ви сідя́ща.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дуєть Гора́ Афо́нськая труди́ твоя́ і по́двиги, і́миже в удо́ліїх і де́бріх єя́ я́ко безпло́тен подвиза́лся єси́, преподо́бне; найпа́че же віща́єть сла́ву твою́ свяще́нная твоя́ Ла́вра, в не́йже цільбопода́тельния мо́щі твоя́ почива́ють, істоча́ющия то́ки чуде́с і ісціле́ній, ві́рою о тебі́ пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, преподо́бне, в бре́нній пло́ті сві́том небе́сним, я́ко пла́мень о́гненний, є́же учени́к твой Гера́сим сподо́бився зрі́ти, со у́жасом возопи́: о, о́тче! Ті́мже і ми вопіє́м ті:","Ра́дуйся, о́тче, сві́том доброді́телей твої́х мир озари́вий;","Ра́дуйся, те́мная бісо́вськая по́лчища із пусти́ні Афо́на отгна́вий.","Ра́дуйся, сія́нієм твоєго́ лиця́ ученика́ твоєго́ удиви́вий.","Ра́дуйся, лю́тую того́ болі́знь єди́ним сло́вом ісціли́вий.","Ра́дуйся, в тлі́нній пло́ті нетлі́нною сла́вою озаре́н би́вий;","Ра́дуйся, огнь любве́ Боже́ственния в себі́ носи́вий.","Ра́дуйся, в Ца́рствії Отця́ Небе́снаго я́ко со́лнце сія́ющий;","Ра́дуйся, моли́твенниче наш ко Христу́ Бо́гу теплі́йший.","Ра́дуйся, в біда́х ско́рий помо́щниче;","Ра́дуйся, в печа́ліх вели́кий уті́шителю.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ христолюби́вий воєво́да Ники́фор ізи́ти на брань проти́ву нечести́вих ага́рян, моля́ше отце́в Афо́нських, да помо́ляться о нем к Бо́гу і да по́слють тя к нему́. Ти же, о́тче Афана́сіє, повину́яся отце́м, а́ще і не хотя́, путеше́ствовал єси́ до Кри́та, і та́мо моли́твами твої́ми помо́гл єси́ христия́ном побіди́ти ага́ряни, неведущия пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє уми́сли зло прелука́вий дия́вол, єгда́ подви́же на за́висть єди́наго от учени́к твої́х, і научи́ єго́ закла́ти тя, я́ко а́гнця непоро́чна. Ти же, о́тче, десни́цею Ви́шняго спасе́н бив, уби́йцю о́наго оте́чеськи прости́л і облобиза́л єси́. Ті́мже всі ми, таково́му твоєму́ незло́бію див'я́щеся, хвале́бно вопіє́м:","Ра́дуйся, в кро́тости і смире́нії твоє́м Христу́ Бо́гу подража́вий;","Ра́дуйся, незло́бієм твої́м ду́ха зло́би побіди́вий.","Ра́дуйся, сокро́вищ Христо́вих дража́йший би́сере, єго́же не возмо́же душегу́бець похи́тити;","Ра́дуйся, єго́же десни́ця Госпо́дня храня́ше от всіх зол.","Ра́дуйся, от внеза́пнаго уби́йства спасе́нний;","Ра́дуйся, смертоно́сним питіє́м, по сло́ву Госпо́дню, неврежде́нний.","Ра́дуйся, тріє́х муже́й, от гла́да і мра́за ізнемо́гших, сме́рті ізба́вивий;","Ра́дуйся, мно́гих от разли́чних болі́зней ісціли́вий.","Ра́дуйся, ві́рния в правосла́вії утверди́вий;","Ра́дуйся, лжеві́рния і неві́рния посрами́вий.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до бі ви́діти, єгда́ повелі́нієм твої́м, о́тче, в зно́йноє вре́м'я поче́рпнутая із мо́ря сла́ная вода́ сотвори́ся хла́дна і сладка́, піющия ю прохлади́вшая і жа́жду утоли́вшая. Ті́мже у́бо велича́єм Го́спода, дарова́вшаго тебі́ такови́й дар чудотворе́нія, і во умиле́нії вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Ди́вно яви́ся тебі́ Ма́тер Христа́ Бо́га на́шего, і повелі́ ті жезло́м порази́ти ка́мень, із него́же а́біє істече́ істо́чник водни́й, і́же і до ни́ні істоча́єть во́ду живу́ і ціле́бну. Таково́му к тебі́ благоволе́нію Влади́чиці чудя́щеся, взива́єм си́це:","Ра́дуйся, я́ко пресві́тлоє лице́ Цари́ці Небе́сния зрі́ти сподо́бился єси́;","Ра́дуйся, я́ко повелі́нієм Єя́ ізве́л єси́ во́ду із ка́мене.","Ра́дуйся, я́ко сим пресла́вним чу́дом богови́дцю Мойсе́ю подо́бен показа́лся єси́;","Ра́дуйся, я́ко с сим вели́ким проро́ком в ра́йських оби́теліх ни́ні обита́єши.","Ра́дуйся, я́ко істо́чник твой благода́тно посіща́єши;","Ра́дуйся, я́ко боля́щим здра́віє подава́єши.","Ра́дуйся, я́ко прокаже́нния очища́єши;","Ра́дуйся, я́ко нечи́стия ду́хи от челові́к отгоня́єши.","Ра́дуйся, я́ко неду́жним усе́рдно послужи́л єси́;","Ра́дуйся, я́ко чре́вния і неудобоціли́мия я́зви уврачева́л єси́.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 9","ps":["Всяк язи́к челові́ч недоуміва́єть по достоя́нію восхвали́ти благоволе́нія Цари́ці Небе́сния к подви́жником христия́нським: Та бо в Ла́вру твою́, о́тче, с двіма́ а́нгелома при́йде, і ученико́м твої́м Матфі́єм ви́дима бисть в хра́мі, раздаю́ща златни́ци і ца́ти, усе́рдно предстоящим і пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Всі і́ноці Гори́ Афо́нськия блажа́ть тя, о́тче Афана́сіє, я́ко наста́вника своєго́ і тепла́ хода́тая; не лише́ни же суть благода́тния твоєя́ по́мощі і всі правосла́внії лю́діє, с любо́вію почита́ющії святу́ю па́м'ять твою́ і взива́ющії си́це:","Ра́дуйся, святи́м і чу́дним твої́м житіє́м святоіме́нний Афо́н возвели́чивий;","Ра́дуйся, небовосхо́дную доброді́телей твої́х лі́ствицю нам в о́браз оста́вивий.","Ра́дуйся, земна́го жре́бія Ма́тері Бо́жієй честно́є украше́ніє;","Ра́дуйся, і́ночества правосла́внаго похвало́.","Ра́дуйся, за мно́гую твою́ к согрешающим любо́в і милосе́рдіє ми́лость Бо́жию получи́вий;","Ра́дуйся, за вели́коє твоє́ о стра́нних попече́ніє от стра́нствовавшаго нас ра́ди Го́спода во ві́чних ски́ніїх сла́вно почте́нний.","Ра́дуйся за сла́вную твою́ над пло́тію і дия́волом побі́ду вінце́м сла́ви увінча́нний;","Ра́дуйся, за ді́вственную чистоту́ і серде́чную простоту́ от Присноді́ви Марі́ї в ближа́йшеє содру́жество прия́тий.","Ра́дуйся, я́ко благоволе́нієм Цари́ці Небе́сния, созда́нная тобо́ю во і́м'я Єя́ оби́тель в твоє́ і́м'я прейменова́ся;","Ра́дуйся, я́ко день преставле́нія твоєго́ в сей оби́телі сві́тло торжеству́ється.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ Бо́гом вруче́нноє ті ста́до от раздо́ров і собла́знов, і к сконча́нію сме́ртному приближа́яся, заві́т ученико́м твої́м письмени́ начерта́л єси́, о́тче, поуча́я всіх взаї́мной бра́тськой любві́ і хране́нію оте́чеських преда́ній. Ми же, хва́ляще таково́є твоє́ о ча́діх попече́ніє, поє́м Христу́ Спаси́телю на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю терпі́нія огради́вся і наде́ждою ві́чних благ укріпи́вся, земно́є стра́нствіє ті́сною стезе́ю проше́л єси́, преподо́бне Афана́сіє, нося́ яре́м поста́, многоно́щнаго бді́нія і о вві́ренних тебі́ душа́х попече́нія; ни́ні же, в небе́снім пребива́я блаже́нстві, пом'яни́ нас, восхваля́ющих тя си́це:","Ра́дуйся, крі́пкий подви́жниче, вся разжже́нния стрі́ли лука́ваго угаси́вий;","Ра́дуйся, слез ізлія́ньми ду́шу твою́ чи́сто оми́вий.","Ра́дуйся, не́мощі немощни́х оте́чеськи носи́вий;","Ра́дуйся, в глубину́ прегріше́ній впадшия на го́ру доброді́телей возводи́вий.","Радвйся, мно́гих вели́ких муже́й наста́вник би́вий;","Ра́дуйся, царя́ Ники́фора в неісполне́нії да́ннаго Бо́гу обі́та кро́тко обличи́вий.","Ра́дуйся, бу́дущая проро́чеськи предви́дівий;","Ра́дуйся, дале́че отстоя́щая я́сно зрі́вий.","Ра́дуйся, Бо́жия сла́ви те́плий рачи́телю;","Ра́дуйся, велі́ній єго́ ре́вностний ісполни́телю.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 11","ps":["Піснь благодаре́нія прине́сл єси́, о́тче, Бо́гу, ди́вно спа́сшему тя от потопле́нія морська́го со ученики́ твої́ми, єгда́, ді́йством ду́ха зло́би, ладія́, в не́йже плил єси́, опрове́ржена бисть, і всі в ней су́щії, в пучи́ну впа́дше, не погибо́ша і воспі́ша хвалу́ Го́сподеві: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том благода́ті Бо́жия озаре́н імі́я твой ум і се́рдце, преподо́бне о́тче Афана́сіє, та́їнственно предре́кл єси́ твою́ страда́льчеськую кончи́ну, в не́йже я́ко му́ченик под разва́линами па́дшаго хра́ма ті́лом погре́бся, ду́хом пресели́лся єси́ в го́рнія оби́телі, в ни́хже, хода́тайством твої́м ко Го́споду помози́ водвори́тися і нам, вопію́щим ті си́це:","Ра́дуйся, в животі́ і по преставле́нії твоє́м мно́гая і пресла́вная чудеса́ сотвори́вий;","Ра́дуйся, от но́ги твоєя́ кров я́ко ми́ро благово́нноє чуде́сно істочи́вий.","Ра́дуйся, на честно́є погребе́ніє твоє́ мно́жество і́ноков собра́вий;","Ра́дуйся, во гро́бі ті́ло твоє́ небе́сною ра́достію світя́щеєся показа́вий.","Ра́дуйся, пома́занієм кро́ве твоєя́ боля́щаго кора́бленника со одра́ сме́ртнаго здра́ва возста́вивий;","Ра́дуйся, се́ю же твоє́ю кро́вію кровоточи́вую жену́ уврачева́вий.","Ра́дуйся, всіх се́рдця любо́вію твоє́ю, к себі́ привлека́ющий;","Ра́дуйся, благоуха́нієм Бо́жия благода́ті смрад страсте́й от мно́гих отгоня́ющий.","Ра́дуйся, світи́льниче пресві́тлий, от гори́ Афо́на всему́ ми́ру правосла́вному сія́ющий;","Ра́дуйся, не то́чію і́ноком, но і миря́ном путь к не́бу озаря́ющий.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть ве́лія тебі́, о́тче, от Бо́га даде́ся, добродетельниє челові́ки на вя́щшеє преуспі́яніє наставля́ти, грі́шния же к покая́нію побуждати, пру́ги от нив отгоня́ти і разли́чния неду́ги і стра́сті врачева́ти. Ті́мже у́бо смире́нно мо́лим тя, о́тче: не лиши́ по́мощі твоєя́ і нас, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще свято́є, равноа́нгельноє твоє́ житіє́, ублажа́єм тя, о́тче Афана́сіє, я́ко многомо́щна моли́твенника о нас пред Го́сподем, тепла́ засту́пника і наста́вника ко спасе́нію, і с любо́вію возглаша́єм ті си́це:","Ра́дуйся, правосла́вния Це́ркве похвало́;","Ра́дуйся, оби́телі твоєя́ і всея́ Гори́ Афо́нськия покрови́телю.","Ра́дуйся, пусти́ннаго безмо́лвія і́скренній люби́телю;","Ра́дуйся, общежи́тія му́дрий руководи́телю;","Ра́дуйся, по́стничеськаго житія́ і́стинний ревни́телю;","Ра́дуйся, всіх і́ночеських доброді́телей сві́тлий о́бразе і учи́телю.","Ра́дуйся, я́ко смире́нія ра́ди не восхоті́л єси́ яви́ти ми́ру моще́й твої́х;","Ра́дуйся, я́ко хотя́щим із'яти о́ния із нідр земни́х огне́м воспрети́л єси́.","Ра́дуйся, я́ко до ни́ні правосла́внії лю́діє покланя́ються свято́му твоєму́ гро́бу;","Ра́дуйся, я́ко і чудоді́йственний жезл твой та́мо зрим єсть.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 13","ps":["О, преди́вний і́ноков наста́вниче і чудотво́рче, преподо́бне о́тче Афана́сіє, предстоя́й ни́ні Престо́лу Царя́ Сла́ви Го́спода на́шего Ісу́са Христа́, моли́ся Єму́ дарова́ти всім нам дух і́стинния кро́тости, любве́ і цілому́дрія, да, сконча́вши живо́т наш в покая́нії, сподо́бимся со всі́ми святи́ми в Небе́сном Ца́рствії пі́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов і всея́ тва́рі Соді́тель, ізбра́вий Го́ру Афо́нськую земни́м уді́лом Пречи́стия Своєя́ Ма́тере і дарова́вий ю во ві́чноє достоя́ніє і́ночествующих, яви́ тя в ней сві́тла світи́льника, весь собо́р преподо́бних украша́юща. Ті́мже у́бо, я́ко вели́кому уго́днику Христо́ву, воспіва́єм ті си́це:","Ра́дуйся, предо́брий і́ноков наста́вниче;","Ра́дуйся, пресла́вний а́нгелов собесі́дниче.","Ра́дуйся, цілому́дрія ди́вноє світи́ло;","Ра́дуйся, усе́рднійший ісполни́телю поста́ і воздержа́нія.","Ра́дуйся, духо́вной во Христі́ жи́зні прему́дрий учи́телю;","Ра́дуйся, сві́тлий о́бразе кро́тости і смире́нія.","Ра́дуйся, і́м'я твоє́ ді́ли безсме́ртія оправда́вий;","Ра́дуйся, дія́ніє і виді́ніє чу́дно в себі́ сочета́вий.","Ра́дуйся, преподо́бному Петру́ Афо́нському в равноа́нгельном житії́ подража́вий;","Ра́дуйся, ра́вную с ним на Небесі́ сла́ву восприя́вий.","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний от гра́да Трапезу́нта і во Афо́ні по́стничеськи просія́вий, ди́вний подви́жниче і чудотво́рче, преподо́бне о́тче Афана́сіє, ско́рий помо́щниче і ціле́бниче неду́гов душе́вних і тіле́сних, я́ко імі́яй ве́ліє дерзнове́ніє к просла́вльшему тя Го́споду, от вся́ких нас бід свободи́ і на спасе́нія стезі́ руководи́, да зове́м ті хвале́бно:","Ра́дуйся, преподо́бне Афана́сіє, Афо́нський чудотво́рче."]},{"h":"Молитва","ps":["Преподо́бне о́тче Афана́сіє, ізря́дний уго́дниче Христо́в і вели́кий Афо́нський чудотво́рче! Во дні земна́го житія́ твоєго́ мно́гія на путь пра́вий наста́вивий і в Ца́рствіє Небе́сноє му́дре руководи́вий, ско́рбния уті́шивий, па́дающим пода́вий ру́ку по́мощі і всім любе́зен, ми́лостив і сострада́телен оте́ць би́вий, ти ни́ні, в Небе́сній пребива́я сві́тлости, найпа́че умно́жавши любо́в твою́ к нам, немощни́м, в мо́рі жите́йстім разли́чні бе́дствующим, іскуша́ємим ду́хом зло́би і страстьми́ свої́ми, вою́ющими на дух. Сего́ ра́ди смире́нно мо́лим тя, святи́й о́тче: по да́нній тебі́ от Бо́га благода́ті помози́ нам твори́ти во́лю Госпо́дню в простоті́ се́рдця і смире́нії, іскуше́нія же вра́жия побіди́ти і свирі́поє страсте́й мо́ре ізсуши́ти, да та́ко немо́кренно пре́йдем жите́йськую пучи́ну і предста́тельством твої́м ко Го́споду сподо́бимся дости́гнути обітова́ннаго нам Ца́рствія Небе́снаго, сла́в'яще Безнача́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Є́же во пло́ті житію́ твоєму́ / удиви́шася а́нгельстії чи́ни: / ка́ко с ті́лом к неви́димим спле́тенієм ізше́л єси́, присносла́вне, / і уязви́л єси́ де́монськия полки́. / Отону́дуже, Афана́сіє, / Христо́с тебі́ воздаде́ бога́тими дарова́ньми: / сего́ ра́ди, о́тче, моли́ // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Я́ко невеще́ственних суще́ств зри́теля ізря́дна, / і ді́ятельна сказа́теля всеї́стинна, / взива́єть тя ста́до твоє́, Богоглаго́льниче: / не оскуді́й моля́ о рабі́х твої́х, / ізба́витися напа́стей і обхожде́ній, вопію́щим ті: // ра́дуйся, о́тче Афана́сіє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Афана́сіє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобним отцям Києво-Печерським","e":"Akathist to the Venerable Fathers of the Kyiv Caves","secs":[{"h":"Кондак 1","ps":["Богоізбра́нний по́лче і ли́че богокра́сний, преподо́бнії отці́ на́ші Пече́рстії, чуде́с мно́гих істо́чници, і́ночеськаго, по́стничеськаго общежи́тія на Русі́ первоучи́телі і наста́вници, сіє́ вам от душе́внаго жела́нія дерза́єм принести́ похва́льноє пі́ніє. Ви же, я́ко іму́щи ве́ліє дерзнове́ніє к подвигополо́жнику Христу́ Бо́гу на́шему, молі́теся Єму́, мо́лим ви, от вся́ких бід і зол нам ізба́витися, да с благодаре́нієм зове́м вам:","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Ікос 1","ps":["Ангелоподо́бнаго возжелаєте житія́, отці́ богому́дрії, мирськи́я многом'яте́жния молви́ ізбіго́сте, в пеще́рах ті́сних і те́мних всели́стеся, іді́же труди́ ве́лії і по́двиги под'ясте, да Христа́ приобря́щете; ті́мже і сли́шіте от немощни́х нас і грі́шних сія́ піснопі́нія:","Ра́дуйся, Анто́ніє, воздержа́нія, смире́нія, послуша́нія і безмо́лвія зерца́ло;","ра́дуйся, ві́ри правосла́вния крі́пкоє забра́ло.","Ра́дуйся, Феодо́сіє, мона́шеськая похвало́;","ра́дуйся, оби́телі твоєя́ велелі́пная сла́во.","Ра́дуйся, Михаї́ле, пе́рвий архіпа́стирю наш і учи́телю;","ра́дуйся, ві́ри Христо́вой усе́рдний насади́телю і ідолослуже́нія іскорени́телю.","Ра́дуйся, Про́хоре, чудотво́рче всеблаже́нний, хлі́би су́щими от би́лій і со́лію от пе́пла, гла́дом тающия лю́ди пропитавий.","Ра́дуйся, Іоа́нне, посто́м неізрече́нним просія́вий.","Ра́дуйтеся, Фео́доре і Васи́ліє, во вре́менній жи́зні взаїмним любве́ Христо́ві сою́зом себі́ связавшії;","ра́дуйтеся, от користолюбиваго кня́зя Мстисла́ва крі́пко пострада́вшії.","Ра́дуйтеся, я́ко і по блаже́нній кончи́ні ва́шей во єди́ній ра́ці дружелюбно почієте;","ра́дуйтеся, я́ко во єди́нім часі́ к престо́лу Бо́жию предста́сте.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 2","ps":["Ви́дя Христо́с Госпо́дь, я́ко во і́м'я Єго́ снидостеся купножительствовати, посреді́ вас обрі́теся, посо́бствуя вам в разли́чних по́двизіх, найпа́че же во бра́ні со ду́хи зло́би поднебесной, і обогащаше вас благода́тію Ду́ха Пресвята́го: одному́ подая́ дар проро́чества, друго́му же да́ри ісціле́ній, іно́му власть ізгоня́ти ду́хи нечи́стії, ви же благода́ть сію́ приє́мши, не вознесо́стіся ду́хом свої́м, но в простоті́ душі́ і се́рдця со смире́нієм і благодаре́нієм Благода́телю Бо́гу піснь воспесте: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неукло́нен іму́ще і крі́пкою ві́рою в Бо́га вооружи́вшеся, путі́ спаси́тельнаго держа́стіся, отці́ прехва́льнії, єго́же і соверши́сте пресла́вно с по́мощію Христа́ і Пречи́стой Єго́ Ма́тері; сію́ по́мощ і нам, хотя́щим богоуго́дному житію́ ва́шему подража́ти, іспросі́те у престо́ла Всеви́шняго, да благода́рно воспоє́м вам:","Ра́дуйся, Поліка́рпе, главо́ пресві́тлая, житія́ святи́х коне́чніє списа́вий і воєди́но собра́вий;","ра́дуйся, я́ко с ни́ми у престо́ла Тро́йці Пресвяти́я предста́вий.","Ра́дуйся, Варлаа́ме, у́ме благода́тний, пеще́ру те́мную і ті́сную сві́тлим і пространним палатам предпочтий;","ра́дуйся, златотканния оде́жди на ру́би і́ночеськия преміни́вий.","Ра́дуйся, Дамія́не, ціле́бниче безме́здний, моли́твами і святи́м єле́єм боля́щих уврачева́вий;","ра́дуйся, купножитія на небесі́х с преподо́бним Феодо́сієм у Го́спода себі́ іспроси́вий.","Ра́дуйся, Никоди́ме, в печенії хлі́бов свяще́нних тридесять літ потруди́вийся.","Ра́дуйся, Лавре́нтіє, в затво́рі теснейшем многолі́тно подвиза́вийся.","Ра́дуйся, Афана́сіє, дар слез і умиле́нія от Го́спода получи́вий.","Ра́дуйся, Єразме, за украше́ніє хра́ма Бо́жия Ма́тере пала́ту красоти́ неізрече́нния в Небе́сном Ца́рстві от Христа́ стяжа́вий.","Ра́дуйся, Луко́, за́повідей Бо́жиїх усе́рдний ді́лателю.","Ра́дуйся, Некта́ріє, послуша́нія нелі́ностний ісполни́телю.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 3","ps":["Си́лою і благода́тію, да́нною ті сви́ше, в животі́ твоє́м, Ага́пите блаже́нне, болі́зні разли́чния врачевавий. Благода́ть сія́ і си́ла тебі́ і ни́ні присущая, па́че же і умно́жися. Ті́мже мо́лим тя: ісціли́ на́ша неду́ги, уврачу́й стра́сті душе́вния і тіле́сния, да здра́ві су́ще душою і ті́лом, воспоє́м просла́вльшему тя Христу́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи к вам ві́ру, любо́в і усе́рдіє, хода́таї бу́дете жи́зні ві́чния, отці́ богоприя́тнії! Ва́ші бо моли́тви многомогущії у престо́ла Бо́жия; сего́ ра́ди і прибіга́єм к вам, я́ко вели́ким помощникам на́шим і заступникам, сла́в'яще вас си́це:","Ра́дуйся, Іоа́нне, я́ко послуша́ніє і по кончи́ні своє́й прояви́л єси́;","ра́дуйся, я́ко старшему бра́ту свой сме́ртний одр уступи́л єси́.","Ра́дуйся, Фео́филе, я́ко братнім послуша́нієм от гні́ва ісцелился єси́;","ра́дуйся, я́ко вмі́сто гні́ва умиле́ніє і сле́зи непреста́нния возимел єси́.","Ра́дуйся, Ку́кшо священному́чениче, я́ко язи́чников мно́жество ко Христо́вой ві́рі приве́л єси́:","ра́дуйся, я́ко за Христа́ со ученико́м твої́м во главу́ усі́чен бил єси́.","Ра́дуйся, Алексі́є, моли́тви у́мния до́брий ді́лателю.","Ра́дуйся, Григо́ріє, іко́н святи́х благогові́йний писателю.","Ра́дуйся, Са́вво, чуде́с вели́ких творителю.","Ра́дуйся, Се́ргіє, послуша́нія прехва́льний рачи́телю.","Ра́дуйся, Мерку́ріє, житію́ безпло́тних поревнователю.","Ра́дуйся, Пи́мене многоболі́зненний, крі́пкий на Бо́га упователю.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 4","ps":["Бурний і широ́кий житія́ мирська́го путь возненави́дівше, возлюби́сте же вседу́шно узькую і прискорбную житія́ мона́шеськаго стезю́ і се́ю усе́рдна потеко́сте, отці́ богому́дрії; ті́мже і Госпо́дь, ви́дя ва́ше благо́є проізволе́ніє, запові́да А́нгелом свої́м споспешествовати вам і укріпля́ти вас. Сего́ ра́ди, хотя́щему всім челові́ком спасти́ся Христу́, поє́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще лю́діє, я́ко Госпо́дь просла́вил святи́м нетлі́нієм тілеса́ ва́ша і дарова́ вам благода́ть ціли́ти неду́ги і болі́зні, ті́мже притека́ють к вам движимиє ві́рою, с Восто́ка, За́пада, Сі́вера і Ю́га, похваля́юще вас приві́тствії такови́ми:","Ра́дуйся, Не́сторе, пе́рвий Ру́ський битописателю;","ра́дуйся житі́й святи́х отцов Пече́рських сказа́телю і усе́рдний їм во всем подража́телю.","Ра́дуйся, Євстра́тіє, до́блій му́чениче і по́стниче, сообра́зно самому́ Христу́ пострада́вший;","ра́дуйся, все я́зви Го́спода Ісу́са на ті́лі своє́м поне́сший.","Ра́дуйся, Елладіє, затворников похвало́.","Ра́дуйся, Ієремі́є, прозорливих сла́во.","Ра́дуйся, Мойсе́є, цілому́дрія світи́ло.","Ра́дуйся, Іоа́нне, ді́вства побі́до.","Ра́дуйся, Ма́рко, єго́ же честні́ї ру́ці гро́би святи́м іскопа́ша;","ра́дуйся, єго́ же гла́са ме́ртвії послу́шаша.","Ра́дуйся, Нико́ло кня́же, в послуша́ніє бра́тії Пече́рстій всеці́ло себі́ преда́вий.","Ра́дуйся, Григо́ріє, і́же потопле́нієм в ріці́ кончи́ну блаже́нную прия́вий, єго́ же ті́ло пречестно́є в ке́ллії чуде́сно обрі́теся.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 5","ps":["Ви́дя Діони́сій богому́дрий тілеса́ ва́ша во гробі́х святолі́пно почива́юща, я́же вни́де покади́ти в день Па́схи Христо́вой, от ізби́тка любве́ і благогові́нія к вам воззва́: «Святі́ї отці́ і бра́тія, ни́ні єсть вели́к ден: Христо́с воскре́се!» І, о чудесе́! Сли́шить а́біє от вас громогласноє: «Воі́стину воскре́се!» Див'я́шеся чудеси́ сему́ пресла́вному, поє́м воскре́сшему і пребива́ющему во вік ві́ка Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Разу́мнії зві́зди небесе́ пеще́рнаго ви єсте́, отці́ прехва́льнії, путь і́ночеськаго житія́ освещающії і на кругі Ру́ськия Це́ркве правосла́вния пресві́тло блиста́ющії. Сла́ва бо всечестни́х по́двигов ва́ших во вся ми́ра конці́ протече́, іспові́даніє же святи́я ві́ри ва́шея всю Вселе́нную облиста́: того́ ра́ди і дерза́єм приноси́ти вам сія́ убо́гія на́ша пі́нія:","Ра́дуйся, Они́симе, я́ко тісното́ю затво́ра пеще́рнаго в простра́нная селе́нія ра́йськия проше́л єси́;","ра́дуйся, я́ко а́лчбою і жа́ждою насище́ніє бесконечноє лицезрі́нія Бо́жия узрі́л єси́.","Ра́дуйся, Матфе́є, я́ко за чистоту́ душі́ і ті́ла да́ра проро́чеськаго сподо́блен єси́;","ра́дуйся, я́ко кро́тостію і незло́бієм висо́ких доброді́телей дости́гл єси́.","Ра́дуйся, Іса́їє, кла́дезю глубо́кий смире́нія;","ра́дуйся, істо́чниче неіссякаємий чудотворе́ній.","Ра́дуйся, Авраа́міє, си́не свята́го трудолю́бія.","Ра́дуйся, Ни́фонте святи́телю, побо́рниче Правосла́вія.","Ра́дуйся, Сильве́стре, би́сере пречестни́й.","Ра́дуйся, Пи́мене, сосу́де Ду́ха Свята́го ізбра́нний.","Ра́дуйся, Ону́фріє, язи́ком молчали́вий, умо́м хваливий Бо́га.","Ра́дуйся, Анатоліє, терпіли́вий душе́ю, ра́зумом цілому́дренний.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 6","ps":["Проповедницей нам явля́ється честна́я десни́ця твоя́, Спиридо́не богоприя́тне, є́ю же правосла́вних чад твої́х поуча́єши, ка́ко пе́рсти слагати подоба́єть во ізображе́ніє креста́ свята́го на челі́, уста́ же расколоучителей загражда́єши, я́ві облича́я їх неправоє уче́ніє о перстосложенії; сим бо о́бразом осіни́в себі́ крестним зна́менієм отошел єси́ ко Христу́, Єму́ же предстоя́ моли́ся, да угаси́ть безмі́рно горя́щую пещ страсте́й на́ших, да да́руєть нам і́стинноє усе́рдіє славосло́вити Єго́ непреста́нно во псалмі́х і пі́ніїх духо́вних в сей жи́зні і в бу́дущей да сподо́бит нас пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ я́ко пресві́тлоє світи́ло богознаменитая оби́тель ва́ша, отці́ преподо́бнії і всю зе́млю Ру́ськую благода́тію Бо́жиєю просвіти́: ю́же кро́вними по́ти воздвиго́сте і на ню же благода́ть сви́ше моли́твами ва́шими і святи́ми по́двиги привлеко́сте, ревну́я бо поревнова́сте проро́честву, є́же рече́: «На гора́х сих возсія́єть благода́ть Бо́жия і ві́ра умно́житься». Ті́мже к вам, я́ко виновником проро́чества о́наго зове́м:","Ра́дуйся, Аре́фо, я́ко Госпо́дь ми́лость свою́ на тебі́ удиви́;","ра́дуйся, я́ко Госпо́дь украденноє бога́тство твоє́ в ми́лостиню тебі́ вміни́.","Ра́дуйся, Фео́филе, єму́ же земля́ бисть ло́жем, власяниця оде́ждею.","Ра́дуйся, Сисо́є, єму́ же бді́ніє бисть сном, сле́зи успокоєнієм.","Ра́дуйся, Алі́піє, єму́ же А́нгели в труді́х свята́го іконописанія помо́щники би́ша.","Ра́дуйся, Си́моне святи́телю, єго́ же святі́ї ру́ци житія́ святи́х написа́ша і нам на по́льзу душе́вную преда́ша.","Ра́дуйся, Ни́коне, Анто́нія пе́рвий благогові́йний учениче́;","ра́дуйся, Феодо́сія в ді́ліх монасти́рських усе́рдний сотру́дниче і в душеспаси́тельних по́двизіх рачительний соучастниче.","Ра́дуйся, Феофа́не, я́ко ті́ло посто́м умертви́л єси́.","Ра́дуйся, Ониси́форе, я́ко ду́шу бді́нними моли́твами оживи́л єси́.","Ра́дуйся, Мака́ріє, я́ко за жизнь святу́ю істленієм ті́ла от Го́спода почелся єси́.","Ра́дуйся, Анастасі́є, дия́коне благогові́йний і страда́льче преди́вний.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 7","ps":["Хотя́ преблаги́й Госпо́дь страну́ на́шу благода́тію Своє́й обогати́ти і да́ти о́браз хотя́щим спасти́ся, подви́же вас Ду́хом Святи́м на вельми́ ско́рбноє і богоуго́дноє житіє́, їм же удиви́сте не то́кмо челові́ков на землі́, но і А́нгелов на небесі́: ви бо, о, отці́ богоно́снії, в пеще́рах заключившеся, а́ки во гробі́х, всеусе́рдно в теплоті́ се́рдця і душі́, Єди́ному Бо́гу порабо́тасте, богокрасно пою́ще піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вия жи́зні і́ночеськия отця́ми і учителям і яви́стеся, я́же на Русі́ ніже́ іменова́ся когда́, сію́ ви насади́сте і до́брі укоренисте. Ті́мже безчи́сленния мно́жества мона́шествующих послі́дующе душеспасительним стезя́м ва́шим благода́рно вам воспіва́ють:","Ра́дуйся, Авраа́міє, я́ко Христа́ Го́спода все́ю душою і се́рдцем возлюби́л єси́;","ра́дуйся, я́ко Єго́ ра́ди і труди́ ве́лії затво́ра пеще́рнаго под'ял єси́.","Ра́дуйтеся і ви, двана́десять бра́тій прекра́снії, я́ко це́рков Бо́жия Ма́тере небесі́ подо́бную украси́ли єсте́;","ра́дуйтеся, я́ко за труди́ ва́ша дина́рій от Си́на Єя́ Христа́ Бо́га, Ца́рство Небе́сноє восприя́ли єсте́.","Ра́дуйся, Ісаа́кіє, я́ко премно́гими страда́нії дия́вольськую пре́лесть низложи́л єси́.","Ра́дуйся, Іліє́, я́ко воздержа́нія по́двиги і безстра́стія благода́тію обогати́лся єси́.","Ра́дуйся, младе́нче му́чениче Іоа́нне, я́ко кров твою́ святу́ю непови́нно за Христа́ пролія́л єси́;","ра́дуйся, Ни́коне, я́ко на кресті́ просте́ршему во́лею дла́ни Христу́ терпі́нієм і незло́бієм вельми́ угоди́л єси́.","Ра́дуйся, святи́телю Єфре́ме, я́ко пчела́ сот пресладок, та́ко ти Уста́в студі́йський в оби́тель Пече́рськую прине́сл єси́.","Ра́дуйся, Ти́те блаже́нне, я́ко гні́внаго бі́са смире́нієм попра́л єси́;","ра́дуйся, я́ко тьму лука́вих де́монов дале́че от нас прогоня́єши.","Ра́дуйся, я́ко світ, є́же не гні́ватися на бли́жняго, собо́ю нам пролива́єши.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до благода́ті небе́сния прояви́ся воочію всіх ві́рних: пеще́ра разбо́йников в храм Бо́жий соді́лася: іді́же бо гріх преізобилова, та́мо благода́ть приумножися, іді́же терн беззако́нія укорени́ся, та́мо ке́дри рая́ Христо́ва возрасташа, іді́же бла́то смра́дноє гріха́ бя́ше, та́мо істо́чници безсме́ртія воскипі́ша, іді́же смерть облада́ше, та́мо Госпо́дь воцари́ся. Див'я́щеся ізміне́нію десни́ці Ви́шняго, зове́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Все ва́ше, преблаженниє отці́, тща́ніє, жела́ніє і попече́ніє бя́ше, да всезлобному ро́да христия́нськаго врагу́ го́рдую главу́ попра́ти і сотре́ти, Го́спода же Ісу́са Христа́ в душа́х і телесах ва́ших да возвели́чіте і просла́віте; сего́ ра́ди приветствуєм і вас си́це:","Ра́дуйся, священному́чениче Лукія́не, я́ко угото́вася тебі́ небе́сноє жили́ще;","ра́дуйся, я́ко страда́льцю, дарова́ся тебі́ несконча́ємоє ра́йськоє поко́їще.","Ра́дуйся, Лавре́нтіє, я́ко суєти́ мирськи́я ізбі́гл єси́;","ра́дуйся, я́ко к общежитію с ми́ром а́нгельським восте́кл єси́.","Ра́дуйся, Пафну́тіє, я́ко, по́мня час сме́ртний, непреста́нно слезил єси́;","ра́дуйся, я́ко при кончи́ні от А́нгелов утіше́нія сподо́бился єси́.","Ра́дуйся, Марти́ріє, я́ко за вели́кую чистоту́ і по́стническиє по́двиги да́ра ціли́ти болі́зні сподо́блен бил єси́.","Ра́дуйся, ієра́рше Іларіо́не, я́ко ста́до слове́сних ове́ць Христо́вих на па́житіх Правосла́вія до́брі упа́сл єси́.","Ра́дуйся, кня́же Фео́доре, я́ко в честь і во сла́ву Це́ркві правосла́вной мно́го потруди́лся єси́.","Ра́дуйся, Діоні́сіє, я́ко «воі́стину воскре́се Госпо́дь» от преподо́бних отце́во в день Па́схи усли́шал єси́.","Ра́дуйся, Афана́сіє, я́ко кра́сная ми́ра сего́ презрі́в, блату вміни́л єси́.","Ра́дуйся, святи́телю Фео́филе, па́стирю до́брий, я́ко за пасо́мих тобо́ю і живо́т положи́ти гото́в бил єси́.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 9","ps":["Всім єсте́ вся, отці́ преподо́бнії, небе́сная бо врачества́ предлагаєте нам і к безме́здним лічба́м свої́м вся ни созиваєте, не хитростьми́ челові́чеськими, ні об'язаньми, но ді́йствієм Свята́го Ду́ха душе́вния і тіле́сния ісціле́нія преєстестве́нні подаєте́, є́же приє́млюще оби́льно, род всяк і во́зраст Благода́телю і Промисли́телю зове́ть благода́рно: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії ри́торськими свої́ми язи́ки не возмо́гуть досто́йно воспіва́ти ва́шея святи́ні, тім па́че аз убо́гий сло́вом і ра́зумом, ки́їми пі́сньми восхвалю́ вас, о, отці́, А́нгелом равноче́стнії, оба́че побужден усе́рдієм і любо́вію я́же к вам, дерза́ю вінча́ти вас си́ми недосто́йними мої́ми похвала́ми:","Ра́дуйся, Зиноне, посто́м і мно́гими іни́ми по́двиги і́ночеськаго житія́ сві́тло просія́вий;","ра́дуйся, смире́нієм, кро́тостію і послуша́нієм зе́млю кро́тких наслі́дивий.","Ра́дуйся, Григо́ріє, я́ко зе́лієм, їм же пита́лся, здра́віє боля́щим преподавий.","Ра́дуйся, Іпа́тіє, святи́м отце́м в болі́зніх со всеусердієм послужи́вий і за сія́ благода́ть Ду́ха ісціля́ти неду́ги восприя́вий.","Ра́дуйтеся, отці́ преподо́бнії, їх же пречестні́ї глави́ во здра́віє душ і тіле́с на́ших ми́ро істоча́ють;","ра́дуйтеся, їх же пресвяті́ї душі́ в неізрече́нній сла́ві Бо́жию престо́лу предстоя́ть.","Ра́дуйся, Мойсе́є, я́ко моли́твами, посто́м і вери́гами стра́сті умертви́л єси́.","Ра́дуйся, Іо́сифе, я́ко врата́ми смире́ннаго і усе́рднаго послуша́нія во ві́чний поко́й вшел єси́.","Ра́дуйся, Па́вле, я́ко ніколи́же в пра́здности вре́мене препроводи́л єси́, ті́мже со труждающимися і обремененними водвори́лся єси́.","Ра́дуйся, Сисо́є, я́ко чрезмерними по́двигами по́стничества не то́кмо челові́ков, но і А́нгелов удиви́л єси́.","Ра́дуйтеся, Лео́нтіє і Геронтіє, я́ко із младе́нчества Христа́ возлюби́ли єсте́;","ра́дуйтеся, я́ко во отро́честві в по́двизіх наста́вником соравнялися єсте́.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мно́гих, всіх обраще́нія і спасе́нія ми́лостивно іща́й премилосердний Христо́с Бог наш, други́х вас отце́в Єги́пта, Фиваї́ди і Палести́ни, - Русі́ прояви́, да ва́ми мно́гих вразуми́ть і пока́жеть ва́шим житіє́м путь ко спасе́нію, в чем ви потруждшеся, до́брі преуспеєте, в неві́дінії су́щих Єва́нгельстій і́стині нелі́ностно поуча́я, к правові́рію приведо́сте і ко хране́нію Бо́жиїх за́повідей і богоуго́дному і чи́стому житію́ сло́вом і ді́лом непреста́нно возбуждасте, Бо́гу Помо́щнику піснь пою́ще: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю тве́рдою і огражде́нієм крі́пким бу́дете нам, всехва́льнії отці́, с те́плою ві́рою, усе́рдієм і любо́вію к вам прибегающим, ограждающе нас проти́ву чу́вственних і ми́сленних враго́в на́ших, да не убої́мся їх, но да побіжда́їм ті́ї моли́твами ва́шими ко Христу́ Бо́гу, зову́ще с благодаре́нієм к вам си́це:","Ра́дуйся, Не́сторе, ни́жняя презрі́вий, ви́шняя же возлюби́вий;","ра́дуйся, я́ко пред кончи́ною самого́ Го́спода Ісу́са Христа́ со А́нгели ви́діти сподо́бивийся.","Ра́дуйся, Фео́доре, я́ко хране́ніє усто́м свої́м положи́л єси́.","Ра́дуйся, Па́мво іспові́дниче, бо́ги язи́чеськия проклявий, і́м'я же Го́спода небесе́ і землі́ іспові́давий.","Ра́дуйся, Софро́ніє, затво́ром крі́пким і желі́зом ті́ло стеснивий, душе́ю же і умо́м со псалмопі́нієм к небесі́ непреста́нно паривий.","Ра́дуйся, Панкратіє, я́ко боля́щим благода́тію Ду́ха Свята́го ісціле́нія істоча́єши.","Ра́дуйся, Анто́ніє, я́ко ду́хи лука́вия от приходя́щих к тебі́ с ві́рою проганяєши.","Ра́дуйся, Марда́ріє, нищети́ і нестяжа́нія люби́телю.","Ра́дуйся, Аммо́не, дре́внім отце́м святи́м в по́двизіх всеусе́рдний подража́телю.","Ра́дуйся, Піоре, стра́сті тіле́сния огне́м воздержа́нія попали́вий.","Ра́дуйся, Марти́ріє, доброді́тельним нра́вом ду́шу просвіти́вий.","Ра́дуйся, Ру́фе, во о́браз житіє́м свої́м постникам і подви́жникам би́вий.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє хвале́бноє побіжда́ється мно́жеством пресла́вних ва́ших по́двигов і трудо́в чрезмерних, превосходя́щих житіє́ челові́чеськоє, но а́нгельському подо́бноє: і похвала́м от А́нгел па́че, а не от челові́к вам приноси́мим би́ти досто́яше, оба́че усе́рдноє на́ше ви́дяще проізволе́ніє, с ві́рою і любо́вію приноси́моє на́ми приймі́те пі́ніє і іспросі́те нам оставле́ніє гріхо́в, і да в добро́м ісправле́нії і покая́нії сконча́єм вре́менноє сіє́ житіє́ на́ше, во ві́чном же да сподо́бимся моли́твами ва́шими пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ вам незаходи́мий возсія́ возненавидевшим страсте́й тьму, уго́дниці Бо́жії пресла́внії: весе́ліє же несконча́ємоє восприя́ вас, до́брий по́двиг со тща́нієм скончавшим. Ті́мже предстоя́ще престо́лу Христо́ву, помина́йте нас пою́щих вам сія́:","Ра́дуйся, Євфроси́ніє, го́рняго Ієрусали́ма дши пречестна́я;","ра́дуйся, до́льняго Ієрусали́ма, на́шею гра́да Ки́єва, ма́ти пресві́тлая.","Ра́дуйся, Іулія́не, ді́во, лиліє прекра́сная, проізростшая в земно́м Христо́вом са́де;","ра́дуйся, процві́тшая в небе́сном Єго́ вертогра́ді.","Ра́дуйся, Мака́ріє священному́чениче, я́ко до сме́рти ві́рен па́стир бил єси́;","ра́дуйся, я́ко пре́жде, не́же прия́ти ті престо́л на землі́ чу́вственний, на престо́ли ми́сленниє предпослался єси́.","Ра́дуйся, Кассія́не, затво́рниче ди́вний.","Ра́дуйся, Арсе́ніє, я́ко за богоугодниє временниє, ві́чно от Христа́ упокоєн єси́.","Ра́дуйся, Євфи́міє, я́ко поще́нія ра́ди твоєго́ вели́каго і немо́лчнаго славосло́вія Бо́гу, ра́йських сла́достей насища́єшися і со А́нгели поє́ши.","Ра́дуйся, Веніями́не, я́ко разда́в імі́нія твоя́, на ло́ні Авраа́ма почива́єши.","Ра́дуйся, Ти́те, я́ко земна́го царя́ во́їнство оста́вль, да Небе́сному Царю́ хра́брійший во́їн бу́деши.","Ра́дуйся, Ахило, я́ко от ю́ности расп'я́лся єси́ житію́ і страсте́м, да распе́ншагося во́лею на кресті́ Христа́ приобря́щеши.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 12","ps":["Благода́тію Всеми́лостиваго і Всеще́драго Бо́га житіє́м равноа́нгельним пожи́сте, отці́ духоноснії, чудеса́ мно́гі соді́ясте, храм Пречи́стій Госпоже́ Ді́ві Богоро́диці пречу́ден созда́сте і я́ко неві́сту прекра́сну зла́том, сребро́м і ка́менієм многоці́нним украси́сте, в онь же лю́діє от всея́ Вселе́нния приходя́ще, восхваля́ють о вас Христа́ Бо́га, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ва́ше безмо́лвноє житіє́, похваля́єм по́двиги ва́ша - пост, моли́тви, сле́зи, колінопреклоне́нія, всено́щния бді́нія, пло́ті умервщленія, ду́ха сокруше́ніє, долулеганія, смире́ніє, кро́тость, молча́ніє, терпі́ніє, нищету́, нестяжа́ніє і вся та чтим, я́же любві́ ра́ди Христо́ви под'ясте, та́ко воспіва́юще:","Ра́дуйтеся, Паї́сіє і Мерку́ріє, я́ко в неразлу́чній жи́зні і єдиноду́шній любві́ бра́тськой пожи́сте на землі́;","ра́дуйтеся, я́ко єди́ною жи́знію і ра́достію вку́пі наслажда́єтеся со Христо́м і на небесі́.","Ра́дуйся, Мака́ріє, я́ко Самуї́л в юном возрасте́ в служе́ніє Го́споду предназначен бил єси́.","Ра́дуйся, Пи́мене, я́ко пшени́ця гумна́ Христо́ва, в жи́тници небе́сния предопреділе́н єси́.","Ра́дуйся, Силуа́не, я́ко на крилі́х поста́ і моли́тви к Бо́гу возлеті́л єси́.","Ра́дуйся, Агафо́не, я́ко на плещіх доброді́телей висо́ких в го́рния под'ять єси́.","Ра́дуйся, Заха́ріє, я́ко бісо́м стра́шен бил єси́, А́нгелом же собесі́дник яви́лся єси́, с ни́ми же і ко престо́лу Тро́йці Пресвяти́я воспари́л єси́.","Ра́дуйся, Ігна́тіє, кня́же пресві́тлий пеще́рнаго гра́да;","ра́дуйся, па́стирю преподо́бний богоізбра́ннаго стада́.","Ра́дуйся, му́чениче младе́нче, я́ко за Христа́ от І́рода бесчеловечнаго ча́шу сме́рті іспи́вий;","ра́дуйся, зе́млю Восто́ка кро́вію освяти́вий і на́шу страну́ прише́ствієм твої́м благослови́вий.","Ра́дуйся, Лонгине, я́ко путе́м у́зьким пра́во ше́ствовал єси́, їм же і рая́ Бо́жия доспі́л єси́.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 13","ps":["О, Всеблаже́ннії і вся́ких похвале́ній превишнії, преподо́бнії отці́ на́ші Пече́рстії, приймі́те сіє́ ма́лоє вам приноше́ніє, я́коже і Госпо́дь прия́т дві ле́пти вдови́ці: і не возгнушайтеся моле́нієм на́шим, я́ко і Христо́с не возгнуша́лся лобза́нія блудни́ці, і сподо́біте нас хода́тайством ва́шим ко Го́споду в добро́м ісправле́нії і покая́нії сконча́ти житіє́ сіє́ і с моли́твою во усті́х, в се́рдці і душе́ отьити от сея́ вре́менния жи́зні к ві́чній, і предста́ти престо́лу Всеви́шняго, іді́же ви предстоїте́ і со Арха́нгели і А́нгели і со всі́ми святи́ми, піснь пою́ще: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Ангелоподо́бнаго возжелаєте житія́, отці́ богому́дрії, мирськи́я многом'яте́жния молви́ ізбіго́сте, в пеще́рах ті́сних і те́мних всели́стеся, іді́же труди́ ве́лії і по́двиги под'ясте, да Христа́ приобря́щете; ті́мже і сли́шіте от немощни́х нас і грі́шних сія́ піснопі́нія:","Ра́дуйся, Анто́ніє, воздержа́нія, смире́нія, послуша́нія і безмо́лвія зерца́ло;","ра́дуйся, ві́ри правосла́вния крі́пкоє забра́ло.","Ра́дуйся, Феодо́сіє, мона́шеськая похвало́;","ра́дуйся, оби́телі твоєя́ велелі́пная сла́во.","Ра́дуйся, Михаї́ле, пе́рвий архіпа́стирю наш і учи́телю;","ра́дуйся, ві́ри Христо́вой усе́рдний насади́телю і ідолослуже́нія іскорени́телю.","Ра́дуйся, Про́хоре, чудотво́рче всеблаже́нний, хлі́би су́щими от би́лій і со́лію от пе́пла, гла́дом тающия лю́ди пропитавий.","Ра́дуйся, Іоа́нне, посто́м неізрече́нним просія́вий.","Ра́дуйтеся, Фео́доре і Васи́ліє, во вре́менній жи́зні взаїмним любве́ Христо́ві сою́зом себі́ связавшії;","ра́дуйтеся, от користолюбиваго кня́зя Мстисла́ва крі́пко пострада́вшії.","Ра́дуйтеся, я́ко і по блаже́нній кончи́ні ва́шей во єди́ній ра́ці дружелюбно почієте;","ра́дуйтеся, я́ко во єди́нім часі́ к престо́лу Бо́жию предста́сте.","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Кондак 1","ps":["Богоізбра́нний по́лче і ли́че богокра́сний, преподо́бнії отці́ на́ші Пече́рстії, чуде́с мно́гих істо́чници, і́ночеськаго, по́стничеськаго общежи́тія на Русі́ первоучи́телі і наста́вници, сіє́ вам от душе́внаго жела́нія дерза́єм принести́ похва́льноє пі́ніє. Ви же, я́ко іму́щи ве́ліє дерзнове́ніє к подвигополо́жнику Христу́ Бо́гу на́шему, молі́теся Єму́, мо́лим ви, от вся́ких бід і зол нам ізба́витися, да с благодаре́нієм зове́м вам:","Ра́дуйтеся, всі преподо́бнії отці́ на́ші Пече́рстії, всеми́рнії світи́льници, великії і пресла́внії чудотво́рці."]},{"h":"Молитва","ps":["Преподо́бнії і богоно́снії отці́ на́ші Анто́ніє і Феодо́сіє, і всі преподо́бнії Пече́рстії, світи́ла земна́я пресві́тлая, от те́мних міст пеще́рних в землі́ Ру́ськой сла́вно просія́вшії, і сію́ мно́гими світоза́рними ангелонра́внаго ва́шего житія́ звізда́ми онебеси́вшії, всю же Вселе́нную висо́ких доброді́телей світлостьми́ і чуде́с боже́ственних блиста́ньми удиви́вшії, і ни́ні сме́ртним за́падом пло́тськи на вре́м'я во гроб заше́дше, душа́ми со Христо́м Со́лнцем Пра́вди, су́ще пра́ведници просвіща́єтеся, я́ко со́лнце во Ца́рствії Небе́снім: іді́же моли́твенная ва́ша к Бо́гу Сві́ту лучи́ о Оте́честві своє́м простира́юще, не забу́діте і нас, всегда́шнія своя́ моли́твенники, в нощі́ страсте́й і скорбе́й пребива́ющия, сви́ше благода́тними призира́ти осія́нії; я́ко да во сві́ті доброді́тельнаго ва́шего житія́ пра́во ходя́ще, сподо́бимся зрі́ти світ неприкоснове́нния сла́ви Бо́жия, хва́ляще Єго́ ку́пно с ва́ми в несконча́ємия ві́ки. Амі́нь."]},{"h":"Інша молитва","ps":["О, уго́дниці Христо́ви, преподо́бнії отці́ на́ші Анто́ніє і Феодо́сіє і всі святі́ї Кі́єво-Пече́рстії, світи́льници пресветлиє, свя́тостію і́ночеськаго житія́ пе́рвиє просіявшиє на землі́ Украї́нській, покрови́телі гра́да Ки́єва і всего́ оте́чества на́шего! К вам, молитвенникам те́плим і предстателям непости́дним, усе́рдно притека́єм, в ну́ждах і ско́рб'ях на́ших утіше́нія і по́мощі прося́ще. Помозі́те нам, раба́м Бо́жиїм (імена́), засту́пници на́ші! Утверді́те нас во ві́рі святі́й, сохрані́те Це́рков Бо́жию от па́губних єресе́й і раско́лов, научі́те нас всегда́ твори́ти за́повіді Бо́жия і вся преда́нія церко́вная, от оте́ць нам запові́данная, бу́діте нам благосердиє отці́ і теплиє моли́твенниці, я́ко да просла́вим і́м'я Живонача́льния Тро́йці, Отця́ і Си́на і Свята́го Ду́ха во ві́ки. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Єгда́ снидо́сте во гро́би / і самі́х себе́ заключи́сте, / тогда́, стра́сті умертви́вше плотські́я, / спогребо́стеся Христу́, Богоно́снії, / і дия́вольськия в подзе́мних разруши́сте огра́ди. // Сего́ ра́ди А́нгели вінці́ с Небе́с вам подаю́ть."]},{"h":"Кондак, глас 2","ps":["Лик по́стничеський собра́ся у́мні, / ми́сленнима зря́ще очи́ма, / прийді́те, лю́діє, хвала́ми почти́м, / і, покланя́ющеся моще́м їх, / любо́вния принесе́м да́ри, / ті́ї бо суть к Бо́гу хода́таї // і моли́твенниці о душа́х на́ших."]},{"h":"Величання","ps":["Велича́єм вас, / преподо́бнії отці́ на́ші Пече́рстії, / і чтим святу́ю па́м'ять ва́шу, / ви бо мо́лите о нас // Христа́, Бо́га на́шего."]}],"notes":[]}];
export default D;
